AF_ADD_PACK("BC", [{"id":"bc-pwd-designation","needsPractitioner":true,"name":"Persons with Disabilities (PWD) Designation","level":"British Columbia","category":"Money","amount":"No direct payment on its own. The designation is required to access disability assistance, and a recipient with it may be eligible for higher rates, health supplements, an annual earnings exemption and a bus pass.","summary":"BC's disability status for adults 18 and over with a severe impairment expected to last at least two years. You need it to get disability assistance.","requires":["bc","age18plus","dailyLivingLimit","bcPwdMedical","bcPwdDesignationFinancial" ],"eligibility":{"mode":"all","items":["You are 18 or older.","You are financially eligible, or likely to be within six months.","You have a severe mental or physical impairment likely to continue for at least two years that significantly restricts daily living and requires an assistive device, the significant help or supervision of another person, or the services of an assistance animal." ]},"requiresNote":"You are 18 or older; are financially eligible or likely to be within six months; and have a severe mental or physical impairment likely to continue for at least two years that significantly restricts daily living and requires an assistive device, the significant help or supervision of another person, or the services of an assistance animal.","note":"The test is about what you can do, not your diagnosis. The impairment must directly and significantly restrict your ability to do daily living activities. And you must need an assistive device, the significant help or supervision of another person, or the services of an assistance animal.","applyText":"Start on My Self Serve","applyUrl":"https://myselfserve.gov.bc.ca/","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/pwd-designation-and-application/designation-application","detail":{"about":"The standard application is form HR2883. Five prescribed classes can use the prescribed-class application (HR3642) instead: people enrolled in BC PharmaCare Plan P (palliative care); people the Ministry of Children and Family Development has determined to be eligible for the At Home Program; people Community Living BC has determined to be eligible for its supports and services; people determined as disabled by the Government of Canada and eligible for the CPP Disability Benefit or Post-Retirement Disability Benefit; and people designated as a Person with Disabilities by Indigenous Services Canada in the BC region. Prescribed-class applicants must still meet all other eligibility requirements (identification, financial, residency, etc.).","aboutList":{"lead":"The standard application is form HR2883. Five prescribed classes can use the prescribed-class application (HR3642) instead:","items":["People enrolled in BC PharmaCare Plan P (palliative care).","People the Ministry of Children and Family Development has determined to be eligible for the At Home Program.","People Community Living BC has determined to be eligible for its supports and services.","People determined as disabled by the Government of Canada and eligible for the CPP Disability Benefit or Post-Retirement Disability Benefit.","People designated as a Person with Disabilities by Indigenous Services Canada in the BC region.","Prescribed-class applicants must still meet all other eligibility requirements (identification, financial, residency, etc.)." ]},"steps":["Start an assistance application through My Self Serve so the ministry can first check financial eligibility","Ask the ministry for the PWD designation application (HR2883) after you start the assistance application","Complete the applicant section, then have a doctor or nurse practitioner complete the medical report","Have a medical practitioner, nurse practitioner or other prescribed professional complete the assessor report","Submit all sections and keep a copy; respond if the ministry asks for more information" ],"documents":["Identification, income, asset and shelter information for the assistance application","PWD designation application HR2883","Medical and functional information describing how the impairment restricts daily living and what help or supervision is required" ],"tips":["You can start the PWD application at age 17 and a half. Disability assistance cannot begin before age 18.","If you are in a prescribed class, ask whether the prescribed-class HR3642 application applies instead of the standard application","The ministry gives the HR2883 application to people who intend to apply for disability assistance. It is not given out only so people can qualify for other programs.","Ask each professional to describe your functional restrictions and support needs, not only the diagnosis" ],"time":"The ministry does not publish one guaranteed decision time","phone":"1-866-866-0800"}},{"id":"bc-fair-pharmacare","name":"Fair PharmaCare","level":"British Columbia","category":"Health","amount":"Income-based drug coverage. Family net income of $13,750 or less: PharmaCare pays 100 percent of eligible costs from the first prescription. Up to $30,000: no deductible, with a family maximum between $100 and $800. Above that a deductible applies, then PharmaCare pays 70 percent, and 100 percent once you reach your family maximum.","summary":"BC's main drug plan for anyone enrolled in MSP. It pays a share of your eligible prescriptions based on family net income. The lower your income, the sooner and the more it pays. Free to register.","requires":["bc","bcMsp" ],"amountTiers":{"caption":"What PharmaCare pays by family net income","headers":["Family net income","What PharmaCare pays" ],"rows":[["$13,750 or less","100% of eligible costs from the first prescription" ],["Up to $30,000","No deductible, with a family maximum between $100 and $800" ],["Above $30,000","A deductible applies, then PharmaCare pays 70%, and 100% once you reach your family maximum" ] ]},"requiresNote":"Any MSP-enrolled BC resident or family can register. Your assistance level is scaled to family net income from two years earlier, verified with the CRA.","note":"Return the consent form within 30 days of registering. If you do not, temporary coverage ends and your family's deductible is set at $10,000. Also, if you are moving into a long-term care facility, ask whether it is enrolled in PharmaCare Plan B before you move in. Plan B gives permanent residents of enrolled facilities 100% coverage of eligible prescription drugs and pharmacy services. It also covers eligible medical supplies up to a maximum. It is automatic, with no application. But not all facilities are enrolled. It does not apply to assisted-living, extended-care, acute-care or temporary respite or hospice stays.","applyText":"Register online","applyUrl":"https://my.gov.bc.ca/ahdc","source":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover/fair-pharmacare-plan","detail":{"about":"Assistance is tied to family net income from two years prior and coverage applies automatically at the pharmacy counter. After a family meets its deductible PharmaCare pays 70% of eligible costs, or 75% if a family member was born before 1940. After a family reaches its family maximum, Fair PharmaCare pays 100% of eligible costs for the rest of the year.","aboutList":{"lead":"Assistance is tied to family net income from two years prior and coverage applies automatically at the pharmacy counter.","items":["After a family meets its deductible PharmaCare pays 70% of eligible costs, or 75% if a family member was born before 1940.","After a family reaches its family maximum, Fair PharmaCare pays 100% of eligible costs for the rest of the year." ]},"steps":["Gather the Personal Health Number for every family member, Social Insurance Numbers for adults, and the adults' tax information from two years ago","Register online, or call Health Insurance BC if online registration is not accessible to you","Use the temporary coverage that begins the same day while income verification is pending","Sign and return the CRA consent form within 30 days so temporary coverage does not end","Check your registration status online or call if a pharmacy cannot see the coverage" ],"documents":["Personal Health Number for every family member","Social Insurance Number for each adult","Line 23600 from each adult's Notice of Assessment from two years ago","Line 12500 Registered Disability Savings Plan income, if applicable" ],"tips":["Registration is free and temporary coverage begins the same day","The CRA consent deadline matters: return it within 30 days","If family income has dropped substantially, ask PharmaCare whether an income review is available","If you or a family member is moving into long-term care, ask whether the facility is registered with PharmaCare Plan B before moving in. Plan B covers 100% of eligible prescription drugs and pharmacy services for permanent residents of registered facilities. It also covers eligible medical supplies up to a maximum price set by PharmaCare. It starts automatically. But not every facility is registered.","Plan B does not apply to extended-care, acute-care, multi-level or assisted-living facilities. It also does not apply to a short-term stay in a long-term care facility, such as a temporary stay for respite care, hospice or palliative care.","Since March 1, 2026, PharmaCare's National Pharmacare plan, Plan NP, has covered many diabetes medications, contraceptives and menopausal hormone therapy at no cost to you. Coverage is automatic at the pharmacy. There is nothing to register for and no receipts to submit. You must be a B.C. resident enrolled in MSP, and the prescription must be dispensed in B.C.","Plan NP prescriptions do not count towards your Fair PharmaCare deductible or family maximum. So they cost you nothing, but they also do not move you closer to meeting your deductible.","The Plan NP diabetes list includes insulins, metformin, glyburide, gliclazide, dapagliflozin and empagliflozin, and combinations of them. A few others need Special Authority approval before a pharmacy can fill them. These include saxagliptin, linagliptin and pioglitazone. Ask your prescriber.","On April 1, 2026, Plan NP expanded to cover certain diabetes-related supplies and devices.","PharmaCare also covers the full cost of nicotine gum, lozenges and patches for one continuous course of up to 12 weeks (84 days) in a calendar year. The allowance resets on January 1. You and the pharmacist both sign a declaration form at the pharmacy, so there is nothing to apply for in advance. You must be enrolled in MSP, but you do not need to be signed up for Fair PharmaCare. Certain prescription stop-smoking drugs are covered instead through Fair PharmaCare or through Plans B, C, G or W." ],"time":"Temporary coverage begins the day you register; income verification follows","phone":"1-800-663-7100"}},{"id":"bc-msp-supplementary-benefits","name":"MSP Supplementary Benefits","level":"British Columbia","category":"Health","amount":"$23 per visit toward acupuncture, chiropractic, massage therapy, naturopathy, physical therapy or non-surgical podiatry, up to a combined 10 visits each calendar year","summary":"Partial MSP coverage for visits to six kinds of practitioners. It is for people who may be eligible, including lower-income B.C. residents and people enroled with MSP through the At Home Program or as Mental Health Clients. Families deemed eligible may also be eligible for the Healthy Kids Program.","requires":["bc","bcMsp","bcSupplementaryBenefitsEligibility" ],"eligibility":{"mode":"all","items":["You (and your spouse, if you have one) are enrolled in MSP.","You may be eligible through your income or through one of the other groups the ministry lists.","You live in B.C., have lived in Canada as a citizen or permanent resident for at least the last 12 months before applying, and are not exempt from paying income tax under another act." ],"note":{"lead":"Those who may be eligible include:","items":["Adjusted net income last year of less than $42,000 (your family may qualify).","Income Assistance recipients.","Convention refugees.","Inmates of B.C. Correctional Facilities.","People enroled with MSP through the At Home Program.","Residents of long term care facilities receiving the Guaranteed Income Supplement.","People enroled with MSP as Mental Health Clients.","First Nations individuals with valid B.C. Medical Plan coverage through the First Nations Health Authority." ],"after":"Adjusted net income is last year's net income confirmed by CRA — combined with your spouse's if you have one — after certain deductions. There is no cost to apply. Coverage does not apply to treatment received outside British Columbia."}},"requiresNote":"You must be enroled in MSP, and your spouse too if you have one, before Supplementary Benefits can be approved. You may be eligible through your income or through one of the other groups the ministry lists. You live in B.C., have lived in Canada as a citizen or permanent resident for at least the last 12 months before applying, and are not exempt from paying income tax under another act. Those who may be eligible include:\n- Adjusted net income last year of less than $42,000 (your family may qualify).\n- Income Assistance recipients.\n- Convention refugees.\n- Inmates of B.C. Correctional Facilities.\n- People enroled with MSP through the At Home Program.\n- Residents of long term care facilities receiving the Guaranteed Income Supplement.\n- People enroled with MSP as Mental Health Clients.\n- First Nations individuals with valid B.C. Medical Plan coverage through the First Nations Health Authority.\n Adjusted net income is last year's net income confirmed by CRA — combined with your spouse's if you have one — after certain deductions. There is no cost to apply. Coverage does not apply to treatment received outside British Columbia.","note":"The $23 is a contribution, not the full fee — many practitioners are opted out of MSP and are allowed to charge more, and you pay the difference. Ask what the visit costs and what MSP covers before you book. The 10 visits are a combined limit across all six service types, not 10 of each.","applyText":"Apply for Supplementary Benefits","applyUrl":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/msp/bc-residents/benefits/services-covered-by-msp/supplementary-benefits","source":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/msp/bc-residents/benefits/services-covered-by-msp/supplementary-benefits","detail":{"about":"MSP contributes $23 per visit for a combined annual limit of 10 visits each calendar year, for acupuncture, chiropractic, massage therapy, naturopathy, physical therapy and non-surgical podiatry from approved providers. Eligibility is assessed from last year's net income as confirmed by the Canada Revenue Agency, or the combined net income of you and your spouse, less certain deductions. The figure that remains is called adjusted net income, and if it is less than $42,000 your family may qualify. People enroled with MSP through the At Home Program, and people enroled with MSP as Mental Health Clients, may also be eligible. Applying is free, and once approved you generally do not need to reapply while you stay eligible for MSP, because income is re-verified each year automatically. MSP does not cover supplementary benefit services received outside the province.","aboutList":{"lead":"MSP contributes $23 per visit for a combined annual limit of 10 visits each calendar year, for acupuncture, chiropractic, massage therapy, naturopathy, physical therapy and non-surgical podiatry from approved providers.","items":["Eligibility is assessed from last year's net income as confirmed by the Canada Revenue Agency, or the combined net income of you and your spouse, less certain deductions.","The figure that remains is called adjusted net income, and if it is less than $42,000 your family may qualify.","People enroled with MSP through the At Home Program, and people enroled with MSP as Mental Health Clients, may also be eligible.","Applying is free, and once approved you generally do not need to reapply while you stay eligible for MSP, because income is re-verified each year automatically.","MSP does not cover supplementary benefit services received outside the province." ]},"steps":["Make sure MSP enrolment is complete for you and your spouse if you have one","Complete the BC Application for Health and Drug Coverage, which applies for MSP enrolment, Supplementary Benefits and Fair PharmaCare on one form","Give CRA permission on the application to release your Notice of Assessment so your income can be verified","If you are newly eligible for MSP, book a B.C. driver licensing office appointment to get your Photo BC Services Card" ],"documents":["The BC Application for Health and Drug Coverage","Your and your spouse's CRA Notice of Assessment or Reassessment information: on the application you give CRA permission to release it; if you apply by mail, include copies with the form","Your Personal Health Number if you already have one" ],"tips":["The 10 visits are a combined limit across all six service types, so they run down together","$23 is a contribution, not the full fee. Ask the practitioner what you will owe before booking.","Keep filing your taxes every year. MSP checks your income automatically from your CRA return, and your eligibility may be affected if you do not file.","Tell MSP if you marry or start living in a marriage-like relationship, because that changes how your income is assessed","Families deemed eligible for Supplementary Benefits may be eligible for basic dental treatment, optical care and hearing assistance through the Healthy Kids Program" ]}},{"id":"bc-pharmacare-plan-c","name":"PharmaCare Plan C (Income & Disability Assistance)","level":"British Columbia","category":"Health","amount":"100% of the cost of eligible drugs and dispensing fees","summary":"Automatic drug coverage from the first dollar if you are on BC income, disability or hardship assistance. PharmaCare pays the full cost of eligible drugs and dispensing fees at the pharmacy counter.","requires":["bc","bcAssistanceStatus" ],"requiresNote":"You are receiving income assistance, disability assistance, hardship assistance or Medical Services Only through the Ministry of Social Development and Poverty Reduction; or you are a child or youth in the care of the Ministry of Children and Family Development or of an Indigenous Governing Body; or you arrived in BC through the Canada-Ukraine authorization for emergency travel.","note":"You cannot be charged for medications or dispensing fees covered by Plan C. Medical devices and supplies are the exception. They are exempt from PharmaCare's Full Payment Policy, so a pharmacy or device provider may charge you above the maximum eligible cost.","applyText":"Automatic — learn more","applyUrl":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover/plan-c","source":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover/plan-c","detail":{"about":"Enrolment in those programs automatically enrols you in Plan C — there is no separate application. It also covers prostheses and orthoses including offloading devices for diabetic foot ulcers, ostomy supplies, and insulin and insulin pumps (insulin pumps need an approved Special Authority request from a doctor).","steps":["Confirm that your qualifying income, disability, hardship, care or protected status is active with the responsible ministry","Give the pharmacy your BC Services Card or Personal Health Number so it can check Plan C","If the status is active but the pharmacy cannot see Plan C, ask the ministry or Health Insurance BC to correct the enrolment","If you are eligible for Plan C but not yet enrolled and need a prescription urgently, ask the prescriber or pharmacist whether they can request emergency Plan C coverage, which provides up to 48 hours of PharmaCare coverage" ],"documents":["BC Services Card or Personal Health Number","Any recent ministry notice showing the qualifying assistance or care status" ],"tips":["There is no separate Plan C application","Register for Fair PharmaCare as well, so coverage can continue if your assistance status changes","Ask the pharmacy about any amount before you pay. Covered drugs and dispensing fees should not be charged under Plan C." ],"time":"Automatic when the qualifying ministry status is active","phone":"1-800-663-7100"}},{"id":"bc-pharmacare-plan-g","name":"PharmaCare Plan G (Psychiatric Medications)","level":"British Columbia","category":"Health","amount":"100% of eligible costs for covered psychiatric medications","requires":["bc","psychiatricMedicationCandidate","planGClinicalAndFinancialNeed" ],"eligibility":{"mode":"all","items":["You have both clinical and financial need.","Your physician or nurse practitioner confirms the clinical side, together with your local mental health and substance use location, or the Child and Youth Mental Health team.","Your annual income is lower than $42,000." ],"note":"If you are eligible, the prescriber submits the Application for PharmaCare Plan G form on your behalf — there is nothing for you to file. The plan covers certain psychiatric medications rather than all of them."},"summary":"Full coverage of certain psychiatric medications for B.C. residents of any age who have both clinical and financial need. Your prescriber applies for you, and you must renew coverage every year.","note":"Coverage lasts up to one year and stops unless a new application is submitted. Know your renewal date. See a prescriber about a month before it, so your coverage does not lapse while you are still taking the medication.","requiresNote":"You must have both clinical and financial need. Your physician or nurse practitioner confirms the clinical side together with your local mental health and substance use location, or the Child and Youth Mental Health team. The financial test is an annual income lower than $42,000. If you are eligible, the prescriber submits the Application for PharmaCare Plan G form on your behalf — there is nothing for you to file. The plan covers certain psychiatric medications rather than all of them.","applyText":"See how to apply for Plan G","applyUrl":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover#plang","source":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover#plang","detail":{"about":"Plan G pays 100% of eligible costs for certain psychiatric medications, for B.C. residents of any age who have both clinical and financial need. The province describes the financial test as an annual income lower than $42,000. Eligibility is confirmed by your physician or nurse practitioner together with your local mental health and substance use location, or the Child and Youth Mental Health team, and the prescriber then submits the Application for PharmaCare Plan G form for you. Coverage runs for up to one year and must be renewed if you still need it. The province advises knowing your renewal date and seeing a healthcare provider about a month ahead to submit the new application.","aboutList":{"lead":"Plan G pays 100% of eligible costs for certain psychiatric medications, for B.C. residents of any age who have both clinical and financial need.","items":["The province describes the financial test as an annual income lower than $42,000.","Eligibility is confirmed by your physician or nurse practitioner together with your local mental health and substance use location, or the Child and Youth Mental Health team, and the prescriber then submits the Application for PharmaCare Plan G form for you.","Coverage runs for up to one year and must be renewed if you still need it.","The province advises knowing your renewal date and seeing a healthcare provider about a month ahead to submit the new application." ]},"steps":["Tell your physician or nurse practitioner that you have both clinical and financial need and ask about Plan G","They confirm eligibility with your local mental health and substance use location, or the Child and Youth Mental Health team","The prescriber submits the Application for PharmaCare Plan G form on your behalf","Write down your renewal date and book an appointment about a month before it to submit a new application" ],"documents":["Nothing for you to submit — your prescriber completes and sends the Application for PharmaCare Plan G form","Bring anything your prescriber asks for to show income if they need it" ],"tips":["Renewal is what catches people out. Coverage lasts up to 1 year and must be renewed. Put the date somewhere you will see it, and go in a month early.","The plan covers certain psychiatric medications, not every drug. Ask your prescriber or pharmacist whether your medication is on Plan G before you rely on it.","Your prescriber confirms eligibility together with your local mental health and substance use location, or the Child and Youth Mental Health team. Plan G covers certain psychiatric medications, so ask whether a specific medication is on the plan.","Plan G's $42,000 test is based on annual income. This is worded differently from the adjusted net income test used for MSP Supplementary Benefits. Qualifying for one does not automatically mean qualifying for the other." ]}},{"id":"bc-pharmacare-plan-p","eligibility":{"mode":"all","items":["This is for B.C. residents of any age who have reached the end stage of a life-threatening disease or illness and who wish to receive palliative care at home." ],"note":"\"Home\" means wherever the person is living — their own home, a family member's or friend's home, a supportive or assisted living residence, or a hospice unit in a long-term care facility, such as a community hospice bed not covered under PharmaCare Plan B. Registration is made by a physician or nurse practitioner, not by the patient or family."},"name":"PharmaCare Plan P (BC Palliative Care Benefits)","level":"British Columbia","category":"Health","amount":"100% of eligible costs for medications on the Plan P formulary","requires":["bc","palliativeCandidateCondition","planPRegistration" ],"summary":"Full coverage of palliative care medications for B.C. residents of any age who have reached the end stage of a life-threatening illness and want to be cared for at home. A doctor or nurse practitioner registers the patient. The family has nothing to submit.","note":"The patient and family do not apply. A physician or nurse practitioner sends one registration form. That same form notifies both PharmaCare and the local health authority. If you want palliative care at home, talk to the doctor or nurse practitioner.","requiresNote":"This is for B.C. residents of any age who have reached the end stage of a life-threatening disease or illness and who wish to receive palliative care at home. \"Home\" means wherever the person is living — their own home, a family member's or friend's home, a supportive or assisted living residence, or a hospice unit in a long-term care facility, such as a community hospice bed not covered under PharmaCare Plan B. Registration is made by a physician or nurse practitioner, not by the patient or family.","applyText":"Read the BC Palliative Care Benefits information sheet","applyUrl":"https://www2.gov.bc.ca/gov/content/health/practitioner-professional-resources/pharmacare/pharmacare-publications/patient-information-sheets#planp","source":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover#planp","detail":{"about":"Plan P covers 100% of eligible costs for medications used in palliative care that appear on the Plan P formulary. It is for B.C. residents of any age who have reached the end stage of a life-threatening disease or illness and who wish to receive palliative care at home, and \"home\" is read broadly: the person's own home, living with family or friends, a supportive or assisted living residence, or a hospice unit at a long-term care facility such as a community hospice bed that is not covered under PharmaCare Plan B. Medications are only part of it — eligible patients can also receive medical supplies and equipment through their local health authority. A physician or nurse practitioner submits the registration form to PharmaCare, and the single form notifies both PharmaCare and the health authority that the patient is eligible.","aboutList":{"lead":"Plan P covers 100% of eligible costs for medications used in palliative care that appear on the Plan P formulary.","items":["It is for B.C. residents of any age who have reached the end stage of a life-threatening disease or illness and who wish to receive palliative care at home, and \"home\" is read broadly: the person's own home, living with family or friends, a supportive or assisted living residence, or a hospice unit at a long-term care facility such as a community hospice bed that is not covered under PharmaCare Plan B.","Medications are only part of it — eligible patients can also receive medical supplies and equipment through their local health authority.","A physician or nurse practitioner submits the registration form to PharmaCare, and the single form notifies both PharmaCare and the health authority that the patient is eligible." ]},"steps":["Tell the doctor or nurse practitioner that palliative care at home is what the patient wants, and ask them to register the patient for BC Palliative Care Benefits","Ask the same clinician, or the local health authority, about the medical supplies and equipment that eligible patients can also receive through their local health authority","Ask for the BC Palliative Care Benefits patient information sheet, which is available in multiple languages" ],"documents":["Nothing for the patient or family to submit — the registration form is completed and sent by the physician or nurse practitioner" ],"tips":["The medications are covered at 100% when they are on the Plan P formulary. If something is not covered, ask the pharmacist to check the formulary.","Eligible patients can also receive supplies and equipment through the local health authority, so ask about them separately","A community hospice bed counts as home for this plan, as long as it is not already covered under PharmaCare Plan B","Registration in Plan P is also one of the prescribed routes to B.C.'s Persons with Disabilities designation. This can matter if disability assistance is being applied for at the same time." ]}},{"id":"bc-fnha-health-benefits","eligibility":{"mode":"all","items":["You must be a First Nations person with Indian status living in British Columbia." ],"note":"Infants up to 24 months are covered if at least one parent is eligible. You may not qualify if you already have coverage through a treaty and land claims agreement, or through certain First Nations funding arrangements with a government that B.C. has identified. The pharmacy coverage, which B.C. calls PharmaCare Plan W, also requires active Medical Services Plan enrolment."},"name":"First Nations Health Benefits (FNHA)","level":"British Columbia","category":"Health","amount":"100% of eligible prescriptions plus dental, vision, medical transportation, mental health and medical supplies","requires":["bc","firstNationsStatus" ],"summary":"Status First Nations people living in B.C. get health coverage through the First Nations Health Authority. It covers prescriptions, medical supplies and equipment, dental, vision, mental health and medical transportation. You enrol by phone with your status number.","note":"Plan W is not a separate application. B.C. states that you do not apply for Plan W and must be enrolled with FNHA to be covered by it. So enrolling with FNHA is the whole route. Some items, including insulin pumps, need special authorization and are not covered automatically.","requiresNote":"You must be a First Nations person with Indian status living in British Columbia. Infants up to 24 months are covered if at least one parent is eligible. You may not qualify if you already have coverage through a treaty and land claims agreement, or through certain First Nations funding arrangements with a government that B.C. has identified. The pharmacy coverage, which B.C. calls PharmaCare Plan W, also requires active Medical Services Plan enrolment.","applyText":"Open the official page on fnha.ca","applyUrl":"https://www.fnha.ca/benefits","source":"https://www2.gov.bc.ca/gov/content/health/health-drug-coverage/pharmacare-for-bc-residents/who-we-cover/first-nations-health-authority-clients","detail":{"about":"The FNHA Health Benefits program includes dental, medical supplies and equipment, medical transportation, mental health, pharmacy and vision care. The pharmacy part is PharmaCare Plan W, which covers 100 percent of eligible prescription costs, certain medical supplies, certain over-the-counter drugs, some natural health products, and pharmacy services. Covered medical supplies include diabetes supplies such as test strips, lancets and alcohol wipes, contraceptives, and ostomy supplies. Plan W requires active MSP coverage together with registered Indian status under the Indian Act, or being a child under two years old with at least one parent who is a registered Indian under the Indian Act.","aboutList":{"lead":"The FNHA Health Benefits program includes dental, medical supplies and equipment, medical transportation, mental health, pharmacy and vision care.","items":["The pharmacy part is PharmaCare Plan W, which covers 100 percent of eligible prescription costs, certain medical supplies, certain over-the-counter drugs, some natural health products, and pharmacy services.","Covered medical supplies include diabetes supplies such as test strips, lancets and alcohol wipes, contraceptives, and ostomy supplies.","Plan W requires active MSP coverage together with registered Indian status under the Indian Act, or being a child under two years old with at least one parent who is a registered Indian under the Indian Act." ]},"steps":["Have your status number ready","Call FNHA Health Benefits at 1-855-550-5454 to enrol, Monday to Friday, 8 a.m. to 4:30 p.m., excluding weekends and statutory holidays","If you are registering for the first time, you may also need to complete the Pacific Blue Cross Enrollment Application for Group Benefits and the Medical Services Plan Application for Enrollment","Email the completed forms to HealthBenefits@fnha.ca","To enrol a child, register the birth with B.C. within three months so the child gets a Personal Health Number, and register the child for Indian Status with Indigenous Services Canada" ],"documents":["Status number","Personal Health Number","Pacific Blue Cross Enrollment Application for Group Benefits, for first-time registration","Medical Services Plan Application for Enrollment, for first-time registration" ],"tips":["A child with a Personal Health Number can be covered under a parent's account until age two while waiting for their own status number. Once the child has their own status number, call 1-855-550-5454 to enrol them separately.","You enrol by phone, not through an online form. Plan the call inside the weekday office hours.","If you already have coverage through a treaty and land claims agreement, or through certain First Nations funding arrangements with a government, you may not qualify for this program." ]}},{"id":"bc-healthy-kids","name":"BC Healthy Kids Program","level":"British Columbia","category":"Health","amount":"Up to $2,000 in basic dental every two years per child, prescription glasses once a year, plus hearing instruments","summary":"Helps pay for basic dental care, prescription eyewear and hearing assistance for children under 19 in low-income families not on income, disability or hardship assistance.","requires":["bc","under19","bcMsp","notBcAssistance","bcHealthyKidsIncome" ],"eligibility":{"mode":"all","items":["Your family qualifies for MSP supplementary benefits — an adjusted net income of $42,000 or less.","You are not receiving income assistance, disability assistance or hardship assistance." ],"note":"Children in families on assistance get equivalent dental and optical coverage through the ministry supplements instead."},"requiresNote":"Your family qualifies for MSP supplementary benefits — that means an adjusted net income of $42,000 or less — and you are not receiving income assistance, disability assistance or hardship assistance. Children in families on assistance get equivalent dental and optical coverage through the ministry supplements instead.","note":"Coverage stays active until the end of the month of your child's 19th birthday. If your child reaches the $2,000 dental limit, emergency treatment is still available, but only for the immediate relief of pain.","applyText":"Apply for health & drug coverage","applyUrl":"https://my.gov.bc.ca/ahdc","source":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/family/child-teen-health/dental-eyeglasses","detail":{"about":"Dental is up to $2,000 of basic services every two years. Optical is prescription glasses once a year, including lenses and basic frames. Hearing instruments include hearing aids, bone-anchored hearing aids, cochlear implants, repairs and related items — the least expensive appropriate option, based on an assessment by an audiologist or hearing instrument practitioner, when the family has no other resources to pay. Adjusted net income is your net income after deductions for age, family size, disability, and income from the Universal Child Care Benefit and a Registered Disability Savings Plan.","aboutList":{"lead":"Dental is up to $2,000 of basic services every two years.","items":["Optical is prescription glasses once a year, including lenses and basic frames.","Hearing instruments include hearing aids, bone-anchored hearing aids, cochlear implants, repairs and related items — the least expensive appropriate option, based on an assessment by an audiologist or hearing instrument practitioner, when the family has no other resources to pay.","Adjusted net income is your net income after deductions for age, family size, disability, and income from the Universal Child Care Benefit and a Registered Disability Savings Plan." ]},"steps":["Apply for MSP supplementary benefits through the provincial health and drug coverage application","File income taxes every year and keep the family's MSP information current","Before treatment, ask the dental, optical or hearing provider to confirm the child's Healthy Kids coverage and any amount you would have to pay","Show the child's BC Services Card or CareCard at the appointment","For hearing instruments, have the provider obtain any required pre-authorization before ordering" ],"documents":["Child's BC Services Card or CareCard","Family income information used for MSP supplementary benefits","Provider assessment and recommendation for hearing instruments, when applicable" ],"tips":["Not every provider charges only the program fee; ask about extra charges before agreeing to treatment","Tell Health Insurance BC when the family size, address or marital status changes","Families on income, disability or hardship assistance receive comparable dental and optical supplements through the ministry instead" ],"time":"Ask Health Insurance BC when you apply","phone":"1-866-866-0800"}},{"id":"bc-medical-transportation","name":"Medical Transportation Supplement","level":"British Columbia","category":"Health","amount":"May pay $0.36 per kilometre by private vehicle, plus bus, ferry, air or train fares, accommodation for overnight travel, and travel escort costs if required","summary":"Helps pay for extraordinary transportation costs to and from essential medical treatment, using the least expensive appropriate transportation.","requires":["bc","bcMedTransportRoute","bcMedTransportNeed" ],"eligibility":{"mode":"any","items":["You are on disability assistance.","You are on income assistance in the Persons with Persistent Multiple Barriers category.","You receive income assistance and reside in a special care facility.","You are on Medical Services Only.","You receive Transitional Health Services after income assistance in the PPMB category.","You receive Transitional Health Services after income assistance while residing in a special care facility.","You are a person or child approved as facing a life-threatening health need, with a direct and immediate life-threatening need for medical transportation.","You are a child in a family receiving income assistance, disability assistance, hardship assistance, MSO or Transitional Health Services." ],"note":"The supplement is not available if you are only receiving income assistance."},"requiresNote":"You may be eligible through disability assistance; income assistance in PPMB; income assistance while residing in a special care facility; or Medical Services Only. Other routes are Transitional Health Services after income assistance in PPMB or while residing in a special care facility; a person or child approved as facing a life-threatening health need with a direct and immediate life-threatening need for medical transportation; or a child in a family receiving income assistance, disability assistance, hardship assistance, MSO or Transitional Health Services. Only receiving income assistance is not a route on its own. You do not have resources available to cover your medical transportation costs.","note":"Ask for pre-approval before you travel. In exceptional circumstances where you could not get funding beforehand, the ministry can consider a request afterwards, but do not count on it. Ambulance bills and the cost to buy, maintain, repair or insure a vehicle are not covered. Trips for non-essential services are not covered either.","applyText":"Submit form HR3320","applyUrl":"https://myselfserve.gov.bc.ca/","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/health-supplements-and-programs/medical-transportation","detail":{"about":"Helps pay for extraordinary transportation costs to and from essential medical treatment. Essential treatment means services under the Medicare Protection Act or Hospital Insurance Act with a medical practitioner, nurse practitioner, specialist or hospital. Meal allowances are normally not provided; in exceptional circumstances the ministry may issue up to $8 per meal. Travel escort costs may be paid if required. Costs may only be considered when accompanying a child under 19 or an adult incapable of travelling alone due to verified medical reasons.","aboutList":{"lead":"Helps pay for extraordinary transportation costs to and from essential medical treatment. Essential treatment means services under the Medicare Protection Act or Hospital Insurance Act with a medical practitioner, nurse practitioner, specialist or hospital.","items":["Meal allowances are normally not provided; in exceptional circumstances the ministry may issue up to $8 per meal.","Travel escort costs may be paid if required.","Costs may only be considered when accompanying a child under 19 or an adult incapable of travelling alone due to verified medical reasons." ]},"steps":["Ask for pre-approval before booking travel through My Self Serve, by phone, mail, fax or at a ministry office","Complete the medical transportation request form HR3320","Attach proof of the treatment and appointment, such as a provider note, appointment card, email, screenshot or Travel Assistance Program form","Explain the least expensive appropriate travel method and whether an escort or overnight stay is medically required","Keep approval and travel receipts in case the ministry requests them" ],"documents":["Form HR3320","Proof of the medical appointment and why the treatment is essential","Travel dates, destination, distance and expected fare or accommodation cost","Medical confirmation that an escort or special travel method is required, if applicable" ],"tips":["Request approval before you travel; after-the-fact payment is limited to exceptional circumstances","For repeated treatment, ask whether approval can cover ongoing trips for up to 12 months","The ministry chooses the least expensive appropriate transportation, so explain accessibility or medical barriers clearly" ],"time":"Apply before arranging the trip","phone":"1-866-866-0800"}},{"id":"handydart-translink","name":"HandyDART (TransLink)","level":"Metro Vancouver","category":"Transit","amount":"Every trip is a 1-Zone fare — $2.85 adult / $2.30 concession with Compass stored value, $3.50 adult / $2.30 concession in cash","summary":"Door-to-door shared-ride transit across Metro Vancouver for people who cannot use regular public transit for all trips without assistance. Any distance, always a 1-Zone fare.","requires":["bc","metroVancouver","transitBarrier" ],"eligibility":{"mode":"all","items":["You live in Metro Vancouver.","You have a physical, sensory or cognitive disability that means you cannot use conventional public transit for all trips without assistance." ],"note":"TransLink states eligibility is not based on advanced age or limited income."},"requiresNote":"You live in Metro Vancouver and have a physical, sensory or cognitive disability that means you cannot use conventional public transit for all trips without assistance. TransLink states eligibility is not based on advanced age or limited income.","note":"This is a Metro Vancouver service. Outside Metro Vancouver, look for BC Transit handyDART instead. Fares shown are current as of July 1, 2026 — TransLink usually changes fares on July 1.","applyText":"Download the HandyDART & HandyCard application","applyUrl":"https://www.translink.ca/handydart","source":"https://www.translink.ca/handydart","detail":{"about":"The earliest pickup is 6 a.m. and the last drop-off is 2 a.m. You can book your trip as far as seven days in advance and up until 4 p.m. the day before your trip. One combined HandyDART and HandyCard application form covers both services.","steps":["Download and complete the combined HandyDART and HandyCard application","Describe the parts of conventional transit you cannot navigate without help, including temporary or changing barriers","Include the optional medical verification if it will help explain the functional barrier","Submit the application using the instructions on the form and wait for Access Transit to contact you","After approval, call to book trips one to seven days ahead; bookings for the next day must be requested before 4 p.m." ],"documents":["Completed HandyDART and HandyCard application","Recent photo for the HandyCard portion","Optional functional or medical verification" ],"tips":["Explain what happens from your door to the stop, on the vehicle and during transfers. Eligibility is about the functional trip, not a diagnosis.","A HandyDART taxi replacement costs the regular HandyDART fare; it is not a TaxiSaver trip","Tell the booking agent about mobility aids, an attendant, a service dog or vehicle limitations" ],"time":"TransLink says it processes HandyDART applications within 10 days of confirming receipt, and asks you to allow 4 to 6 weeks for HandyCard applications.","phone":"604-953-3680"}},{"id":"handycard-translink","name":"HandyCard (TransLink)","level":"Metro Vancouver","category":"Transit","amount":"Free photo ID card — concession fares for you, free travel for your attendant, and access to half-price TaxiSaver coupons","summary":"Photo ID card for Metro Vancouver riders who cannot use regular transit without assistance. It gets you concession fares, lets an attendant travel free, and gives you access to the TaxiSaver program.","requires":["bc","metroVancouver","transitBarrier" ],"requiresNote":"You apply on the same combined HandyDART and HandyCard application form. HandyDART users may also be eligible for HandyCard, a photo-identity card for customers who need assistance to use the conventional system. The HandyDART test is a physical, sensory or cognitive disability that means you cannot use conventional public transit for all trips without assistance; see the application form for detailed criteria.","note":"The attendant travels free on buses, SkyTrain, SeaBus and West Coast Express. HandyDART trips are paid separately at the 1-Zone fare.","applyText":"Apply with the HandyDART & HandyCard form","applyUrl":"https://www.translink.ca/rider-guide/transit-accessibility/handydart","source":"https://www.translink.ca/rider-guide/transit-accessibility/handydart","detail":{"about":"HandyCard is for conventional TransLink services, not HandyDART. Carry the original photo card and show it when paying a concession fare or travelling with an attendant.","steps":["Complete the combined HandyDART and HandyCard application","Describe why you cannot use conventional transit without an attendant","Include the required photo and submit the form using its instructions","When the card arrives, carry it on every eligible trip and show it when requested" ],"documents":["Completed combined application","A recent photo meeting the form requirements","Optional supporting verification describing the transit barrier" ],"tips":["HandyCard applicants must be at least 12 and live in the TransLink service region","An attendant rides free with you on conventional transit, but you still pay your own concession fare","The same application can request HandyDART and HandyCard together" ],"time":"Allow 4 to 6 weeks for HandyCard applications to be processed","phone":"604-953-3680"}},{"id":"taxisaver-translink","name":"TaxiSaver Program (TransLink)","level":"Metro Vancouver","category":"Transit","amount":"Half-price taxi coupons — $25.00 buys one book with $50.00 worth of coupons, maximum two books per month","summary":"Half-price taxi coupons for HandyCard holders.","requires":["bc","metroVancouver","transitBarrier","translinkHandyCard" ],"requiresNote":"You must be a TransLink HandyCard member.","note":"Order by cheque or money order with a self-addressed envelope. Or buy in person at the TransLink Customer Service Centre at Waterfront Station, which takes cash, debit or credit. If you buy in person, you or your representative must show the original HandyCard.","applyText":"Get a HandyCard, then order TaxiSavers","applyUrl":"https://www.translink.ca/rider-guide/transit-accessibility/how-to-use-accessible-transit","source":"https://www.translink.ca/rider-guide/transit-accessibility/how-to-use-accessible-transit","detail":{"about":"TaxiSavers are coupon books for ordinary participating taxi trips. They are separate from taxis dispatched by HandyDART as part of a booked HandyDART trip.","steps":["Get and keep an active TransLink HandyCard","Choose mail order or in-person purchase at the TransLink Customer Service Centre at Waterfront Station","For mail order, send a cheque or money order with the required self-addressed envelope","For an in-person purchase, bring the original HandyCard; a representative may purchase for you if they bring it","Show the HandyCard to the taxi driver and use coupons toward the participating taxi fare" ],"documents":["Original TransLink HandyCard","Cheque or money order for mail orders, or accepted payment for an in-person purchase" ],"tips":["One $25 book contains $50 in coupons and the limit is two books per month","You can use post-dated cheques to pre-order future months","Call before travelling to Waterfront Station if you need accessibility or current counter-hour information" ],"time":"In person is immediate when stock and eligibility are confirmed; mail delivery varies","phone":"604-953-3680"}},{"id":"handydart-bctransit","name":"handyDART (BC Transit)","level":"British Columbia","category":"Transit","amount":"Registration is free; attendants ride free","summary":"Door-to-door shared-ride transit in BC Transit communities outside Metro Vancouver, for people whose disability prevents them from using fixed-route transit without assistance.","requires":["bc","outsideMetroVancouver","transitBarrier" ],"eligibility":{"mode":"all","items":["You live in a BC Transit community that has handyDART service.","You have a permanent or temporary disability that prevents you from using fixed-route transit without assistance." ]},"requiresNote":"You live in a BC Transit community that has handyDART service, and you have a permanent or temporary disability that prevents you from using fixed-route transit without assistance.","note":"Attendants ride free and must board and exit at the same stop as you. Each region has its own handyDART page, contact and booking office — start from your community's page on bctransit.com.","applyText":"Register with your region's handyDART office","applyUrl":(a) =>
  BC_TRANSIT_HANDYDART_REGISTRATION[a && a.city] || BC_TRANSIT_HANDYDART_CHOOSER,"source":(a) =>
  BC_TRANSIT_HANDYDART_REGISTRATION[a && a.city] || BC_TRANSIT_HANDYDART_CHOOSER,"detail":{"about":"handyDART is shared, door-to-door service. Drivers drop you off at the closest accessible point near your destination. Registration is free. You can pay your fare with cash when you board, or buy fare products in advance.","steps":["Find your community on the BC Transit website and open its handyDART registration page","Complete, sign and date the regional handyDART application","Describe which parts of fixed-route transit you cannot use without assistance","Include the optional medical verification if it helps explain the functional barrier","Submit the form to the regional registrar, then follow the local instructions for booking after approval" ],"documents":["Completed regional handyDART application","Optional Medical Verification of Eligibility form","Mobility-aid measurements or travel-support details if requested by the region" ],"tips":["Registration is free and eligibility is based on functional ability, not diagnosis, age or mobility device","Contacts, fares and booking hours differ by community — use your own regional page","Ask whether your region offers a handyPASS for a free attendant and Taxi Saver access" ],"time":"Varies by regional transit system","phone":"Use the handyDART number on your community's BC Transit page"}},{"id":"taxi-saver-bctransit","name":"Taxi Saver Program (BC Transit)","level":"British Columbia","category":"Transit","amount":"Half-price taxi coupons — in the Victoria region, $40 buys an $80 package, one package per month","summary":"Half-price taxi coupons for permanently registered handyDART riders, for one-off trips when handyDART does not work.","requires":["bc","outsideMetroVancouver","age12plus","transitBarrier","bcTransitHandyDart" ],"eligibility":{"mode":"all","items":["You are a permanently registered handyDART customer.","You are 12 years of age or older.","You have a handyPASS." ]},"requiresNote":"You are a permanently registered handyDART customer, 12 years of age or older, and you have a handyPASS.","note":"Coupons come in $1, $2 and $5 values. Taxi drivers do not give change for them, so pay any remainder in cash. Coupons cannot be transferred or used as a tip. The $40 for $80 package and the one-per-month limit are confirmed for the Victoria region. Other BC Transit regions run their own versions, so check your region's page.","applyText":"Check your region's Taxi Saver page","applyUrl":"https://www.bctransit.com/victoria/riderinfo/handydart/taxi-saver/","source":"https://www.bctransit.com/victoria/riderinfo/handydart/taxi-saver/","detail":{"about":"Taxi Saver is delivered by participating regional BC Transit systems. This guide uses Victoria's current rules; other regions can set different prices, purchase methods and taxi companies.","steps":["Confirm that you are permanently registered for handyDART, age 12 or older and have a handyPASS","Open your region's Taxi Saver page and confirm the current package price and purchase method","Buy vouchers from the regional Taxi Saver office or approved outlet","Book a participating taxi directly and show your handyPASS","Use vouchers toward the metered fare and pay any remainder in cash (for example, on a $5.80 fare you pay $5.00 in coupons and $0.80 in cash)" ],"documents":["Current handyPASS","Payment accepted by the regional Taxi Saver office" ],"tips":["Vouchers cover 50% of eligible taxi fares. They cannot be transferred or used as a tip.","Drivers do not give change for vouchers, so combine denominations carefully","Check the participating taxi list before booking because companies can change" ],"time":"Ask the regional Taxi Saver office","phone":"Victoria region: 250-995-5618"}},{"id":"bc-disability-assistance-pwd","needsPractitioner":true,"name":"BC Disability Assistance (PWD)","level":"British Columbia","category":"Money","amount":"Up to $1,483.50/month single ($983.50 support + $500 shelter) plus $52/month transportation supplement; up to $2,662/month for a couple where both have PWD","summary":"Monthly income support for adults with the Persons with Disabilities (PWD) designation — a support allowance plus shelter allowance, an automatic $52 transportation supplement, health supplements and PharmaCare Plan C coverage.","requires":["bc","age18plus","dailyLivingLimit","bcPwdMedical","bcDisabilityAssistanceFinancial" ],"note":"Rates took effect December 1, 2025. As of July 2026, $1,483.50 for a single person is the current maximum. You can also work. Starting January 1, 2026, you can earn up to $16,200 a year before earnings change your payment. The limit is $23,400 for a couple where one of you has PWD and $32,400 where both do. There is no monthly cap, so you can earn it whenever suits you. Even if you go over the limit, you always keep 100% of the money you earn. Only the assistance payment is reduced.","applyText":"Apply on My Self Serve","applyUrl":"https://myselfserve.gov.bc.ca/","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/bc-employment-and-assistance-rate-tables/disability-assistance-rate-table","detail":{"about":"Disability assistance is BC's core income program for people with the PWD designation. A single person receives a $983.50 monthly support allowance plus a shelter allowance of up to $500 (for one person the minimum is $75 if your actual shelter costs are less), and every PWD recipient gets a $52 transportation supplement as cash or an in-kind bus pass. It also opens the door to dental, optical, medical equipment, medical transportation and nutrition supplements, and 100% drug coverage under PharmaCare Plan C.","aboutList":{"lead":"Disability assistance is BC's core income program for people with the PWD designation.","items":["A single person receives a $983.50 monthly support allowance plus a shelter allowance of up to $500 (for one person the minimum is $75 if your actual shelter costs are less), and every PWD recipient gets a $52 transportation supplement as cash or an in-kind bus pass.","It also opens the door to dental, optical, medical equipment, medical transportation and nutrition supplements, and 100% drug coverage under PharmaCare Plan C." ]},"steps":["Create an account at myselfserve.gov.bc.ca (or call 1-866-866-0800) and complete the online application so the ministry can check financial eligibility","Request the PWD designation application and complete the applicant section (form HR2883)","Have your doctor or nurse practitioner complete the medical report section","Have a doctor, nurse practitioner or prescribed professional (e.g., occupational therapist, social worker) complete the assessor report","Submit everything and respond to any ministry follow-up. If you are approved for the designation and are financially eligible, assistance is paid in the month following designation (payments begin in the month of your 18th birthday if you were designated before turning 18).","Report income and changes monthly as required to keep payments accurate" ],"documents":["ID and Social Insurance Number for all adults in the family unit","Bank statements and details of assets and income","Rent receipt, lease or proof of shelter costs","Completed PWD application (applicant, medical and assessor sections)" ],"tips":["Already on CPP Disability, Community Living BC, the At Home Program, PharmaCare Plan P (palliative) or ISC PWD? A simplified prescribed-class application (HR3642) skips most of the medical paperwork","You can take the $52 transportation supplement as a BC Bus Pass instead of cash. Choose whichever you actually use.","PWD has higher asset limits than regular income assistance, so savings do not disqualify you as quickly","At 65 most recipients move to federal Old Age Security and GIS. The ministry will contact you before then.","The earnings exemption runs January 1 to December 31 and does not carry over. Anything you do not use is gone, and you get a fresh limit each year.","There is no monthly limit. You can earn the whole exemption in one busy month or spread it across the year without your assistance changing.","Going over the limit does not cost you your earnings. Your assistance is reduced by the amount you went over, and you keep 100% of what you earned.","The ministry sends you a letter once you reach 75% of your exemption, and you can check what is left any time on My Self Serve.","If you start disability assistance partway through the year, your exemption is prorated for the months left in the year. A change in your family also changes your limit.","File monthly report HR0081 by the fifth of the month if you have income or any change to report. Report your income even when it is exactly the same as last month." ],"time":"Financial eligibility is usually confirmed within days; the PWD designation decision commonly takes several weeks to a few months once all three report sections are submitted","phone":"1-866-866-0800"}},{"id":"bc-autism-funding-under-6","needsPractitioner":true,"name":"Autism Funding: Under Age 6","level":"British Columbia","category":"Money","amount":"Up to $22,000/year","summary":"Direct yearly funding to buy autism intervention services (behaviour consultants, therapists, supervised behaviour interventionists) for children under 6 with an autism diagnosis.","requires":["bc","under6","autismSelected","autismDiagnosis" ],"requiresNote":"Child under age 6 with an autism spectrum disorder diagnosis meeting BC standards (BCAAN or qualified private assessment)","note":"Autism Funding accepts new applications until March 2027 and ends March 31, 2027. The ministry says it will contact all recipients about their eligibility to transfer to the BC Children and Youth Disability Benefit ahead of the transition. Final aligned funding periods may be prorated to March 31, 2027.","applyText":"Apply for autism funding","applyUrl":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/autism-spectrum-disorder/autism-funding/apply","source":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/autism-spectrum-disorder/autism-funding/funding-amount","detail":{"about":"Normally, up to 20% of the allocation can go to training, travel and equipment (TTE). For the final aligned funding period ending March 31, 2027, BC increased the allowable TTE portion to 50%. Requests must not exceed 50% of a child/youth’s annual funding amount for benefit plans that are 12 months or less. For benefit plans that are 13 months or longer, the limit is 50% on the adjusted portion, with the first 12 months being available at 20%. Families are encouraged to check their TTE balance on MyFamily Services (MyFS) or call Autism Funding to confirm their balance (Toll Free: 1 877 777-3530).","coversList":{"lead":"Up to $22,000 per year per child covers:","items":["Professionals listed on the Registry of Autism Service Providers (RASP)","Behaviour interventionists supervised by a RASP professional","Family counselling or therapy (providers do not need to be on RASP)","Employment-related costs when you hire staff","Administrative costs up to $100/month" ]},"steps":["Get an autism diagnosis through the BC Autism Assessment Network (BCAAN, free via physician referral) or a private assessment meeting BC standards","Register for a Basic BCeID account to apply online, or complete the paper Application for Autism Funding","Email the application and supporting documents to mcf.autismfundingintake@gov.bc.ca or submit through your local CYSN office","Sign the funding agreement, then choose providers (RASP-listed professionals, supervised behaviour interventionists, or family counselling providers) and submit invoices or reimbursement claims" ],"documents":["Proof of age and residency (for example a birth certificate or BC Services Card)","BCAAN assessment: the BCAAN Clinical Outcome (PANTER) Form (BCAAN assessment reports are optional)","Private (non-BCAAN) assessment: form CF0904 and a diagnostic report showing the ADOS-2 and ADI-R were used, signed by the assessor, with the speech-language and psychological evaluation findings","Assessment outside B.C.: form CF0905 and a copy of the original diagnostic report or assessment information","Basic BCeID account for online applications","Assessment outside B.C.: a new assessment may be required if the BC specialist cannot confirm that the previous diagnosis meets the DSM-5 criteria" ],"tips":["Intervention services must come from providers on the RASP registry, or from behaviour interventionists supervised by a RASP professional. Family counselling or therapy providers do not need to be on RASP.","The normal training, travel and equipment limit is 20%, but BC raised it to 50% for the final aligned funding period ending March 31, 2027. Requests must not exceed 50% of a child/youth’s annual funding amount for benefit plans that are 12 months or less. For benefit plans that are 13 months or longer, the limit is 50% on the adjusted portion, with the first 12 months being available at 20%. Families are encouraged to check their TTE balance on MyFamily Services (MyFS) or call Autism Funding to confirm their balance (Toll Free: 1 877 777-3530).","Approved services and purchases must be delivered by March 31, 2027; direct-payment supporting documents are due May 31, 2027. Submit invoices and reimbursement requests within 6 months of each service or purchase; for those made on March 31, 2027, the last day is September 30, 2027","From July 2026 the ministry contacts Autism Funding families about moving to the new Disability Benefit ($6,500 or $17,000/year). You keep your current funding until your transition date.","These professionals may be eligible to provide family counselling or therapy: Canadian Certified Counsellors, Registered Clinical Counsellors, Registered Marriage and Family Therapists, Registered Psychiatrists, Registered Psychologists, and Registered Social Workers or Registered Clinical Social Workers. Contact Autism Funding or Autism Information Services BC for more information." ],"time":"New applications are accepted until March 2027. The program and final aligned funding periods end March 31, 2027; later paperwork deadlines do not extend the service-delivery date.","phone":"1-877-777-3530"}},{"id":"bc-autism-funding-6-18","needsPractitioner":true,"name":"Autism Funding: Ages 6-18","level":"British Columbia","category":"Money","amount":"Up to $6,000/year","summary":"Yearly funding for autism intervention, therapies, life-skills programs, camps and out-of-school tutoring for children and youth aged 6 to 18.","requires":["bc","age6to18","autismSelected","autismDiagnosis" ],"requiresNote":"Child or youth aged 6-18 with an autism spectrum disorder diagnosis meeting BC standards","note":"Autism Funding accepts new applications until March 2027 and ends March 31, 2027. The ministry says it will contact all recipients about their eligibility to transfer to the BC Children and Youth Disability Benefit ahead of the transition. Final aligned funding periods may be prorated to March 31, 2027.","applyText":"Apply for autism funding","applyUrl":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/autism-spectrum-disorder/autism-funding/apply","source":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/autism-spectrum-disorder/autism-funding/funding-amount","detail":{"about":"Administrative costs are limited to up to $50 a month for a bookkeeper, or $600 per funding period for direct payment accountant fees. The normal training, travel and equipment (TTE) limit is 20%. For the final aligned funding period ending March 31, 2027, BC increased the allowable TTE portion to 50%. Requests must not exceed 50% of a child/youth’s annual funding amount for benefit plans that are 12 months or less. For benefit plans that are 13 months or longer, the limit is 50% on the adjusted portion, with the first 12 months being available at 20%. Families are encouraged to check their TTE balance on MyFamily Services (MyFS) or call Autism Funding to confirm their balance (Toll Free: 1 877 777-3530). For families with youth aging out (turning 19) prior to March 31, 2027, requests for travel, training and equipment purchases must not exceed 20%.","coversList":{"lead":"Up to $6,000 per year per child for:","items":["Behaviour consultants or analysts","Speech-language pathologists","Occupational or physical therapists","Behaviour interventionists (should be supervised by one of the professionals listed above)","Life skills and social skills programs","Out-of-school learning support and tutoring","Dietary counselling from registered dieticians","Family counselling","Specialized therapeutic camps for autism" ]},"steps":["Have an autism diagnosis on file (BCAAN or qualified private assessment)","Apply online with a Basic BCeID or send the Application for Autism Funding to mcf.autismfundingintake@gov.bc.ca, or go through your local CYSN office","Sign the funding agreement and hire providers for the eligible services (behaviour interventionists should be supervised by a listed professional)","Submit invoices for direct payment or claim reimbursements" ],"documents":["Proof of age and residency (for example a birth certificate or BC Services Card)","BCAAN assessment: the BCAAN Clinical Outcome (PANTER) Form (BCAAN assessment reports are optional)","Private (non-BCAAN) assessment: form CF0904 and a diagnostic report showing the ADOS-2 and ADI-R were used, signed by the assessor","Assessment outside B.C.: form CF0905 and a copy of the original diagnostic report or assessment information","Basic BCeID account for the online portal","Assessment outside B.C.: a new assessment may be required if the BC specialist cannot confirm that the previous diagnosis meets the DSM-5 criteria" ],"tips":["For ages 6-18, providers do not have to be RASP-listed for every service type. So therapy, tutoring and camps are easier to fund than under the Under-6 program.","The normal training, travel and equipment limit is 20%, but BC raised it to 50% for the final aligned funding period ending March 31, 2027. Requests must not exceed 50% of a child/youth’s annual funding amount for benefit plans that are 12 months or less. For benefit plans that are 13 months or longer, the limit is 50% on the adjusted portion, with the first 12 months being available at 20%. Families are encouraged to check their TTE balance on MyFamily Services (MyFS) or call Autism Funding to confirm their balance (Toll Free: 1 877 777-3530).","Approved services and purchases must be delivered by March 31, 2027; direct-payment supporting documents are due May 31, 2027. Submit invoices and reimbursement requests within 6 months of each service or purchase; for those made on March 31, 2027, the last day is September 30, 2027","For families with youth aging out (turning 19) before March 31, 2027, requests for travel, training and equipment purchases must not exceed 20%.","Ask your CYSN office about the transition schedule if you have not been contacted by fall 2026" ],"time":"New applications are accepted until March 2027. The program and final aligned funding periods end March 31, 2027; later paperwork deadlines do not extend the service-delivery date.","phone":"1-877-777-3530"}},{"id":"bc-cy-disability-benefit","needsPractitioner":true,"name":"BC Children and Youth Disability Benefit","level":"British Columbia","category":"Money","amount":"$6,500 or $17,000/year","summary":"New direct funding for children and youth, from age 0 until the last day of their 19th birthday month, who have significant disabilities of any diagnosis (autism, Down syndrome, cerebral palsy, intellectual disability and more). It replaces Autism Funding and the School-Aged Extended Therapies stream.","requires":["bc","bcCydbAge","childHighNeeds","bcCydbIntake" ],"eligibility":{"mode":"all","items":["The child is aged 0 until the last day of their 19th birthday month.","The child has a long-term disability causing significant and complex developmental support needs, based on diagnosis and/or functional impact." ]},"requiresNote":"Ages 0 until the last day of the 19th birthday month, with a long-term disability causing significant and complex developmental support needs, based on diagnosis and/or functional impact","note":"Began April 1, 2026. Eligible families already receiving ministry services for children and youth with support needs, including autism funding, will not need to apply, although some may be asked to provide additional information. The benefit will be available province-wide by April 1, 2027.","applyText":"Learn about the Disability Benefit","applyUrl":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/financial-supports/disability-benefit","source":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/financial-supports/disability-benefit","detail":{"about":"Two funding tiers: a base tier of $6,500/year and a higher tier of $17,000/year set through support planning with a ministry worker. Funding covers disability-related expenses including respite, paediatric therapies, behavioural intervention, and assistive and augmentative communication supports. Eligibility is needs-based, not diagnosis-specific: direct admission for conditions such as moderate-to-profound intellectual disability, autism with intellectual disability, and degenerative conditions with predictable decline (such as Duchenne muscular dystrophy and SMA types 1 and 2), plus a needs-based clinical review pathway for rare or atypical cases. Part of a $475-million, three-year provincial investment that also expands free community services (therapies from spring 2026, behaviour and mental-health supports 2027, navigation and school-aged programming 2027-2028).","aboutList":{"lead":"Two funding tiers: a base tier of $6,500/year and a higher tier of $17,000/year set through support planning with a ministry worker.","items":["Funding covers disability-related expenses including respite, paediatric therapies, behavioural intervention, and assistive and augmentative communication supports.","Eligibility is needs-based, not diagnosis-specific: direct admission for conditions such as moderate-to-profound intellectual disability, autism with intellectual disability, and degenerative conditions with predictable decline (such as Duchenne muscular dystrophy and SMA types 1 and 2), plus a needs-based clinical review pathway for rare or atypical cases.","Part of a $475-million, three-year provincial investment that also expands free community services (therapies from spring 2026, behaviour and mental-health supports 2027, navigation and school-aged programming 2027-2028)." ]},"steps":["Already receiving Autism Funding or SAET: wait to be contacted — a ministry worker manages your transition between April 2026 and March 2027","Not yet in a program: before March 31, 2027 you can apply through the current pathways (such as Autism Funding or the School-Aged Extended Therapies stream). Children and youth receiving CYSN services before March 31, 2027 will transition to the Disability Benefit if they are eligible.","After April 1, 2027: new applicants apply directly to the Disability Benefit","Work with a ministry worker on support planning if your child may qualify for the $17,000 higher tier" ],"documents":["Existing program enrolment (some children move directly based on information on file; others may be asked for additional information), or","Diagnostic reports and functional assessments showing significant support needs (communication, cognitive/adaptive functioning, safety or behavioural complexity)" ],"tips":["Do not wait for 2027. Before March 31, 2027 you can apply through the current pathways. Those receiving CYSN services by then will move to the Disability Benefit if they are eligible.","Funding is flexible across respite, therapy, behaviour intervention and AAC (augmentative and alternative communication), rather than tied to one diagnosis stream","Services outside British Columbia and unresearched interventions are not eligible uses","Call the toll-free helpline for families (1-844-442-2800) with questions. To ask about using the funding, call PAIRS (1-844-878-4700, 8:30am to 4:30pm Monday to Friday, excluding statutory holidays)." ],"time":"Transition runs April 2026 to March 2027; new applicants apply directly after April 1, 2027.","phone":"1-844-442-2800"}},{"id":"bc-monthly-nutritional-supplement","needsPractitioner":true,"name":"Monthly Nutritional Supplement","level":"British Columbia","category":"Health","amount":"Up to $180/month for dietary items plus up to $45/month for vitamins or minerals","summary":"Extra monthly money on top of disability assistance for PWD recipients whose severe condition causes chronic, progressive deterioration of health, and who need extra nutrition to prevent imminent danger to life and have no other family resources to pay for it.","requires":["bc","age18plus","bcPwdStatus","nutritionNeed","lowIncome" ],"note":"A practitioner must confirm at least two symptoms. Examples are malnutrition, underweight status, significant weight loss, significant muscle-mass loss, significant neurological degeneration, deterioration of a vital organ, or moderate-to-severe immune suppression.","applyText":"Get form HR2847 (PDF)","applyUrl":"https://www2.gov.bc.ca/assets/gov/british-columbians-our-governments/policies-for-government/bc-employment-assistance-policy-procedure-manual/forms/pdfs/hr2847.pdf","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/bc-employment-and-assistance-rate-tables/health-supplements-and-programs-rate-table","detail":{"about":"The MNS is for people on disability assistance with the PWD designation who have a severe medical condition causing chronic, progressive deterioration of health with wasting-type symptoms, and who need additional nutritional items or vitamins and minerals to prevent imminent danger to life. Current maximums (Health Supplements & Programs rate table, effective August 1, 2023) are $180/month for dietary items and $45/month for vitamins or minerals.","aboutList":{"lead":"The MNS is for people on disability assistance with the PWD designation who have a severe medical condition causing chronic, progressive deterioration of health with wasting-type symptoms, and who need additional nutritional items or vitamins and minerals to prevent imminent danger to life.","items":["Current maximums (Health Supplements & Programs rate table, effective August 1, 2023) are $180/month for dietary items and $45/month for vitamins or minerals." ]},"steps":["Get form HR2847 (Application for Monthly Nutritional Supplement) from your ministry office, My Self Serve or the link above","Complete Part B yourself","Have a medical practitioner, nurse practitioner or registered dietitian complete Part C describing your condition, symptoms and the items needed","Submit the form; the ministry's Health Assistance staff review and decide" ],"documents":["Form HR2847 with the practitioner or dietitian section completed" ],"tips":["A registered dietitian can complete Part C. This is often faster than waiting for a specialist appointment.","Be specific about each symptom: two or more must be documented for approval","If denied, request reconsideration. Better medical detail can help a reconsideration." ],"time":"Typically a few weeks after the ministry receives the completed form","phone":"1-866-866-0800"}},{"id":"bc-optical-supplement","name":"Optical Supplements (Glasses & Eye Exams)","level":"British Columbia","category":"Health","amount":"Routine eye exam up to $44.83 with an optometrist or $48.90 with an ophthalmologist once every 2 years; new prescription glasses at the ministry's maximum rates, plus new lenses if your eye doctor confirms a change in your prescription","summary":"Eye exams and prescription eyewear for everyone on income or disability assistance. Show your BC Services Card at any eye clinic, and the ministry pays the optometrist or optician directly.","requires":["bc","bcAssistanceStatus" ],"note":"MSP already covers children's routine eye exams. The supplement pays for their glasses. You may be responsible for costs above the ministry's fee schedule, so ask the clinic first.","applyText":"See what's covered","applyUrl":"https://www2.gov.bc.ca/gov/content/family-social-supports/income-assistance/on-assistance/supplements/optical","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/bc-employment-and-assistance-rate-tables/health-supplements-and-programs-rate-table","detail":{"about":"Everyone receiving income or disability assistance gets specified optical services: routine eye exams for adults (up to $44.83 with an optometrist or $48.90 with an ophthalmologist every two years), new eyeglasses up to ministry maximum rates, new lenses if your eye doctor confirms a change in your prescription, and necessary repairs to lenses or frames. Payment goes straight from the ministry to the optometrist or optician.","aboutList":{"lead":"Everyone receiving income or disability assistance gets specified optical services:","items":["Routine eye exams for adults (up to $44.83 with an optometrist or $48.90 with an ophthalmologist every two years)","New eyeglasses up to ministry maximum rates","New lenses if your eye doctor confirms a change in your prescription","And necessary repairs to lenses or frames","Payment goes straight from the ministry to the optometrist or optician." ]},"steps":["Take your BC Services Card to any eye clinic","The clinic verifies your coverage through Pacific Blue Cross","Get your exam and choose frames within the ministry rate (or pay the difference)","The ministry pays the provider directly" ],"documents":["BC Services Card" ],"tips":["Ask the clinic which frames are fully covered at ministry rates before choosing","If your eye doctor confirms a change in your prescription, new lenses are covered" ],"time":"No application — coverage verified at the clinic on the spot","phone":"1-866-866-0800"}},{"id":"bc-bus-pass","name":"BC Bus Pass Program","level":"British Columbia","category":"Transit","amount":"No annual fee for PWD recipients; $45/year for eligible low-income seniors","summary":"A bus pass for people on BC disability assistance and for low-income seniors. It works on scheduled BC Transit services across the province. In Metro Vancouver it comes as a Compass Card.","requires":["bc","bcBusPassStatus" ],"eligibility":{"mode":"any","items":["You receive BC disability assistance (PWD designation).","You are a low-income senior who receives the Guaranteed Income Supplement (GIS).","You are 60 to 64 and on provincial income assistance.","You are 65 or older and would get the GIS but for residency rules." ]},"requiresNote":"For people receiving BC disability assistance (PWD designation). Low-income seniors also qualify: GIS recipients, 60-64 year olds on provincial income assistance, and 65+ who would get GIS but for residency rules.","note":"PWD recipients pay no annual fee. They choose the bus pass instead of the $52 monthly cash transportation supplement. The separate eligible low-income-senior stream costs $45 per year.","applyText":"Request via My Self Serve or call 1-866-866-0800","applyUrl":"https://www2.gov.bc.ca/gov/content/transportation/passenger-travel/buses-taxis-limos/bus-pass/people-with-disabilities","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/general-supplements-and-programs/bc-bus-pass-program","detail":{"about":"The BC Bus Pass Program provides a monthly pass at no annual cost to eligible people with the PWD designation who receive disability assistance, and a separate $45 annual pass to eligible low-income seniors. The pass works on scheduled BC Transit services across the province and as a Compass Card on TransLink in Metro Vancouver. A PWD recipient chooses either the pass or the $52 monthly cash transportation supplement.","aboutList":{"lead":"The BC Bus Pass Program provides a monthly pass at no annual cost to eligible people with the PWD designation who receive disability assistance, and a separate $45 annual pass to eligible low-income seniors.","items":["The pass works on scheduled BC Transit services across the province and as a Compass Card on TransLink in Metro Vancouver.","A PWD recipient chooses either the pass or the $52 monthly cash transportation supplement." ]},"steps":["Confirm whether you qualify through the PWD stream or the low-income-senior stream","If you receive PWD disability assistance, choose either the no-fee bus pass or the $52 monthly cash transportation supplement","Request the pass through My Self Serve or by calling 1-866-866-0800; PWD recipients switching from cash should contact the ministry by the 5th for the change to start the next month","Allow 4 to 6 weeks for a new pass to arrive" ],"documents":["Seniors stream: SIN, name, date of birth, address and contact details" ],"tips":["PWD recipients pay no annual fee. The $45 annual fee applies to the eligible low-income-senior stream.","The pass works in BC Transit communities across the whole province, not just your home city","Replacement passes can have a fee, even when the original PWD pass had no annual fee. Report a lost pass quickly.","PWD recipients can later cancel the pass and go back to the $52 monthly cash supplement. To do this, contact the ministry by the 5th.","No new documents if you already receive disability assistance — just your request" ],"time":"Allow 4 to 6 weeks for a new pass to arrive","phone":"1-866-866-0800"}},{"id":"sparc-parking-permit","eligibility":{"mode":"all","items":["Mobility limitation confirmed by a medical professional — for example you use a wheelchair or a mobility aid like a cane or crutches, or your health prevents you from walking far." ],"note":"You don't need to own a vehicle."},"needsPractitioner":true,"name":"Accessible Parking Permit (SPARC BC)","level":"British Columbia","category":"Parking","amount":"Fees are set by SPARC BC; confirm the current fee on their site. Permanent permits are valid 3 years; temporary permits are valid 1-12 months and are not renewable.","summary":"BC's accessible parking placard for people with mobility limitations. Hang it from the rear-view mirror. It is valid whether you drive or ride as a passenger.","requires":["bc","bcParkingMobility" ],"requiresNote":"Mobility limitation confirmed by a medical professional — for example you use a wheelchair or a mobility aid like a cane or crutches, or your health prevents you from walking far. You don't need to own a vehicle.","note":"SPARC BC is the non-profit that runs BC's permit program. SPARC BC sets the fees. Check the current fee and any hardship help on its site.","applyText":"Apply through SPARC BC","applyUrl":"https://www.sparc.bc.ca/parking-permits/","source":"https://www.sparc.bc.ca/parking-permits/","detail":{"about":"SPARC BC issues the accessible parking permits recognized in designated spaces across British Columbia. Two types exist: permanent (valid 3 years, renewable) and temporary (1 to 12 months, not renewable — reapply if still needed). The permit belongs to the person, not a car, and must be displayed on the rear-view mirror while parked.","aboutList":{"lead":"SPARC BC issues the accessible parking permits recognized in designated spaces across British Columbia.","items":["Two types exist: permanent (valid 3 years, renewable) and temporary (1 to 12 months, not renewable — reapply if still needed).","The permit belongs to the person, not a car, and must be displayed on the rear-view mirror while parked." ]},"steps":["Download the application form from sparc.bc.ca or call 604-718-7744 / 1-888-718-7794 for a copy","Have the referral section completed by a medical professional with a valid MSP number","Check SPARC BC's site for the current fee and submit it with the application; ask about hardship assistance if needed","Allow 2 to 3 weeks for processing","Display the permit on the rear-view mirror whenever parked in an accessible space" ],"documents":["Application form including the medical professional referral section","Payment of the current fee listed by SPARC BC, unless hardship assistance applies" ],"tips":["The permit is yours, not the vehicle's. Use it in any car you drive or ride in.","Renew permanent permits online at online.sparc.bc.ca before they expire. Expired permits can't be renewed online.","Temporary permits can't be renewed. Send a new application if you still need one.","Email permits@sparc.bc.ca with questions" ],"time":"2 to 3 weeks from when your application is received","phone":"604-718-7744 or toll-free 1-888-718-7794"}},{"id":"bc-medical-equipment-devices","needsPractitioner":true,"name":"Medical Equipment & Devices Supplement","level":"British Columbia","category":"Equipment","amount":"Full cost of pre-approved equipment — e.g., scooters up to $3,500 ($4,500 bariatric), floor/ceiling lifts up to $4,200 (more only if the excess is from unusual installation expenses); wheelchairs, walkers, hospital beds and bathing aids at ministry rates","summary":"The ministry buys, repairs and replaces essential medical equipment — canes to power wheelchairs, hospital beds, transfer aids, pressure-relief mattresses, specialized glucose meters — for people on assistance with no other way to pay.","requires":["bc","bcAssistanceStatus","equipmentNeed" ],"note":"Pre-approval is required: the ministry must approve the request before purchase, except in cases of a life-threatening emergency, and it is the payer of last resort — other available resources (for example ICBC, WorkSafeBC or private insurance) must be considered first. Co-funding may be considered when other resources cannot pay the entire cost.","applyText":"Request via My Self Serve","applyUrl":"https://myselfserve.gov.bc.ca/","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/health-supplements-and-programs/medical-equipment-and-devices","detail":{"about":"Covered items include canes, crutches, walkers, manual and power wheelchairs, scooters, grab bars, bath seats, commodes, lift devices, hospital beds, pressure-relief mattresses and non-conventional glucose meters. The item must be prescribed by a medical practitioner or nurse practitioner, and/or the medical need confirmed by the assessment of a relevant therapist (occupational or physical therapist). Many items also need a therapist assessment. Most equipment can be replaced every five years (wheelchair seating after two; canes, crutches and walkers as needed). Scooters intended primarily for recreational or sports use, lift chairs, automatic turning beds and containment type beds are not provided.","aboutList":{"lead":"Covered items include canes, crutches, walkers, manual and power wheelchairs, scooters, grab bars, bath seats, commodes, lift devices, hospital beds, pressure-relief mattresses and non-conventional glucose meters.","items":["The item must be prescribed by a medical practitioner or nurse practitioner, and/or the medical need confirmed by the assessment of a relevant therapist (occupational or physical therapist). Many items also need a therapist assessment.","Most equipment can be replaced every five years (wheelchair seating after two; canes, crutches and walkers as needed).","Scooters intended primarily for recreational or sports use, lift chairs, automatic turning beds and containment type beds are not provided." ]},"steps":["Contact the ministry through My Self Serve or 1-866-866-0800 to start an equipment request","Get a prescription from your doctor or nurse practitioner, and/or an assessment from a relevant therapist confirming the medical need","Complete an occupational or physical therapist assessment where required (wheelchairs, seating, scooters, lifts)","Submit supplier quote(s); wait for written ministry pre-approval","The ministry pays the supplier directly; repairs are requested the same way" ],"documents":["Doctor or nurse practitioner prescription and/or therapist assessment confirming the medical need","Occupational/physical therapist assessment for mobility and positioning items","Supplier quote" ],"tips":["Never buy first — the ministry will not accept payment responsibility for equipment purchased without prior approval, except in cases of a life-threatening emergency","If you need specific features, ask your OT to note why the least-expensive option would not meet your medical need.","Repairs and batteries can be covered between replacement cycles" ],"time":"Weeks to a couple of months depending on assessments, quotes and pre-approval","phone":"1-866-866-0800"}},{"id":"bc-at-home-medical","needsPractitioner":true,"name":"At Home Program: Medical Benefits","level":"British Columbia","category":"Health","amount":"Per-item coverage — wheelchair seating to $9,000, lifts to $8,000, hospital bed to $4,000, scooter to $3,700, dental $700 a year, optical $150 a year, plus the full cost of eligible prescription drugs through PharmaCare Plan F, which also pays part of the cost of some medical supplies","summary":"Medical equipment, therapies, dental and optical care, medical travel and PharmaCare Plan F for eligible children. See the assessed daily-living, direct nursing care and palliative routes below.","requires":["bc","child","bcMsp","bcAtHomeMedicalRoute" ],"eligibility":{"mode":"all","items":["Your child is 17 or younger.","Your child is a BC resident enrolled in the Medical Services Plan.","Your child lives at home with a parent or guardian, or with an Extended Family Program caregiver.","Your child meets one of the routes listed below." ]},"requiresNote":"Your child is 17 or younger, is a BC resident enrolled in the Medical Services Plan, and lives at home with a parent or guardian or with an Extended Family Program caregiver. Medical-benefit routes are alternatives: assessed dependence in at least three of eating, dressing, toileting and washing; eligibility for Nursing Support Services direct nursing care, without an eligibility assessment; or a palliative condition with life expectancy of up to six months as indicated by a physician or nurse practitioner, without an eligibility assessment.","note":"Benefits last until the last day of the month your child turns 18. PharmaCare Plan F coverage ends the same day. Start the adult disability assistance application about six months before that birthday. Young people in the program get a streamlined route into it. New families can still apply until March 2027.","applyText":"See eligibility and apply","applyUrl":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/complex-health-needs/at-home-program/at-home-program-eligibility","source":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/complex-health-needs/at-home-program","detail":{"about":"Medical Benefits can cover approved equipment, supplies, therapies, dental, optical, medical travel, and, through PharmaCare Plan F, the full cost of eligible prescription drugs and part of the cost of some medical supplies. The program must approve many items before they are bought, and coverage ends on the last day of the month the child turns 18.","aboutList":{"lead":"Medical Benefits can cover approved equipment, supplies, therapies, dental, optical, medical travel, and, through PharmaCare Plan F, the full cost of eligible prescription drugs and part of the cost of some medical supplies.","items":["The program must approve many items before they are bought.","Coverage ends on the last day of the month the child turns 18.","Any one of these routes can apply: assessed dependence in at least three of eating, dressing, toileting and washing.","Eligible for Nursing Support Services direct nursing care: no eligibility assessment is required.","Palliative route: a palliative condition with life expectancy of up to six months.","A physician or nurse practitioner must indicate this palliative life expectancy.","No eligibility assessment is required for this palliative route." ]},"steps":["Complete the At Home Program application with a doctor or nurse practitioner","Attach the requested identification and functional assessments; children under 3 will be asked for extra supporting information","Send the application to the regional At Home Program office listed by the province","Take part in the in-home assessment of eating, dressing, toileting and washing if one is required","Wait for the written decision, then work with the CYSN worker or Medical Benefits branch before purchasing covered equipment or services" ],"documents":["Completed At Home Program application with parent and medical-professional sections","Identification for the child and parent or guardian","Child's Personal Health Number and proof of active MSP","Requested functional assessments such as Vineland-3, PEDI-CAT or GMFCS, when applicable" ],"tips":["Families in current pilot areas use a different Medical Benefits application route. Check the official page for your community.","Do not buy equipment, dental, optical or travel first when pre-approval is required","Start adult PWD planning about six months before the child's 18th birthday","PharmaCare Plan F is not a separate application. Once your child gets full benefits or medical benefits through the At Home Program, MCFD sends their information to PharmaCare. The drug coverage then follows automatically.","Drugs are fully paid, but supplies such as syringes or glucose monitors are only partly paid, so ask what you will owe. Before you keep buying a supply yourself, ask the At Home Program or your pharmacist if it is on the designated list." ],"time":"Assessment and regional review follow a complete application; no guaranteed timeline is published","phone":"Medical Benefits: 1-888-613-3232"}},{"id":"bc-supported-child-development","name":"Supported Child Development","level":"British Columbia","category":"Family","amount":"Consulting and support services so a child with extra support needs can take part in inclusive child care","summary":"Community programs that help children with extra support needs take part in regular, fully inclusive child care. They support the family and the child care centre, not just the child.","requires":["bc","child","childcare" ],"requiresNote":"For children with extra support needs who are attending or want to attend a child care setting in BC.","note":"Ask your public health nurse or physician, or contact your local Ministry of Children and Family Development office. Aboriginal Supported Child Development offers the same supports in a way that is culturally relevant and meaningful. See ascdp.bc.ca.","applyText":"Find your local program","applyUrl":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/early-childhood-intervention","source":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/early-childhood-intervention","detail":{"about":"Supported Child Development is a set of community-based programs offering consulting and support to children, families and child care centres so children with extra support needs can participate in inclusive child care. Aboriginal Supported Child Development provides culturally relevant support.","steps":["Use the provincial early-intervention page to find the Supported Child Development program serving your community","Contact the program directly, or ask a public health nurse or physician to help with the referral","Tell the program which child care setting the child attends or hopes to attend and what participation barriers are present","Work with the program and child care provider on an individual support plan" ],"documents":["Child and parent or guardian contact information","Information from the child care provider about participation and support needs","Relevant developmental or health reports if the local program requests them" ],"tips":["Contact the program even if the child does not yet have a child care placement","Ask about Aboriginal Supported Child Development if culturally grounded service is a better fit","Availability and intake steps are local, so the community program is the official contact" ],"time":"Intake and availability vary by community"}},{"id":"bc-at-home-saet","needsPractitioner":true,"name":"At Home Program: School-Aged Extended Therapies (SAET)","level":"British Columbia","category":"Health","amount":"Up to $5,760/year each for OT, PT and speech therapy, plus up to $1,920/year for chiropractic or massage","summary":"May help families with the cost of out-of-school occupational therapy, physiotherapy and speech-language pathology for school-aged children enrolled in the At Home Program.","requires":["bc","schoolAge","childThreeAdls","atHomeProgram" ],"requiresNote":"School-aged children and youth enrolled in the At Home Program","note":"Children enrolled in and still eligible for the At Home Program transition first to the new B.C. Children and Youth Disability Benefit during the April 2026–March 2027 phase. Therapies remain an approved use of the new benefit. SAET stays available until March 31, 2027, or until your child transitions, whichever comes first. All SAET authorizations are being updated to match that end date. New families are told to keep using the current pathways for now. The new benefit is fully operational provincewide from April 1, 2027. Ask AHP Medical Benefits which stream applies to your child.","applyText":"Request through AHP Medical Benefits","applyUrl":"https://www2.gov.bc.ca/gov/content/health/managing-your-health/child-behaviour-development/support-needs/complex-health-needs/at-home-program/medical-benefits","source":"https://www2.gov.bc.ca/assets/gov/family-and-social-supports/children-teens-with-support-needs/at_home_program_guide.pdf","detail":{"about":"Up to $5,760 per 12-month period for each of occupational therapy, physiotherapy and speech-language pathology (including therapist-assistant services), delivered one-to-one or in groups. Maximum billing rates: $160/hour for therapists, $60/hour for therapist assistants; up to $480 of the maximum can go to consultation, report writing and travel. A separate maximum of $1,920/year may be provided for chiropractic ($40/session) or massage ($40/hour). Exceptions to maximums are considered for post-surgical rehabilitation. Services must complement, not duplicate, school-based therapy.","aboutList":{"lead":"Up to $5,760 per 12-month period for each of occupational therapy, physiotherapy and speech-language pathology (including therapist-assistant services), delivered one-to-one or in groups.","items":["Maximum billing rates: $160/hour for therapists, $60/hour for therapist assistants; up to $480 of the maximum can go to consultation, report writing and travel.","A separate maximum of $1,920/year may be provided for chiropractic ($40/session) or massage ($40/hour).","Exceptions to maximums are considered for post-surgical rehabilitation.","Services must complement, not duplicate, school-based therapy." ]},"steps":["Ensure the child is enrolled in the At Home Program","Have the treating OT, PT, SLP, chiropractor or massage therapist complete the At Home Program Request for School-Aged Extended Therapies form, including intended functional outcomes","Submit the request to AHP Medical Benefits for review","Approved therapists invoice AHP Medical Benefits directly" ],"documents":["Request for School-Aged Extended Therapies form completed by the treating therapist","Functional outcomes for the child (Part 5 of the request form)" ],"tips":["The therapist who requests services must work with the school-based therapy team so services do not overlap","Sequential therapy blocks (one goal at a time) are preferred over running everything at once","If your child has transitioned to the Disability Benefit, ask which therapies can be paid from the $6,500/$17,000 annual allocation instead","Exceptions to the annual maximum are considered for post-surgical rehab. Ask for an exception." ],"time":"Requests reviewed by AHP Medical Benefits; SAET recipients transitioned to the Disability Benefit starting April 2026.","phone":"1-888-613-3232"}},{"id":"bc-clbc","needsPractitioner":true,"name":"Community Living BC (CLBC) Adult Supports","level":"British Columbia","category":"Family","amount":"Individually planned funded services — residential, employment, community inclusion, respite","summary":"A provincial agency that funds lifelong supports for adults 19+ with developmental disabilities. Supports include home sharing and staffed living, employment services, community inclusion, respite and family support. Youth can apply from age 16. What funded support you get, and when, depends on how urgent your situation is and the funding CLBC has at the time of the request.","requires":["bc","age16plus","bcClbcStream","disabilityDoc" ],"eligibility":{"mode":"any","items":["You are an adult 19 or older with significantly impaired intellectual and adaptive functioning that began before age 18.","Under the PSI stream, you are an adult with an FASD or autism spectrum diagnosis plus significant adaptive-functioning limitations." ],"note":"You can apply from age 16, and supports can be life-long."},"requiresNote":"Adults 19+ with significantly impaired intellectual and adaptive functioning that began before age 18; or, under the PSI stream, adults with an FASD or autism spectrum diagnosis plus significant adaptive-functioning limitations. Apply from age 16; supports can be life-long","note":"There are two eligibility streams. Developmental Disability needs a psychologist's cognitive and adaptive assessments. The Personalized Supports Initiative needs an FASD or ASD diagnosis plus significant daily-living limitations. You do not need an intellectual disability for this stream. These assessments are sometimes already done when you were in school, so ask before arranging new ones.","applyText":"Check CLBC eligibility","applyUrl":"https://www.communitylivingbc.ca/who-does-clbc-support/eligible-clbc-support/","source":"https://www.communitylivingbc.ca/what-support-is-available/","detail":{"about":"Services are delivered through a network of contracted agencies and planned individually with a CLBC facilitator.","coversList":{"lead":"CLBC funds and coordinates:","items":["Residential supports (living in your own place, shared living/home sharing with a contracted family, or staffed homes)","Employment support to find and keep a job","Community inclusion and connection programs","Skill development","Respite for families","Wellness supports for daily responsibilities","Behavioural support" ]},"steps":["From age 16, ask your MCFD/CYSN worker about transition planning to CLBC","Contact your nearest CLBC office (1-877-660-2522) — a facilitator explains the required documents and approved assessors","Submit assessments and forms completed by an approved professional (registered psychologist for the DD stream); school-years assessments may be reusable","Once eligibility is confirmed, attend the CLBC Welcome Workshop series and work with your facilitator on a support plan","CLBC connects you to funded services based on the plan and available resources" ],"documents":["Cognitive/psychoeducational assessment by a registered psychologist (DD stream)","Adaptive functioning assessment completed by an approved professional","Confirmed FASD or autism spectrum diagnosis for the PSI stream","CLBC eligibility forms completed by approved professionals" ],"tips":["Start at 16, because assessments and planning take time. What funded support you get, and when, depends on how urgent your situation is and the funding CLBC has at the time of your request.","If you were assessed in school, ask the school district for copies. You may not need a new assessment.","Not eligible under the DD stream? Ask specifically about the Personalized Supports Initiative (PSI)","Respite or equivalent funding is commonly the first service offered to families of transitioning youth. Ask your facilitator what is available in your region.","Adults on CLBC services usually also qualify for BC PWD disability assistance. Apply for both." ],"time":"When funded support starts depends on how urgent your situation is and the amount of funding CLBC has at the time of the request.","phone":"1-877-660-2522"}},{"id":"bc-csg-students-disabilities","needsPractitioner":true,"name":"Canada Student Grant for Students with Disabilities (StudentAid BC)","level":"British Columbia","category":"Education","amount":"$2,800 per program year","summary":"A grant of $2,800 per program year (August 1 to July 31) that you do not repay. It is for post-secondary students with a permanent, or persistent or prolonged, disability. In B.C. it is handled through your StudentAid BC application.","requires":["bc","student","disabilityDoc" ],"eligibility":{"mode":"all","items":["You qualify for federal student aid.","You are enrolled full-time or part-time at a designated post-secondary institution.","You have a permanent disability, or a persistent or prolonged disability (lasting at least 12 months) verified by a qualified medical assessor." ]},"requiresNote":"You must qualify for federal student aid, be enrolled full-time or part-time at a designated post-secondary institution, and have a permanent disability or a persistent or prolonged disability (lasting at least 12 months) verified by a qualified medical assessor.","note":"The current amount reflects a temporary 40% federal increase that runs until July 31, 2027. Once StudentAid BC verifies your disability status you are automatically considered for the province's other disability grants too. Note: StudentAid BC changed its process in June 2026 — new applicants use the online Disability status application instead of the old Appendix 8 form. This amount is a temporary increase in place until July 31, 2027 — check the current figure before you count on it.","applyText":"Apply through StudentAid BC","applyUrl":"https://studentaidbc.ca/apply/how-to-apply-disability-funding","source":"https://studentaidbc.ca/explore/grants-scholarships/canada-student-grant-students-disabilities","detail":{"about":"This federal grant, delivered through StudentAid BC, helps cover education costs for students with disabilities. It is money you do not pay back, and it is available whether you study full-time or part-time. Disability status can be a permanent disability (lifelong) or a persistent or prolonged disability (12+ months). Once your disability status is verified, you can also use reduced course-load rules (40-59% counts as full-time) and other B.C. disability grants.","aboutList":{"lead":"This federal grant, delivered through StudentAid BC, helps cover education costs for students with disabilities.","items":["It is money you do not pay back, and it is available whether you study full-time or part-time.","Disability status can be a permanent disability (lifelong) or a persistent or prolonged disability (12+ months).","Once your disability status is verified, you can also use reduced course-load rules (40-59% counts as full-time) and other B.C. disability grants." ]},"steps":["Apply for StudentAid BC full-time or part-time funding online.","In your StudentAid BC account, open the Disability status application in the Forms section (for applications submitted after June 23, 2026).","Download the Disability Verification Form and have a qualified medical assessor complete it. Some disabilities (Specific Learning Disorders) do not require the form and have different verification requirements; check the instructions on the form.","Upload the signed form (if your disability needs it) inside the Disability status application and submit your declaration.","StudentAid BC reviews it (about 6 weeks) and posts the decision to your account; the grant is then included in your funding assessment." ],"documents":["StudentAid BC application (full-time or part-time)","Disability Verification Form completed by a qualified medical assessor (not required for some disabilities, such as Specific Learning Disorders)","Social Insurance Number and B.C. ID for your StudentAid BC account" ],"tips":["You can submit the disability verification any time. You do not have to wait for your loan application to finish.","Permanent disabilities never need re-verification. Persistent or prolonged disabilities are re-verified when you enter repayment or after a break of more than 5 years.","If you already get provincial disability assistance (PWD), tell your school's financial aid office. It can affect how your funding is set up." ],"time":"About 6 weeks for disability verification","phone":"1-800-561-1818"}},{"id":"bc-csg-services-equipment","needsPractitioner":true,"name":"Canada Student Grant for Services and Equipment – Students with Disabilities","level":"British Columbia","category":"Education","amount":"Up to $20,000 per loan year","summary":"Up to $20,000 per year for disability-related education services and equipment, such as notetakers, tutors, interpreters and technical aids. It is for post-secondary students with disabilities and goes through StudentAid BC.","requires":["bc","student","disabilityDoc" ],"eligibility":{"mode":"all","items":["You qualify for a federal student loan.","You study full-time or part-time at a designated institution.","You have a verified permanent or persistent/prolonged disability.","You have exceptional education-related costs caused by your disability." ]},"requiresNote":"You must qualify for a federal student loan, study full-time or part-time at a designated institution, have a verified permanent or persistent/prolonged disability, and have exceptional education-related costs caused by your disability.","note":"This grant adds to the Canada Student Grant for Students with Disabilities ($2,800 a year until July 31, 2027). If costs remain after the full $20,000, B.C.'s Assistance Program for Students with Disabilities can add up to $10,000-$12,000.","applyText":"Apply through StudentAid BC","applyUrl":"https://studentaidbc.ca/apply/how-to-apply-disability-funding","source":"https://studentaidbc.ca/explore/grants-scholarships/canada-student-grant-services-and-equipment-students-disabilities","detail":{"about":"This grant pays for the specific services and equipment you need because of your disability while studying — things like notetakers, tutors, interpreters, assistive software and other technical aids. It is non-repayable and is assessed through your StudentAid BC application after your disability status is verified.","steps":["Complete a StudentAid BC application and get your disability status verified (Disability Verification Form from a qualified medical assessor; some disabilities, such as Specific Learning Disorders, have different verification requirements — see the form's instructions).","Work with your school's accessibility services office to identify the services and equipment you need.","Your school's accessibility services officer sends the Equipment Request form to Assistive Technology BC (for equipment), or the Services Request form to StudentAid BC (for services).","For equipment, Assistive Technology BC contacts you to review your needs and your equipment is ordered. For services, you get a notification when your request is complete." ],"documents":["Verified disability status with StudentAid BC","Documentation of the services or equipment you need and their costs (your school's accessibility office helps prepare this)" ],"tips":["Book an appointment early with your school's accessibility services office. They know this process well and often start the paperwork for you.","Keep receipts for everything the grant pays for." ],"time":"About 6 weeks for disability verification, then with your funding assessment","phone":"1-800-561-1818"}},{"id":"bc-access-grant-students-disabilities","needsPractitioner":true,"name":"B.C. Access Grant for Students with Disabilities","level":"British Columbia","category":"Education","amount":"Up to $1,560 per program year ($30 per week of study)","summary":"Non-repayable grant money that replaces B.C. student loans for full-time students with a disability, so you borrow less.","requires":["bc","student","disabilityDoc" ],"eligibility":{"mode":"all","items":["You are enrolled in a full-time program at a designated public post-secondary school in B.C.","You qualify for federal and provincial student financial aid.","You have a permanent disability, or a persistent or prolonged disability as defined by the Canada Student Financial Assistance Program." ],"note":"Students who received this grant at another school in 2025/26, for the same program at the same school, may request to continue until their program is complete or July 31, 2029, whichever is first."},"requiresNote":"You may be eligible if you are enrolled in a full-time program at a designated public post-secondary school, you qualify for federal and provincial student financial aid, and you have a permanent disability, or a persistent or prolonged disability as defined by the Canada Student Financial Assistance Program. See the limited continuing-grant exception below.","note":"Only available to students attending B.C. public post-secondary schools. Students enrolled at another school in 2025/26 who received this grant for the same program at the same school may request to continue until their program is complete or until July 31, 2029, whichever occurs first. It replaces B.C. student loan funding with grant funding, so it lowers what you have to pay back.","applyText":"See how to apply for disability funding","applyUrl":"https://studentaidbc.ca/explore/grants-scholarships/bc-access-grant-students-disabilities","source":"https://studentaidbc.ca/explore/grants-scholarships/bc-access-grant-students-disabilities","detail":{"about":"This non-repayable grant replaces B.C. student loan funding with grant funding for eligible full-time students with a disability at B.C. public post-secondary schools (a limited exception applies to students already receiving it at another school), reducing the amount they borrow.","steps":["Apply for full-time StudentAid BC funding for the study period","If disability status is not already verified, submit the StudentAid BC Disability Verification Form completed by an accepted medical assessor","Confirm that your school is a B.C. public post-secondary institution, or ask about continuing if you received this grant there in 2025/26","Review the assessment notice in your StudentAid BC account; the grant is assessed with the aid application" ],"documents":["StudentAid BC application","Disability Verification Form if status is not already verified","Any follow-up financial information StudentAid BC requests" ],"tips":["There is no separate grant application after disability status is verified","Contact the school's accessibility services office early for accommodations and related disability funding" ],"time":"Assessed with the StudentAid BC application","phone":"1-800-561-1818"}},{"id":"bc-supplemental-bursary-students-disabilities","needsPractitioner":true,"name":"B.C. Supplemental Bursary for Students with Disabilities","level":"British Columbia","category":"Education","amount":"$800 per program year full-time, or $400 per program year part-time","summary":"A bursary you do not repay, to help with the cost of post-secondary education. It is for students with a permanent, or persistent or prolonged, disability. You may be eligible as a full-time or part-time student if you qualify for the Canada Student Grant for Students with Disabilities.","requires":["bc","student","disabilityDoc" ],"requiresNote":"Full-time means a course load of 40% or more; part-time means 20% to 39%. Available to students attending B.C. public post-secondary schools only. You may be eligible if you qualify for the Canada Student Grant for Students with Disabilities.","note":"There is a transition rule: students enrolled at a school other than a B.C. public school in 2025/26 who received this bursary for the same program at the same school may request to continue receiving it until their program is complete, or until July 31, 2029, whichever occurs first.","applyText":"See how to apply for disability funding","applyUrl":"https://studentaidbc.ca/explore/grants-scholarships/bc-supplemental-bursary-students-disabilities","source":"https://studentaidbc.ca/explore/grants-scholarships/bc-supplemental-bursary-students-disabilities","detail":{"about":"This non-repayable bursary helps eligible full-time and part-time students with a permanent, or persistent or prolonged, disability pay post-secondary education costs at B.C. public post-secondary schools.","steps":["Apply for StudentAid BC full-time or part-time funding for the study period","Submit the Disability Verification Form if StudentAid BC has not already verified disability status","Confirm that the school and course load meet the bursary rules","Review the StudentAid BC assessment notice; the bursary is assessed automatically when the conditions are met" ],"documents":["StudentAid BC aid application","Disability Verification Form when needed","School and course-load information" ],"tips":["A 40% course load counts as full-time for this bursary; 20% to 39% counts as part-time","Ask StudentAid BC about the published transition rule if you received this bursary at a non-public school in 2025/26" ],"time":"Assessed with the StudentAid BC application","phone":"1-800-561-1818"}},{"id":"bc-assistance-program-students-disabilities","needsPractitioner":true,"name":"B.C. Assistance Program for Students with Disabilities","level":"British Columbia","category":"Education","amount":"Up to $10,000, or up to $12,000 if an attendant is required at school","summary":"Funding for exceptional education-related services and adaptive equipment. Use it after the federal services and equipment grant runs out.","requires":["bc","student","disabilityDoc" ],"eligibility":{"mode":"all","items":["You are enrolled at a designated private or public post-secondary institution in B.C.","You have a permanent disability, or a persistent or prolonged disability." ],"note":"It also covers students in developmental programs or courses."},"requiresNote":"You are enrolled at a designated private or public post-secondary institution in B.C. and have a permanent disability, or a persistent or prolonged disability. It also covers students in developmental programs or courses.","note":"You can only get this grant once you have used up all available funds through the Canada Student Grant for Services and Equipment – Students with Disabilities. Apply for that federal grant first. The page does not say whether these amounts are per year or a lifetime limit.","applyText":"See how to apply for disability funding","applyUrl":"https://studentaidbc.ca/explore/grants-scholarships/bc-assistance-program-students-disabilities","source":"https://studentaidbc.ca/explore/grants-scholarships/bc-assistance-program-students-disabilities","detail":{"about":"This grant funds exceptional education-related services and adaptive equipment after all available funding from the Canada Student Grant for Services and Equipment – Students with Disabilities has been used. Apply for the federal grant first.","steps":["Have StudentAid BC verify your disability status","Meet with the school's accessibility services office to document disability-related services and equipment","Apply first for the Canada Student Grant for Services and Equipment – Students with Disabilities","If eligible costs exceed that grant, have the accessibility office submit the B.C. Assistance Program request and quotes","Wait for written approval before purchasing equipment or committing to services" ],"documents":["Verified disability status","Accessibility-services assessment of required services or equipment","Supplier quotes or service-cost estimates","Evidence that the federal services-and-equipment grant has been used" ],"tips":["Do not buy equipment before you have written funding approval","The official page does not say whether the maximum is annual or lifetime. Ask StudentAid BC before you plan around it." ],"time":"Varies with assessment, quotes and funding review","phone":"1-800-561-1818"}},{"id":"bc-learning-disability-assessment-bursary","needsPractitioner":true,"name":"Learning Disability Assessment Bursary","level":"British Columbia","category":"Education","amount":"Up to $3,500","summary":"Helps with the up-front costs of a learning disability assessment. This assessment is what opens the door to disability funding and academic accommodations.","requires":["bc","student","learningDisability","bcLdAssessmentReferral" ],"eligibility":{"mode":"all","items":["You qualify for student funding through StudentAid BC.","You are enrolled full-time or part-time in post-secondary level courses at a designated public post-secondary institution in B.C.","The accessibility services office at your school has recommended that you have a learning disability assessment." ]},"requiresNote":"You qualify for student funding through StudentAid BC, you are enrolled full-time or part-time in post-secondary level courses at a designated public post-secondary institution in B.C., and the accessibility services office at your school has recommended that you have a learning disability assessment.","note":"Your school's accessibility services office must recommend you. This is part of the eligibility. Start by contacting the accessibility services office at the school you plan to attend.","applyText":"Contact your school's accessibility services office","applyUrl":"https://studentaidbc.ca/explore/grants-scholarships/learning-disability-assessment-bursary","source":"https://studentaidbc.ca/explore/grants-scholarships/learning-disability-assessment-bursary","detail":{"about":"This bursary covers up to $3,500 of the up-front cost of a learning disability assessment when the accessibility services office at an eligible B.C. public post-secondary institution recommends the assessment.","steps":["Apply for StudentAid BC funding and confirm that the school is an eligible B.C. public post-secondary institution","Meet with the school's accessibility services office and ask whether it recommends a current learning-disability assessment","Have the accessibility office start the bursary process before booking the assessment","Use the approved qualified assessor and submit the required invoice or receipt through the school process" ],"documents":["StudentAid BC funding eligibility","Accessibility-services recommendation","Assessment quote or invoice and the completed assessment documentation requested by the school" ],"tips":["Start with accessibility services. Booking an assessment on your own does not make you eligible for the bursary.","Ask how the assessor will be paid and what amount, if any, you must pay up front" ],"time":"Ask the school's accessibility services office","phone":"StudentAid BC: 1-800-561-1818"}},{"id":"bc-access-grant-deaf-students","needsPractitioner":true,"name":"B.C. Access Grant for Deaf Students","level":"British Columbia","category":"Education","amount":"Up to $30,000 per program year, based on financial need assessed by StudentAid BC","summary":"Helps deaf and hard of hearing students with the extra cost of a specialized school that teaches in American Sign Language. It applies only to Gallaudet University in Washington, D.C. and the National Technical Institute for the Deaf in Rochester, New York. Both are in the United States.","requires":["bc","student","disabilityDoc","hearingDisability" ],"eligibility":{"mode":"all","items":["You are deaf or hard of hearing.","Your disability status is verified by StudentAid BC.","You demonstrate financial need.","You are enrolled in a full-time course load of 60% or more.","You are attending an eligible school." ],"note":"The only eligible schools are Gallaudet University in Washington, D.C. and the National Technical Institute for the Deaf in Rochester, New York."},"requiresNote":"You are deaf or hard of hearing, your disability status is verified by StudentAid BC, you demonstrate financial need, you are enrolled in a full-time course load of 60% or more, and you are attending an eligible school. The only eligible schools are Gallaudet University in Washington, D.C. and the National Technical Institute for the Deaf in Rochester, New York.","note":"There is no separate application. If StudentAid BC has verified your disability status and you are attending one of the two eligible schools, they assess your eligibility automatically.","applyText":"Learn more at StudentAid BC","applyUrl":"https://studentaidbc.ca/explore/grants-scholarships/bc-access-grant-deaf-students","source":"https://studentaidbc.ca/sites/all/files/school-officials/policy_manual_26_27.pdf","detail":{"about":"This grant is only for eligible deaf or hard of hearing students attending Gallaudet University in Washington, D.C. or the National Technical Institute for the Deaf in Rochester, New York. StudentAid BC assesses it automatically when disability status is verified and the student attends one of those two schools.","steps":["Apply for StudentAid BC funding for full-time study at Gallaudet University or the National Technical Institute for the Deaf","Submit the Disability Verification Form if StudentAid BC has not already verified deaf or hard-of-hearing status","Provide any financial-need or enrolment information StudentAid BC requests","Review the funding assessment; there is no separate application for this grant" ],"documents":["StudentAid BC application","Verified disability status","Full-time enrolment information for one of the two eligible schools" ],"tips":["Only the two named U.S. institutions qualify","Ask StudentAid BC how cross-border tuition, currency and payments are handled before you commit to costs" ],"time":"Assessed with the StudentAid BC application","phone":"1-800-561-1818"}},{"id":"bc-dental-supplement","eligibility":{"mode":"any","items":["Adults may be able to get basic dental coverage if they receive disability assistance, qualify as a person with persistent multiple barriers (PPMB), or are eligible for general health supplements.","Children under 19 in families on any assistance are covered." ],"note":"Everyone on assistance can get emergency dental treatment to relieve pain. Adults on income assistance may also be eligible for dentures if their complete upper and/or lower teeth were removed in the previous six months to relieve pain."},"name":"Dental Supplements (Income & Disability Assistance)","level":"British Columbia","category":"Health","amount":"Up to $1,000 per 2 calendar years for adults (current period Jan 2025–Dec 2026); up to $2,000 per 2 years for children under 19, plus $1,000/year for hospital dental under general anesthesia","summary":"Basic dental care for people on disability assistance, such as check-ups, fillings, extractions and dentures. The ministry pays the dentist directly. Emergency treatment to relieve pain is covered for everyone on assistance.","requires":["bc","bcAssistanceStatus" ],"requiresNote":"Adults may be able to get basic dental coverage if they receive disability assistance, qualify as a person with persistent multiple barriers (PPMB), or are eligible for general health supplements; children under 19 in families on any assistance are covered. Everyone on assistance can get emergency dental treatment to relieve pain. Adults on income assistance may also be eligible for dentures if their complete upper and/or lower teeth were removed in the previous six months to relieve pain.","note":"The adult limit resets on January 1 of every odd-numbered year. The current $1,000 window runs January 2025 through December 2026. Unused room disappears in January 2027. Amounts and covered services are in BC's health supplements rate table. Check the current limits there.","applyText":"See what's covered","applyUrl":"https://www2.gov.bc.ca/gov/content/family-social-supports/income-assistance/on-assistance/supplements/dental","source":"https://www2.gov.bc.ca/gov/content/family-social-supports/income-assistance/on-assistance/supplements/dental","detail":{"about":"Coverage includes restorations, extractions, preventative care, partial and replacement dentures, and crowns or bridges in certain cases, billed under ministry fee schedules. Adults with eligibility get up to $1,000 over each two-calendar-year period. Children get up to $2,000 plus an extra $1,000 per year for hospital dental treatment under general anesthesia. Emergency dental to relieve pain is available to everyone on assistance regardless of the limit.","aboutList":{"lead":"Coverage includes restorations, extractions, preventative care, partial and replacement dentures, and crowns or bridges in certain cases, billed under ministry fee schedules.","items":["Adults with eligibility get up to $1,000 over each two-calendar-year period.","Children get up to $2,000 plus an extra $1,000 per year for hospital dental treatment under general anesthesia.","Emergency dental to relieve pain is available to everyone on assistance regardless of the limit." ]},"steps":["Confirm you receive disability assistance or otherwise qualify for general health supplements","Book any dentist, denturist or dental hygienist and show your BC Services Card","The office confirms your coverage with the ministry's insurer (Pacific Blue Cross) before treatment","The ministry pays the provider directly — ask in advance about any costs above the fee schedule" ],"documents":["BC Services Card or Personal Health Number" ],"tips":["Ministry fee-schedule rates are below many dentists' usual fees. Ask the office to bill within the schedule, or to tell you the difference before work starts.","Plan larger treatment around the 2-year cycle, so a January reset gives you a fresh $1,000","Dentures have their own rules and limits. Ask the ministry before you order." ],"time":"No application is described on the page — if you receive assistance you may be able to have basic dental costs covered; the provider verifies it at booking","phone":"1-866-866-0800"}},{"id":"bc-additional-home-owner-grant","name":"B.C. Home Owner Grant — additional grant for people with disabilities","level":"British Columbia","category":"Tax","amount":"For 2026, up to $845, or up to $1,045 in a northern and rural area","summary":"A larger property tax grant for B.C. homeowners with a disability, or who live with a relative who has one. It reduces the property tax you owe; it is not a payment.","requires":["bc","homeowner","bcHomeOwnerGrantDisabilityRoute" ],"eligibility":{"mode":"all","items":["You are the registered owner, a Canadian citizen or permanent resident, live in B.C., and occupy the property as your principal residence.","You pay at least $100 in property taxes.","You qualify on one of two routes: you receive provincial disability assistance, hardship assistance or a supplement under the Employment and Assistance for Persons with Disabilities Act; or you pay at least $150 a month for assistance with daily living activities, or have spent at least $2,000 on structural modifications to the home." ]},"requiresNote":"You must be the registered owner, a Canadian citizen or permanent resident, live in B.C., and occupy the property as your principal residence. You must also pay at least $100 in property taxes. You qualify on one of two routes: you receive provincial disability assistance, hardship assistance or a supplement under the Employment and Assistance for Persons with Disabilities Act; or you pay at least $150 a month for assistance with daily living activities, or have spent at least $2,000 on structural modifications to the home.","note":"The higher northern and rural amount ends on January 1, 2027. From that date, every B.C. property gets $570 regular or $845 with the additional amount. There is no separate northern or rural top-up.","applyText":"Apply for the home owner grant","applyUrl":"https://www2.gov.bc.ca/gov/content/taxes/property-taxes/annual-property-tax/home-owner-grant/person-with-disabilities","source":"https://www2.gov.bc.ca/gov/content/taxes/property-taxes/annual-property-tax/home-owner-grant/person-with-disabilities","detail":{"about":"The home owner grant lowers the property tax on your principal residence. For 2026 the regular grant is up to $570, plus an extra $200 for northern and rural properties; from January 1, 2027 it is $570 everywhere. If you are a person with a disability, or you live with a relative who has one, the additional grant raises that to up to $845, or up to $1,045 in a northern and rural area. The 2026 grant threshold is an assessed value of $2,075,000, and the grant is reduced by $5 for each $1,000 of assessed value above it. For Option B (the daily-living or structural-modification route), a health professional must certify on Form B (FIN 74) that the person has a severe mental or physical impairment likely to continue for at least two years. If your assessed value is above the threshold, a separate low income grant supplement may apply when adjusted net income is $32,000 or less.","aboutList":{"lead":"The home owner grant lowers the property tax on your principal residence.","items":["For 2026 the regular grant is up to $570, plus an extra $200 for northern and rural properties; from January 1, 2027 it is $570 everywhere.","If you are a person with a disability, or you live with a relative who has one, the additional grant raises that to up to $845, or up to $1,045 in a northern and rural area.","The 2026 grant threshold is an assessed value of $2,075,000, and the grant is reduced by $5 for each $1,000 of assessed value above it.","Option B is the daily-living or structural-modification route.","For Option B, Form B (FIN 74) requires health-professional certification of a severe mental or physical impairment likely to continue for at least two years.","If your assessed value is above the threshold, a separate low income grant supplement may apply when adjusted net income is $32,000 or less." ]},"steps":["Read the eligibility page for people with disabilities","If you qualify through disability assistance, no health professional form is needed and you may optionally file Form FIN 81, Home Owner Grant Consent for Release of Information","If you qualify on the daily-living or structural-modification route, have a health professional complete Form B (FIN 74), Certificate of Health Professional and Property Owner, with your first application","Apply for the grant each year, through the province rather than your municipality" ],"documents":["Form B (FIN 74), Certificate of Health Professional and Property Owner, for the daily-living or structural-modification route on a first application","Optionally Form FIN 81, Home Owner Grant Consent for Release of Information","Your property tax notice" ],"tips":["You must apply every year, the grant is not automatic","You must still pay at least $100 in property taxes","The higher northern and rural amount ends January 1, 2027" ],"phone":"Toll free 1-888-355-2700, or 250-387-0555"}},{"id":"bc-home-reno-tax-credit","name":"Home Renovation Tax Credit for Seniors and Persons with Disabilities","level":"British Columbia","category":"Tax","amount":"Up to $1,000 per year (10% of up to $10,000 in eligible renovation costs), refundable","summary":"A refundable B.C. tax credit. It is worth 10% of up to $10,000 in accessibility renovations to your principal residence, so up to $1,000 back per year. It is for people who qualify for the disability tax credit, seniors 65+, and family members who live with them.","requires":["bc","homeRenoCandidate","homeowner","bcHomeRenoSpend" ],"eligibility":{"mode":"all","items":["You are a B.C. resident at year end.","You either qualify for the federal disability tax credit (any age), are 65 or older, or are a family member living with (and claiming for) an eligible person." ]},"requiresNote":"You must be a B.C. resident at year end and either qualify for the federal disability tax credit (any age), be 65 or older, or be a family member living with (and claiming for) an eligible person.","note":"Refundable means you get the money even if you owe no tax. Renovations must improve access, mobility or safety in the home. Examples are ramps, grab bars, walk-in tubs, widened doors and stair lifts. General repairs and upgrades that add value do not count. Active for the 2025 and 2026 tax years.","applyText":"Claim on your tax return","applyUrl":"https://www2.gov.bc.ca/gov/content/taxes/income-taxes/personal/credits/seniors-renovation","source":"https://www2.gov.bc.ca/gov/content/taxes/income-taxes/personal/credits/seniors-renovation","detail":{"about":"This credit helps cover permanent renovations that make your principal residence more accessible, functional or safe — improving access to the home or land, helping you move around and function at home, or reducing risk of harm. Qualifying examples include wheelchair ramps, grab bars, handrails, walk-in bathtubs, raised toilets, lowered cupboards, adjustable counters, widened doorways, non-slip flooring, motion-activated lighting and stair lifts. Aesthetic upgrades, appliances, regular repairs, HVAC, windows, and mobility equipment like walkers or wheelchairs do not qualify.","aboutList":{"lead":"This credit helps cover permanent renovations that make your principal residence more accessible, functional or safe — improving access to the home or land, helping you move around and function at home, or reducing risk of harm.","items":["Qualifying examples include wheelchair ramps, grab bars, handrails, walk-in bathtubs, raised toilets, lowered cupboards, adjustable counters, widened doorways, non-slip flooring, motion-activated lighting and stair lifts.","Aesthetic upgrades, appliances, regular repairs, HVAC, windows, and mobility equipment like walkers or wheelchairs do not qualify." ]},"steps":["Complete eligible renovations to your principal residence and keep all receipts.","At tax time, complete Schedule BC(S12) — the B.C. Home Renovation Tax Credit for Seniors and Persons with Disabilities form.","Enter your renovation expenses beside box 60480 on the British Columbia Credits form (BC479).","File with your T1 return; the credit is refunded even if you owe no tax." ],"documents":["Receipts from suppliers and contractors (with GST/HST numbers where applicable)","Disability tax credit eligibility (if claiming as a person with a disability)" ],"tips":["Family members who live with a senior or a person with a disability can claim the credit for work on the shared home.","The main purpose of the renovation cannot be to increase your property value. Keep documents that show the accessibility purpose.","You can pair this with the federal Home Accessibility Tax Credit and Multigenerational Home Renovation Credit on the same expenses where the rules allow. Ask your tax preparer." ],"time":"Claimed annually at tax time","phone":"1-800-959-8281"}},{"id":"bc-raha","needsPractitioner":true,"name":"B.C. Rebate for Accessible Home Adaptations (BC RAHA)","level":"British Columbia","category":"Health & equipment","amount":"Up to $20,000 in rebates, as a lifetime maximum per household","summary":"A B.C. rebate that pays back part of the cost of home adaptations for independent living. It is for lower-income households where someone has a permanent disability or loss of physical ability. Homeowners apply on their own. Tenants apply together with their landlord.","requires":["bc","homeAccessNeed","rahaEligibility" ],"eligibility":{"mode":"all","items":["You or someone in your household has a permanent disability or loss of physical ability.","The home is the principal residence of the owner(s) and of the person needing the adaptations.","Your combined household assets are less than $100,000, not counting the value of the home being adapted.","Your combined annual gross household income is less than $146,270.00.","Everyone who owns the home, and the person needing the adaptations, is a Canadian citizen, a permanent resident of Canada, a refugee sponsored by the Government of Canada, or someone who has applied for refugee status, and not under sponsorship." ],"note":"BC Housing also checks your community together with the assessed value of the home, so there is no single home-value cutoff. For this program \"household\" means the owner(s) plus any relative permanently living in the home. Some adaptations need an assessment from an occupational therapist or physical therapist."},"requiresNote":"You or someone in your household must have a permanent disability or loss of physical ability, and the home must be the principal residence of the owner(s) and of the person needing the adaptations. Your combined household assets must be less than $100,000, not counting the value of the home being adapted, and your combined annual gross household income must be less than $146,270.00. BC Housing also checks your community together with the assessed value of the home, so there is no single home-value cutoff. Everyone who owns the home, and the person needing the adaptations, must be a Canadian citizen, a permanent resident of Canada, a refugee sponsored by the Government of Canada, or someone who has applied for refugee status, and not under sponsorship. For this program \"household\" means the owner(s) plus any relative permanently living in the home. Some adaptations need an assessment from an occupational therapist or physical therapist.","note":"Adaptations completed before BC Housing gives written approval are not eligible for a rebate, except emergency adaptations required before hospital release. Once approved you have 180 days to finish the work.","applyText":"Apply for BC RAHA","applyUrl":"https://www.bchousing.org/housing-assistance/BC-RAHA","source":"https://www.bchousing.org/housing-assistance/BC-RAHA","detail":{"about":"BC RAHA provides rebates so people can adapt their home for independent living. The lifetime maximum is $20,000 per household, and individual adaptations have their own caps set out in BC Housing.s Maximum Rebate Schedule. Applications are taken first-come, first-served until the funding for the year runs out, and the funding renews on April 1 each year. BC Housing aims to assess a completed application within 8 weeks, and pays within 3 weeks of receiving the final documents once the work is done. If you rent, the unit must be a legal, self-contained home with its own full kitchen and bathroom, and the tenant must be living independently rather than in assisted living. Tenants apply jointly with their landlord, and members of a housing co-operative use the landlord-and-tenant route.","aboutList":{"lead":"BC RAHA provides rebates so people can adapt their home for independent living.","items":["The lifetime maximum is $20,000 per household, and individual adaptations have their own caps set out in BC Housing's Maximum Rebate Schedule.","Applications are taken first-come, first-served until the funding for the year runs out, and the funding renews on April 1 each year.","BC Housing aims to assess a completed application within 8 weeks, and pays within 3 weeks of receiving the final documents once the work is done.","If you rent, the unit must be a legal, self-contained home with its own full kitchen and bathroom, and the tenant must be living independently rather than in assisted living.","Tenants apply jointly with their landlord, and members of a housing co-operative use the landlord-and-tenant route." ]},"steps":["Check the property and adaptation eligibility pages, and use the BC RAHA Calculator to see whether you might qualify","Get an occupational therapist or physical therapist assessment if your adaptation needs one","Submit the BC RAHA Homeowner Application, or the Landlord and Tenant Application if you rent, with the documents it lists","Wait for written approval from BC Housing before any work starts, then complete the work within 180 days" ],"documents":["The BC RAHA Homeowner Application, or the Landlord and Tenant Application if you rent","An occupational therapist or physical therapist assessment where the adaptation requires one","Contractor quotes","Proof of household income and assets as listed in the application" ],"tips":["Do not start work before written approval, because anything finished first is not eligible","Funding renews April 1 and applications are first-come first-served, so apply early in the year","You have 180 days from written approval to finish","The $20,000 is a lifetime maximum for the household, not per adaptation","BC Housing publishes an eligibility calculator at bcrahacalculator.bchousing.org. It takes a few minutes. It tells you if you are likely to qualify before you fill in the full application." ],"time":"BC Housing aims to assess completed applications within 8 weeks, and pays within 3 weeks after the work is done and documents are received.","phone":"604-433-2218 in the Lower Mainland, or toll free 1-800-257-7756"}},{"id":"bc-work-able-internship","name":"Work-Able Accessible Employment Program (BC Public Service)","level":"British Columbia","category":"Work","amount":"Paid BC Public Service internship of up to 24 months","summary":"A paid internship program in the BC Public Service for recent post-secondary graduates who self-identify as having a disability. This can be any physical, sensory, neurological, visible or invisible disability.","requires":["bc","age18plus","employmentActive","bcWorkAbleSelfIdentify","recentGraduate" ],"eligibility":{"mode":"all","items":["You are a recent post-secondary graduate with a two-year diploma, associate degree, bachelor's degree, master's degree or doctorate from a recognized post-secondary institution.","Your graduation date is within 3 years of the program start date.","You self-identify as having a disability, are a resident of British Columbia and are legally entitled to work in Canada." ],"note":"You do not have to disclose your specific diagnosis."},"requiresNote":"You must be a recent post-secondary graduate with a two-year diploma, associate degree, bachelor's degree, master's degree or doctorate from a recognized post-secondary institution, with a graduation date within 3 years of the program start date, self-identify as having a disability, are a resident of British Columbia, and are legally entitled to work in Canada. You do not have to disclose your specific diagnosis.","note":"Intake runs every year. Applications for the 2026/27 cohort are closed. The page says to check back in Spring 2027 for information on the 2027/28 intake. Graduates keep access to internal BC Public Service job postings for 24 months after they finish the program.","applyText":"Check intake dates and apply","applyUrl":"https://www2.gov.bc.ca/gov/content/careers-myhr/job-seekers/internship-co-op-opportunities/work-able","source":"https://www2.gov.bc.ca/gov/content/careers-myhr/job-seekers/internship-co-op-opportunities/work-able","detail":{"about":"Work-Able coordinates paid internship opportunities across the BC Public Service for recent graduates with disabilities, for up to 24 months. Participants get government work experience, a peer cohort of other graduates with disabilities, exposure to different career paths, and post-program access to internal job postings.","steps":["Check the Work-Able page in Spring 2027 for information on the 2027/28 intake, or contact the Work-Able team to be notified when the next application period opens.","Confirm you graduated within 3 years of the program start date.","Apply online during the intake window; you self-identify as having a disability without disclosing a diagnosis.","If selected, you are placed in a paid position with a ministry." ],"documents":["Proof of post-secondary graduation (within 3 years of program start)","Resume" ],"tips":["Contact the Work-Able team to be notified when the next application period opens.","Workplace accommodations are part of the program's design, so you do not need to negotiate them alone." ],"time":"Annual intake; internships run up to 24 months"}},{"id":"bc-workbc-assistive-technology","name":"WorkBC Assistive Technology Services","level":"British Columbia","category":"Equipment","amount":"Equipment and supports funded fully or partially, based on your financial circumstances","summary":"Funding for assistive technology you need to get or keep a job. This includes devices and equipment, ergonomic furniture, communication and hearing devices, ASL interpreting and captioning, and workplace modifications. It even includes vehicle modifications for getting to work.","requires":["bc","age16plus","employmentActive","disabilityDoc" ],"eligibility":{"mode":"all","items":["You are 16 or older.","You are a B.C. resident legally eligible to work.","You are not a full-time student, unless you are in your final year.","You have a work-related barrier due to a disability or functional limitation." ],"note":"Volunteering toward a longer-term employment goal counts. Self-employment counts if you can show proof of regular income."},"requiresNote":"You must be 16 or older, a B.C. resident legally eligible to work, not a full-time student (unless in your final year), and have a work-related barrier due to a disability or functional limitation. Volunteering toward a longer-term employment goal counts, and so does self-employment with proof of regular income.","note":"Covers employment-related needs, including volunteer work that is part of a longer-term employment goal. It does not cover medical treatments and therapies, items for daily living, or employment services such as job coaching or wage subsidies. It is delivered under contract to the province, with regional offices in Burnaby, Kelowna, Nanaimo and Victoria.","applyText":"Apply online","applyUrl":"https://apply.workbc.ca/","source":"https://www.workbc.ca/get-support/assistive-technology-pwd","detail":{"about":"Assistive Technology Services (ATS) removes equipment barriers between you and employment. It funds assistive devices and technology, ergonomic supports like furniture and lighting, restorative supports, ASL interpreting and captioning, communication and hearing devices for work, workplace access modifications, and vehicle modifications needed for employment. How much is covered depends on your financial circumstances.","aboutList":{"lead":"Assistive Technology Services (ATS) removes equipment barriers between you and employment.","items":["It funds assistive devices and technology, ergonomic supports like furniture and lighting, restorative supports, ASL interpreting and captioning, communication and hearing devices for work, workplace access modifications, and vehicle modifications needed for employment.","How much is covered depends on your financial circumstances." ]},"steps":["Apply through WorkBC Online Employment Services (apply.workbc.ca) or contact ATS directly.","An ATS specialist works with you to understand your work barrier and equipment needs.","Approved equipment and services are arranged fully or partially funded." ],"documents":["Proof you are a B.C. resident eligible to work","Information about your job, job offer, self-employment (needs proof of regular income) or volunteer role","Details of the disability-related barrier and equipment needs (ATS helps document this)" ],"tips":["Commuting barriers count. Vehicle modifications and travel-related equipment can be funded when needed for work.","You can use ATS while you have a job to keep it, not just when job hunting.","Email info-ats@workbc.ca if you are unsure whether your situation qualifies." ],"time":"Varies by request; contact ATS for current timelines","phone":"1-844-453-5506"}},{"id":"bc-workbc-employment-services","name":"WorkBC Employment Services","level":"British Columbia","category":"Work","amount":"Free employment services, including work experience and wage subsidies. Funding support for training, transportation, dependent care and employment-related disability supports may be available, typically for clients with an employment plan.","summary":"BC's free public employment service. Help finding work, possible funding support for training, and possible financial supports, with services built specifically for people with disabilities.","requires":["bc","age16plus","bcWorkBcRoute" ],"requiresNote":"Check whether you are eligible by applying online at apply.workbc.ca. Staff can support you in completing your application.","note":"If you have a disability, job search help includes working with employers to shape or customize jobs to meet your needs. Funding for assistive technology is covered by a separate program in this catalog: WorkBC Assistive Technology Services.","applyText":"Apply online at WorkBC","applyUrl":"https://www.workbc.ca/get-support/workbc-centre-services","source":"https://www.workbc.ca/get-support/workbc-centre-services","detail":{"about":"WorkBC centres provide free employment services including job-search help, work experience and wage subsidies. Funding support for training and employment-related disability supports may be available, typically for clients with an employment plan. A WorkBC counsellor reviews eligibility and builds the plan with you.","aboutList":{"lead":"WorkBC centre services and possible funding:","items":["Free employment services including job-search help, work experience and wage subsidies.","Funding support for training and employment-related disability supports may be available, typically for clients with an employment plan.","A WorkBC counsellor reviews eligibility and builds the plan with you." ]},"steps":["Get a Basic BCeID or set up online access with a BC Services Card","Register for Online Employment Services and select WorkBC Employment Services","Complete the application, including work status, barriers and the WorkBC centre you want to use","Upload requested documents and communicate with the centre through the secure portal","Meet an employment counsellor to confirm eligibility and create a personal action plan" ],"documents":["Valid Social Insurance Number","Information showing you are legally allowed to work in B.C.","Work and education history","Information about disability-related employment barriers if requesting specialized supports" ],"tips":["You do not need a phone number or a fixed mailing address to submit the online application","Centre staff can help you complete the application","People with disabilities can qualify in more work or student situations. These include being at risk of losing a job or being in the final year of school","Financial supports are typically for clients who are case managed through WorkBC. That means you have an employment plan and work with an employment specialist.","Dependent care covers childcare while you are job searching." ],"time":"The local WorkBC centre decides eligibility after reviewing the completed application","phone":"Contact your selected WorkBC centre"}},{"id":"bc-fuel-tax-refund-disabilities","name":"Fuel Tax Refund for Persons with Disabilities","level":"British Columbia","category":"Transit","amount":"You may receive a fuel tax refund of up to $500 each calendar year for a qualifying vehicle registered in the program, and a 25% discount off ICBC basic Autoplan insurance (including electric vehicles)","summary":"Refunds the provincial fuel tax on a vehicle you own, lease or have an ownership interest in. If you are eligible for the program, you may also receive 25% off your basic ICBC insurance.","requires":["bc","vehicleOwner","bcFuelTaxRoute" ],"eligibility":{"mode":"any","items":["B.C. Disability Assistance Certification","Letter from the British Columbia Aboriginal Network on Disability Society (BCANDS) confirming you receive disability assistance or a supplement from the Social Assistance for Persons with Disability program in accordance with the Indigenous Services Canada Social Development Program – Policy and Procedures Handbook – BC Region. The letter from BCANDS must state the date you were enrolled in the Social Assistance for Persons with Disability program and the end date (if applicable)","Letter from Veterans' Affairs confirming you receive a 100% disability pension. This letter must state: That you receive a 100% disability pension through service while in His Majesty's forces, and The date you began receiving the disability pension","Letter from the Canadian National Institute for the Blind (CNIB) confirming permanent sight impairment. The letter from CNIB must state: That you have a permanent sight impairment, That you are not eligible to hold a driver's licence, and The effective date of the impairment","Medical certification confirming one of the following conditions: Loss of a limb","Medical certification confirming one of the following conditions: Permanent dependence on a wheelchair","Medical certification confirming one of the following conditions: Complete and permanent functional loss of lower limbs","Medical certification confirming one of the following conditions: Permanent impairment of movement to the extent that use of public transportation would be hazardous (whether or not it's available)","Medical certification confirming one of the following conditions: Permanent mental disability to the extent that use of public transportation would be hazardous (whether or not it's available)","Medical certification confirming one of the following conditions: Permanent sight impairment to the extent that you're not eligible to hold a driver's licence" ],"note":"You must be 16 or older and must also own or lease a vehicle, or have an ownership interest in a vehicle"},"requiresNote":"You must be 16 years old or older and own or lease a vehicle, or have an ownership interest in a vehicle. Confirm your disability through one of the routes below, including all the listed letter conditions and dates.","note":"Register first. You can apply for a refund only after your registration is confirmed. Register with the Ministry of Finance online or with a downloadable form. Then you get a registration confirmation letter. After that, you can claim refunds.","applyText":"Register for the fuel tax refund","applyUrl":"https://www2.gov.bc.ca/gov/content/taxes/sales-taxes/motor-fuel-carbon-tax/refund-disabilities","source":"https://www2.gov.bc.ca/gov/content/taxes/sales-taxes/motor-fuel-carbon-tax/refund-disabilities","detail":{"about":"This is a two-stage program: register the person and qualifying vehicle first, then claim fuel-tax refunds using original receipts after the registration effective date.","steps":["Gather the disability confirmation and vehicle ownership or lease information listed by the Ministry of Finance","Register online or submit form FIN 119 with every required supporting document","Wait for the mailed registration confirmation letter and note the registration effective date","Keep original fuel receipts from that effective date onward","Submit the refund application with eligible receipts; the ministry must receive a claim within four years of the fuel purchase" ],"documents":["Accepted disability confirmation or medical certification, with all the conditions and dates listed above","Your driver's licence number; if you do not have a valid driver's licence, a copy of other government-issued ID confirming your date of birth and legal name","Vehicle registration or lease information; if you are not the registered owner or lessee but have an ownership interest, a completed Appendix 3 – Vehicle Ownership Declaration","If you are registering and signing on behalf of another person who is 19 or older, a copy of a power of attorney or representation agreement with the registration documents","Original receipts showing date, fuel type, litres, and seller name and address" ],"tips":["Do not claim fuel bought before the registration effective date","Incomplete registration packages delay approval" ],"time":"Processing takes up to 4 weeks. Registration must be approved before any refund claim","phone":"1-877-388-4440"}},{"id":"bc-icbc-disability-discount","name":"ICBC Disability Discount (Basic Autoplan)","level":"British Columbia","category":"Transit","amount":"You may receive 25% off ICBC basic Autoplan insurance (including electric vehicles) if you are eligible for the fuel tax refund program for persons with disabilities","summary":"If you are eligible for the provincial fuel tax refund program for persons with disabilities, you may receive 25% off the basic part of your ICBC vehicle insurance.","requires":["bc","bcVehicleDisabilityRoute","vehicleOwner","bcFuelTaxRegistered" ],"requiresNote":"You must be 16 or older. You may receive it if you are eligible for the Fuel Tax Refund Program for Persons with Disabilities — the same disability confirmations listed there apply.","note":"Register for the Fuel Tax Refund Program for Persons with Disabilities first. Then talk to an Autoplan broker about applying the discount to your policy.","applyText":"Start with the fuel tax refund program","applyUrl":"https://www2.gov.bc.ca/gov/content/taxes/sales-taxes/motor-fuel-carbon-tax/refund-disabilities","source":"https://www2.gov.bc.ca/gov/content/taxes/sales-taxes/motor-fuel-carbon-tax/refund-disabilities","detail":{"about":"The discount is applied through an Autoplan broker after the Ministry of Finance registers you in the Fuel Tax Refund Program for Persons with Disabilities.","steps":["Complete the provincial Fuel Tax Refund Program registration","Wait for the Ministry of Finance registration confirmation","Bring the confirmation and vehicle information to an Autoplan broker","Ask the broker to apply the disability discount to eligible Basic Autoplan coverage" ],"documents":["Fuel Tax Refund Program registration confirmation","Vehicle registration and current Autoplan policy information","Identification requested by the broker" ],"tips":["The discount applies to Basic Autoplan, not to every optional coverage charge","Ask the broker when the discount will start if your policy is already active","Electric vehicles can get the insurance discount even though they do not use fuel" ],"time":"Ask an Autoplan broker after provincial registration is confirmed"}},{"id":"bc-property-tax-deferment-disabilities","name":"Property Tax Deferment for Persons with Disabilities","level":"British Columbia","category":"Tax","amount":"A low-interest provincial loan that pays your annual property taxes; interest is 2% above the prime rate, plus a $60 application fee and a $10 annual renewal fee","summary":"Instead of you paying your property taxes each year, the province pays them and registers a loan against your home. You repay when you sell or transfer it.","requires":["bc","age18plus","dailyLivingLimit","bcPwdStatus","homeowner","citizenPR","bcDefermentProperty" ],"eligibility":{"mode":"all","items":["You are designated as a person with disabilities under the Employment and Assistance for Persons with Disabilities Act — a severe mental or physical impairment likely to continue at least two years that directly and significantly restricts your ability to perform daily living activities and requires an assistive device, supervision, or the services of an assistance animal.","You have and maintain a minimum equity of 25 percent of the property's assessed value." ]},"requiresNote":"You must be designated as a person with disabilities under the Employment and Assistance for Persons with Disabilities Act — a severe mental or physical impairment likely to continue at least two years that directly and significantly restricts your ability to perform daily living activities and requires an assistive device, supervision, or the services of an assistance animal. You must also have and maintain a minimum equity of 25 percent of the property's assessed value.","note":"The 25 percent equity rule means your charges plus deferred taxes cannot be more than 75 percent of the BC Assessment value of your home. For taxes deferred for the 2026 tax year and later, interest compounds monthly. You are not charged interest on the application or renewal fees.","applyText":"Check eligibility and apply","applyUrl":"https://www2.gov.bc.ca/gov/content/taxes/property-taxes/annual-property-tax/property-tax-deferment-program/eligibility","source":"https://www2.gov.bc.ca/gov/content/taxes/property-taxes/annual-property-tax/property-tax-deferment-program/eligibility","detail":{"about":"Property tax deferment is a loan secured against the home, not a grant. Interest and fees are added to the account, and eligibility must be maintained.","steps":["Check the regular-program eligibility rules, including B.C. residency, citizenship or permanent residency, principal residence and at least 25% equity","Pay all previous-year property taxes, utility user fees, penalties and interest","Gather each owner's Social Insurance Number, birth date and property-tax notice","Apply online between May 1 and December 31; applying after the local due date can still cause late penalties","Check application status and renew each year unless you choose and remain eligible for auto-renewal" ],"documents":["Current property-tax notice and jurisdiction information","Social Insurance Number and date of birth for each owner","PWD designation information or physician certification requested by the program","Mortgage and other registered-charge information needed to verify equity" ],"tips":["Apply before the municipality's tax due date. This avoids late penalties while the province reviews your application","Confirm the current interest rate. Know that interest compounds for 2026 and later deferrals","Do not use this program if you have already paid this year's property taxes in full" ],"time":"Applications and renewals are accepted May 1 to December 31 each year"}},{"id":"bc-sales-tax-credit","name":"B.C. Sales Tax Credit","level":"British Columbia","category":"Tax","amount":"Up to $75 for yourself and $75 for a cohabiting spouse or common-law partner","summary":"A small refundable credit you claim on your tax return. It is not a disability program. It helps people with a low income who file a return.","requires":["bc","bcStcAgeOrFamily","lowIncome" ],"eligibility":{"mode":"all","items":["You were a B.C. resident on December 31.","You were 19 or older, or had a spouse or common-law partner, or were a parent." ]},"requiresNote":"You were a B.C. resident on December 31 and were either 19 or older, or had a spouse or common-law partner, or were a parent.","note":"The credit goes down by 2% of your net income over $15,000 if you are single. For couples, it goes down by 2% of family net income over $18,000. So it phases out at a low income. It is refundable up to the amount that is more than the income tax you owe. This means you can get it even if you owe no tax.","applyText":"See how to claim it","applyUrl":"https://www2.gov.bc.ca/gov/content/taxes/income-taxes/personal/credits/sales-tax","source":"https://www2.gov.bc.ca/gov/content/taxes/income-taxes/personal/credits/sales-tax","detail":{"about":"Claim it when you file your T1 Income Tax Return using the British Columbia Credits form (BC479). You must claim within three years after the end of the tax year.","steps":["File the federal T1 income tax return for the year","Complete the B.C. Credits form BC479","Enter the sales tax credit claim from BC479 with the return","If you missed it, ask the Canada Revenue Agency to adjust the return within three years after the tax year" ],"documents":["Tax slips and income information for the year","Spouse or common-law partner income information when applicable","Form BC479" ],"tips":["File even if you owe no income tax, because this credit is refundable","The credit depends on your income and is not only for people with disabilities","Ask the CRA if you have questions about the tax return and refund" ],"time":"Claimed with the annual tax return","phone":"Canada Revenue Agency: 1-800-959-8281"}},{"id":"vancouver-leisure-access","name":"Leisure Access Program (LAP)","level":"Vancouver","category":"Recreation","amount":"Free admission to pools and rinks, 50% off fitness centre admission and group swimming and skating lessons, and a pass valid for 3 years","summary":"Vancouver's low-income recreation pass. Swimming and skating admission are free; outdoor pools require an online reservation. Fitness centre admission, group swimming and skating lessons and other listed programs are half price.","requires":["bc","vancouver","lowIncome" ],"eligibility":{"mode":"any","items":["Child Disability Benefit: a family with a child up to 17 that receives the Child Disability Benefit, shown on its Canada Child Benefit notice","Disability Tax Credit: you, your spouse or partner, or a dependent aged 18 or older qualifies for the Disability Tax Credit, and your family's combined net income is at or below the table maximum","Income assistance: you receive income assistance or one of the listed provincial or federal subsidies (for example MSDPR assistance, Guaranteed Income Supplement, RAP, SAFER or a valid red bus pass)","Agency referral: you are a client of a non-profit or government agency that can refer you","Asylum seeker or temporary foreign worker: the non-profit or government agency you are a client of refers you (Third Party Referral form)","Low income without income assistance, and you cannot be referred: your net family income is at or below the table maximum","Employment Insurance: you are receiving EI benefits in 2026/2027, and your projected family income is at or below the table maximum" ],"note":"You must be a resident of the City of Vancouver (UBC and the University Endowment Lands are not in the City). Leisure Access is not available to immigrants classified as investors or entrepreneurs. It is also not available to individuals or families with combined interest and other investment income (line 12100) over $1,500, net rental income (line 12600) over $2,000, or capital gains (line 12700) over $2,000."},"requiresNote":"You must be a City of Vancouver resident and meet one of the routes below, including its income or referral conditions and the exclusions.","note":"Starting January 1, 2026, Leisure Access passes are valid for 3 years. A pass issued in 2026 does not expire until 2029. Note that UBC and the University Endowment Lands are not in the City of Vancouver.","applyText":"Apply for a Leisure Access pass","applyUrl":"https://vancouver.ca/parks-recreation-culture/leisure-access-card.aspx","source":"https://vancouver.ca/parks-recreation-culture/leisure-access-card.aspx","detail":{"about":"The pass adds free or reduced recreation access to a Vancouver Park Board OneCard and ActiveNet account. The route and documents depend on whether you qualify through a listed benefit, an agency referral or the low-income application.","steps":["Open the City's page and choose the application route matching your situation","Complete the Leisure Access application and gather the documents listed for that route","Submit it at a Park Board community centre or by the stated mail process","After approval, have the Leisure Access membership added to the OneCard and ActiveNet account","For a child 16 or younger, complete the parent or guardian photo-consent form" ],"documents":["Proof of a qualifying benefit or current Proof of Income Statement, depending on route","Proof of a City of Vancouver address dated within 90 days","Government-issued identification","OneCard photo consent for children 16 and younger","2025 Canada Child Benefit notice (Child Disability Benefit route)","2025 Proof of Income Statement verifying receipt of the Disability Tax Credit (not a Notice of Assessment)","Original Third Party Referral form completed by the referring agency within 90 days, signed and dated by you (agency referral routes)","Family members' 2025 tax year Proof of Income Statement (EI route)","Service Canada letter showing your Employment Insurance start and finish date and benefit rate (EI route)" ],"tips":["A Notice of Assessment is not the same as the CRA Proof of Income Statement asked for on the low-income route","UBC and University Endowment Lands addresses are outside the City of Vancouver","Bring the pass and photo identification when a partner venue asks for both" ],"time":"Ask the Leisure Access office when submitting"},"amountTiers":{"caption":"Maximum net family income by route (EI route: projected family income)","headers":["Family size","Disability Tax Credit route","Low-income self-referral and EI routes" ],"rows":[["1 person","$53,166","$43,028" ],["2 people","$70,972","$60,834" ],["3 people","$84,645","$74,507" ],["4 people","$96,171","$86,033" ],["5 people","$106,325","$96,187" ],["6 people","$115,506","$105,368" ],["7 people","$123,948","$113,810" ],["Each additional person","Not stated on the page","Add $8,450" ] ]}},{"id":"surrey-leisure-access","name":"Leisure Access Program (LAP)","level":"Surrey","category":"Recreation","amount":"Free 1-year pass for ages 0-18 and 60+, or 75% off for adults 19-59, plus 75% off most registered courses","summary":"Surrey's recreation subsidy. Children, youth and seniors get a free year-long pass to every City recreation facility. Adults get three quarters off.","requires":["bc","surrey","surreyLeisureRoute" ],"eligibility":{"mode":"any","items":["Income tax documents: your family's combined net income (line 23600) is less than the maximum for your family size in the table, and the City's other income-line limits are met","Client of the Ministry of Social Development","Disability Tax Credit applicants must meet the City's family-income and other income-line limits.","Senior receiving the Guaranteed Income Supplement","Child or youth in qualifying legal care, or a young adult supported by the Ministry's SAJE program.","Refugee, with a referral application completed through an approved settlement services agency" ],"note":"You must be a Surrey resident. The City says you may qualify if one of these situations applies. For the Disability Tax Credit route, your family's combined net income, after subtracting the Disability Tax Credit amounts the City's page lists, must be less than the maximum for your family size, and the City's other income-line limits must be met. The legal-care route covers a child or youth aged 0-18 in the legal care of the Ministry of Children and Family Development, Métis Family Services or Vancouver Aboriginal Child and Family Services Society, or a young adult aged 19-25 supported by the Ministry's SAJE program; enrolment covers the child or youth and one legal guardian."},"requiresNote":"You may qualify if you are a Surrey resident and one of the City's routes applies. See the route list and its income, legal-care and referral conditions below.","note":"Enrolment is valid for one year. If you apply with income tax documents, your family's combined net income must be less than the maximum for your family size in the table. This is line 23600 of your Notice of Assessment or Proof of Income Statement. A family is one or two married or common-law adults and their legal dependents aged 18 and under. In the year you are enrolled, course discounts have limits. For ages 0-18, the limit is up to $500 plus $500 at Semiahmoo Arts Society. For adults 19-59 and seniors 60+, it is up to $250 plus $250. Applicable day camps for children (0 to 12) and youth (13 to 18) get 75% off with no discount limits. A few specialty programs are not included.","applyText":"Apply for the Leisure Access Program","applyUrl":"https://www.surrey.ca/parks-recreation/activities-registration/admissions-passes/leisure-access-program","source":"https://www.surrey.ca/parks-recreation/activities-registration/admissions-passes/leisure-access-program","detail":{"about":"Surrey accepts several qualifying routes. Income-tax and Disability Tax Credit applicants must meet the family-income test and the line 12100, 12600, 20800 and 25400 limits on the City's page.","steps":["Review the City's qualifying routes and select the one that applies","Complete the Leisure Access Program application and copy the documents required for that route","Submit online and wait for staff to schedule an appointment, or submit in person at a listed Surrey facility","After approval, use the pass through the MySurrey account or call registration staff" ],"documents":["Application form","Government-issued photo identification for one adult","Proof of Income Statement for each adult in the family, when applying with income tax documents","Program confirmation, DTC information or referral documents for another qualifying route","Canada Child Benefit Notice, Goods and Services Tax Credit Notice or Canada Groceries and Essentials Benefit Notice (income-tax and DTC routes; MSD and GIS routes only if children aged 0-18 or a spouse in the family are not listed on the letter)" ],"tips":["Translation and interpretation support are available free","As of September 1, 2026, income tax documents must be for the 2025 or 2026 tax year.","Ask whether a specialty program is excluded before you register" ],"time":"Online applicants are contacted for appointments on a first-come, first-served basis","phone":"604-502-6325"},"amountTiers":{"caption":"Family net income maximum for the Leisure Access Program — only for patrons applying with income tax documents","headers":["Family size","Family net income" ],"rows":[["1","$26,355" ],["2","$32,075" ],["3","$39,940" ],["4","$49,829" ],["5","$56,742" ],["6","$62,928" ],["7","$69,112" ],["8 and more","$6,186 for each additional person" ] ]}},{"id":"burnaby-fair-play","name":"FAIR Play Program","level":"Burnaby","category":"Recreation","amount":"$250 credit per youth, adult or senior, $500 per child, plus an annual Be Active Pass for each family member","summary":"Burnaby gives every eligible family member a recreation credit and a free annual Be Active Pass. The pass is in addition to the credit. It is not paid for out of the credit.","requires":["bc","burnaby","burnabyFairPlayRoute" ],"eligibility":{"mode":"any","items":["You receive federal or provincial government income assistance.","Your combined family income is within the FAIR Play income scale.","You apply for a child with a disability and currently receive the Child Disability Benefit. This application is only for your child.","You are a government or privately sponsored refugee.","You have current Canadian Ukraine Emergency Travel Authorization (CUAET).","You have an approved agency referral; no household application is required." ],"note":"You must also live in Burnaby."},"requiresNote":"You must live in Burnaby and meet one of these: you receive federal or provincial government income assistance; you meet the income criteria; you apply on behalf of a child with a disability and currently receive the Child Disability Benefit (this application is only for your child); you are a government or privately sponsored refugee or have current Canadian Ukraine Emergency Travel Authorization (CUAET); or you have an approved agency referral.","note":"You can apply once a year, and the credit is valid for a year. Unused credit is removed when it expires and has no cash value. The FAIR Play Program replaced the older Recreation Credit Program on March 1, 2024.","applyText":"Apply for FAIR Play","applyUrl":"https://www.burnaby.ca/services-and-payments/seniors-and-family-support/fair-play-program","source":"https://www.burnaby.ca/services-and-payments/seniors-and-family-support/fair-play-program","detail":{"about":"Each approved family member receives both a Be Active Pass and recreation credit. The City accepts income-assistance, income, child-disability, refugee or current CUAET, and approved-agency-referral routes.","steps":["For a household application, download and print the FAIR Play application or pick up a copy at a Burnaby recreation or culture facility","Choose the qualifying route and gather the supporting documents listed on the form","For a household application, complete the household information and submit using the City's instructions","For an approved agency referral, no household application is required","Instead, your approved referral agency worker can complete and submit a FAIR Play Agency Referral Form directly to the FAIR Play Office on your behalf","After approval, use the Be Active Pass and apply the recreation credit during online or staff-assisted registration" ],"documents":["Completed FAIR Play application for the household application route","FAIR Play Agency Referral Form submitted by your approved referral agency worker instead of a household application for the agency-referral route","Proof of Burnaby residence","Income, assistance, child-disability, refugee, current CUAET or agency-referral documentation for the chosen route" ],"tips":["Burnaby Community Services can help with translation, documents and the application","Credit expires after one year and cannot be paid out as cash","During online registration, check that the recreation-credit box is applied to the balance" ],"time":"Apply once per year; ask the City for current processing time"}},{"id":"richmond-rec-fee-subsidy","name":"Recreation Fee Subsidy Program (RFSP)","level":"Richmond","category":"Recreation","amount":"Unlimited free admission to many drop-in programs and services plus 90% off most registered programs, up to $300 a year for children and youth or $100 a year for adults and seniors","summary":"Richmond's recreation subsidy for residents in financial hardship — free admission to many drop-in programs and services with no cap on visits, and nine tenths off most registered programs.","requires":["bc","richmondbc","richmondFinancialHardship" ],"eligibility":{"mode":"all","items":["You live in Richmond.","You are in financial hardship, shown either by receiving one of the government assistance programs the City lists (for example Disability Assistance or the Canada Disability Benefit), or, if you do not receive them, by meeting the City's family net income and other financial limits." ]},"requiresNote":"You must live in Richmond and be in financial hardship, shown either by receiving one of the government assistance programs the City lists (for example Disability Assistance or the Canada Disability Benefit), or, if you do not receive them, by meeting the City's family net income and other financial limits. The City defines hardship as difficulty paying for basic living costs such as food, clothing and housing, without savings or other financial resources.","note":"The 90% discount on most registered programs is capped at $300 per year in subsidy for children and youth 18 and under, and $100 per year for adults and seniors 19 and over. Free admission to eligible drop-in programs is not capped.","applyText":"Apply for the Recreation Fee Subsidy","applyUrl":"https://www.richmond.ca/culture/social/accessibility/subsidies/recreation-fee.htm","source":"https://www.richmond.ca/culture/social/accessibility/subsidies/recreation-fee.htm","detail":{"about":"Participants get unlimited free admission to many drop-in services and a 90% discount on most registered City and participating community programs, subject to the annual registered-program subsidy cap.","steps":["Download the application for the current program year and review the two financial-hardship qualification methods","Complete one application per family or couple and attach the documents for the selected method","Submit by email, mail or at a Richmond recreation facility, Cultural Centre or City Hall","If help is needed, book an in-person support appointment at City Hall","Keep the approval letter and use the subsidy when registering for eligible activities" ],"documents":["Completed current-year application","Proof of Richmond residence","Government-assistance confirmation or current income and financial-hardship documents required by the form" ],"tips":["Use the application for the correct program year","Help with the application in person is by appointment, not drop-in","Before you register, ask whether a program counts toward the annual discounted-program cap" ],"time":"Current 2026–2027 applications cover September 1, 2026 to August 31, 2027","phone":"604-247-4909"}},{"id":"victoria-life","name":"L.I.F.E. Program (Leisure Involvement For Everyone)","level":"Victoria","category":"Recreation","amount":"Two years of unlimited free drop-ins at Victoria Recreation Centre (opening planned early 2027) and public skating at Save-On-Foods Memorial Arena, 52 free regional drop-ins a year, plus a program credit of $80 to $120 depending on age","summary":"Victoria's low-income recreation membership. It runs two years from your approval date, not by calendar year, and covers drop-ins at Victoria Recreation Centre (opening planned early 2027), public skating and regional partner drop-ins.","requires":["bc","victoria","lowIncome" ],"eligibility":{"mode":"all","items":["You are a City of Victoria resident with a fixed address, have lived there for the previous 30 days, and can demonstrate proof of residency.","Your household income is at or below the Statistics Canada low-income threshold for your household size (see the table below). All family members and dependants at the same address are included." ]},"amountTiers":{"caption":"Income eligibility — Statistics Canada low-income threshold by household size","headers":["Household size","Household income at or below" ],"rows":[["1 person","$29,640" ],["2","$38,493" ],["3","$47,145" ],["4","$55,076" ],["5","$62,464" ],["6","$70,451" ],["7","$78,436" ] ]},"requiresNote":"You must be a City of Victoria resident with a fixed address, have lived there for the previous 30 days, and be able to demonstrate proof of residency. Household income must be at or below the Statistics Canada low-income threshold: $29,640 for 1 person, $38,493 for 2, $47,145 for 3, $55,076 for 4, $62,464 for 5, $70,451 for 6 and $78,436 for 7. All family members and dependants at the same address are included.","note":"Membership is valid for two years. The two years start on your approval date, so you do not have to apply in January. The registered-programming credit is for the whole two-year term, not for each year.","applyText":"Apply for the L.I.F.E. Program","applyUrl":"https://www.victoria.ca/parks-recreation/recreation/accessibility-inclusion/life-program","source":"https://www.victoria.ca/parks-recreation/recreation/accessibility-inclusion/life-program","detail":{"about":"The two-year membership combines unlimited drop-ins at Victoria Recreation Centre (opening planned early 2027) and public skating, a regional 52-visit benefit and a one-time registered-program credit. If you cannot provide the standard documents you may still be eligible to apply using an adjudicator. The City only accepts adjudicator applications when all required information is provided and audits all adjudicator forms.","aboutList":{"lead":"The two-year membership includes:","items":["Unlimited drop-ins at Victoria Recreation Centre (opening planned early 2027) and public skating.","A regional 52-visit benefit and a one-time registered-program credit.","If you cannot provide the standard documents you may still be eligible to apply using an adjudicator.","The City only accepts adjudicator applications when all required information is provided and audits all adjudicator forms." ]},"steps":["Complete one L.I.F.E. application for family members living at the same address","Gather current proof of City of Victoria residence and income documents for household adults","If you cannot provide the documents, you may be able to use an adjudicator: a community professional familiar with your financial and residential situation completes the adjudicator form","Submit through the method on the current City form","After approval, obtain the regional visit sticker each calendar year and use the program credit before the two-year term ends" ],"documents":["Completed L.I.F.E. application","Utility bill, phone bill or rental agreement from the last three months","Most recent CRA Notice of Assessment for household members aged 19 and older, or completed adjudicator verification" ],"tips":["The $80 or $120 program credit is for the whole two-year term, not for each year","You must renew the regional 52-visit sticker each calendar year","Before you choose the discounted regional annual pass, ask staff which benefit option is better" ],"time":"Membership lasts two years from approval"}},{"id":"saanich-life","name":"L.I.F.E. Program (Leisure Involvement For Everyone)","level":"Saanich","category":"Recreation","amount":"Choose one of two options for two years. Option 1: free drop-ins at Saanich facilities, 52 regional drop-in visits a year, and a one-time grant of $80 to $120 (by age) toward registered programs at Saanich centres. Option 2: 50% off an annual Regional Recreation Pass.","summary":"Saanich's version of the regional L.I.F.E. program. Approval lasts two years. You pick one of two benefit options.","requires":["bc","saanich","lowIncome" ],"eligibility":{"mode":"all","items":["You have proof of Saanich residency — a utility or phone bill dated within the last three months, a current signed rental agreement, or a current driver's licence or BC identification card. One proof covers the whole family.","Most households qualify with a Canada Revenue Agency Proof of Income Statement for every household member 19 and over, even those who will not use the program. Thresholds are based on their combined gross income." ],"note":"Other routes exist: newcomers can apply with landing papers showing a landing date within one year of applying; if your statement no longer reflects your current income (for example after an illness or job loss) you can use a completed adjudicator form; a youth in a local school without parental or guardian support can use the Youth Application form; if none fit, contact the financial-assistance office."},"requiresNote":"You need proof of Saanich residency — a utility or phone bill dated within the last three months, a current signed rental agreement, or a current driver's licence or BC identification card. One proof covers the whole family. Most households need a Canada Revenue Agency Proof of Income Statement for every household member 19 and over, even those who will not use the program; thresholds are based on their combined gross income. Other routes exist: newcomers with landing papers showing a landing date within one year of applying; a completed adjudicator form if the statement no longer reflects current income (for example after illness or job loss); a Youth Application form for a youth in a local school without parental or guardian support. Contact the financial-assistance office if none fit.","note":"Approval is valid for two years from the date of approval. The grant amounts below are for the whole two-year term. For adults and preschool-age children, the grant is all that is available for the two years. For children (5–12) and youth (13–18), there may be some extra funds after the first grant is used. This has strict eligibility guidelines and no guarantee. Saanich only accepts CRA Proof of Income Statements, not Notices of Assessment. Allow at least 5 days between approval and registering, because grants take up to 5 days to appear on your account.","applyText":"Apply online for L.I.F.E.","applyUrl":"https://www.saanich.ca/EN/main/parks-recreation-community/community-services/financial-assistance/financial-assistance.html","source":"https://www.saanich.ca/EN/main/parks-recreation-community/community-services/financial-assistance/financial-assistance.html","detail":{"about":"Saanich's two-year L.I.F.E. approval lets you choose Option 1 (free drop-ins at Saanich facilities, regional drop-in visits, and an age-based one-time grant for Saanich registered programs) or Option 2 (50% off an annual Regional Recreation Pass). Current applications can be completed through the City's secure online form.","aboutList":{"lead":"Saanich's two-year L.I.F.E. approval lets you choose one of two options.","items":["Option 1 includes free drop-ins at Saanich facilities and regional drop-in visits.","Option 1 also includes an age-based one-time grant for registered programs at Saanich centres.","Option 2 is 50% off an annual Regional Recreation Pass.","Current applications can be completed through the City's secure online form." ]},"steps":["Gather one current proof of Saanich residence for the household","Get the current CRA Proof of Income Statement for every household member age 19 or older (or, if another route applies to you, the form for that route)","Complete the secure online L.I.F.E. application and upload the documents","If income shown is under $1,000 or the household has a special situation, contact the financial-assistance office directly","Allow time after approval for the program grant to appear before registering" ],"documents":["Utility or phone bill from the last three months, signed rental agreement, driver's licence or BC identification","Current CRA Proof of Income Statement for every household member 19 or older (most households), or the adjudicator form / Youth Application form where those routes apply","Recent landing papers instead of income statements for eligible newcomers within one year of arrival" ],"tips":["Saanich accepts CRA Proof of Income Statements, not Notices of Assessment","The first grant is for the whole two-year approval. Children and youth may be able to ask about extra funds, but they are not guaranteed","Allow at least five days after approval before you try to spend the grant" ],"time":"Grant setup can take up to five days after approval"}},{"id":"kelowna-recreation-assistance","name":"Financial Assistance for Recreation (KFAP)","level":"Kelowna","category":"Recreation","amount":"A credit toward a Parkinson Recreation Centre pass or City programs","summary":"Kelowna's recreation subsidy for residents on a low income. It gives a credit you can spend on a facility pass or on programs.","requires":["bc","kelowna","lowIncome","citizenPR","notPostSecondaryStudent" ],"eligibility":{"mode":"all","items":["You are a Canadian citizen or permanent resident currently residing in Kelowna as a full-time resident.","You meet the family net income threshold based on the after-tax Low Income Cut-off (see the table below). You must also meet income verification requirements and have all the necessary documentation. People receiving government financial assistance are eligible to apply, as are people who do not receive it but are experiencing financial hardship and meet the guidelines." ],"note":"Post-secondary students are not eligible, though they can ask for the discounted student rate on passes instead. Also not eligible: temporary residents and visitors, including anyone on a study or work permit; immigrants classified as business class, investor or entrepreneur; and anyone banned from City recreation facilities, including Parkinson Recreation Centre and the Kelowna-area YMCAs. Recreation Services may exercise discretion when determining eligibility for Financial Assistance for individuals with previous suspensions or bans."},"amountTiers":{"caption":"City of Kelowna — Low Income Cut-Offs (LICO) 2025 (family net income after tax)","headers":["Family size","Family net income" ],"rows":[["1","$26,926" ],["2","$33,519" ],["3","$41,208" ],["4","$50,032" ],["5","$56,744" ],["6","$64,000" ],["7","$71,254" ] ]},"requiresNote":"You must be a Canadian citizen or permanent resident currently residing in Kelowna as a full-time resident, and meet the family net income threshold based on the after-tax Low Income Cut-off published by Statistics Canada. The City 2025 LICO table lists $26,926 for a family of 1, $33,519 for 2, $41,208 for 3, $50,032 for 4, $56,744 for 5, $64,000 for 6 and $71,254 for 7. You must also meet income verification requirements and have all the necessary documentation. People receiving government financial assistance are eligible to apply, as are people who do not receive it but are experiencing financial hardship and meet the guidelines. Post-secondary students are not eligible, though they can ask for the discounted student rate on passes instead. Also not eligible: temporary residents and visitors, including anyone on a study or work permit; immigrants classified as business class, investor or entrepreneur; and anyone banned from City recreation facilities, including Parkinson Recreation Centre and the Kelowna-area YMCAs. Recreation Services may exercise discretion when determining eligibility for Financial Assistance for individuals with previous suspensions or bans.","note":"To apply, email the Access to Recreation Department. The assessment may take up to two weeks from the date you submit, if all required information is received. The income assessment counts income from all sources. This includes disability benefits and workers' compensation, as well as employment, investments, pensions, child and foster child support, rental income and funds held in trust.","applyText":"Email Access to Recreation to apply","applyUrl":"https://www.kelowna.ca/parks-recreation/recreation-sport/recreation-programs-registration/financial-assistance-recreation","source":"https://www.kelowna.ca/parks-recreation/recreation-sport/recreation-programs-registration/financial-assistance-recreation","detail":{"about":"Kelowna assesses combined household income from all sources and places an approved credit on the recreation account for passes or City programs.","steps":["Email the Access to Recreation Department to request the current application process","Gather proof of a Kelowna address from the last three months","Get a CRA Income Statement (Option C print, not Notice of Assessment) for each household member who contributes income or expenses","Submit the completed application and all supporting documents","Wait for approval before buying a pass or program; approved credit can then be used during registration" ],"documents":["Recent utility, cable or internet bill, rental agreement, or government document showing a Kelowna address","CRA Income Statement for contributing household members","Government-assistance confirmation when using that qualifying route","Citizenship or permanent-resident information requested by the form" ],"tips":["Past purchases are not covered, so wait for approval","All income sources count, including disability benefits and income from outside Canada","A clerk at Parkinson Recreation Centre can check whether processing is complete","You must re-apply every year. You can resubmit up to one month before your current term ends.","If you are a post-secondary student, you cannot use this program. You can still get the discounted student rate on a pass. Show a valid student ID and proof of full-time enrolment." ],"time":"The assessment may take up to two weeks from the date of submission, provided all required information is received."}},{"id":"coquitlam-far","name":"Financial Assistance for Recreation (FAR)","level":"Coquitlam","category":"Recreation","amount":"50 drop-in passes plus a $225 credit for every eligible family member","summary":"Coquitlam gives each eligible family member their own 50 drop-in passes and their own $225 credit. The credit is for City admissions, passes and programs.","requires":["bc","coquitlam","coquitlamStatus","coquitlamIncome" ],"eligibility":{"mode":"all","items":["You are a Coquitlam resident.","You meet the 2025 Low Income Cut-off for your household size (see the table below)." ],"note":"A family here means one or two married or common-law adults and their legal dependents aged 18 and younger."},"amountTiers":{"caption":"Income eligibility — 2025 Low Income Cut-off by household size","headers":["Household size","Income at or below" ],"rows":[["1 person","$27,478" ],["2","$34,206" ],["3","$42,053" ],["4","$51,058" ],["5","$57,908" ],["6","$65,313" ],["7 or more","$72,715" ] ]},"requiresNote":"You must be a Coquitlam resident and meet the 2025 Low Income Cut-off for your household size: $27,478 for 1 person, $34,206 for 2, $42,053 for 3, $51,058 for 4, $57,908 for 5, $65,313 for 6 and $72,715 for 7 or more. A family here means one or two married or common-law adults and their legal dependents aged 18 and younger.","note":"You can verify income in four ways. First: a CRA Income Statement (the Option C print, not a Notice of Assessment) for each family member who contributes to household income. Or: the main applicant's proof of government assistance. Or: the main applicant's proof of receiving a red Compass Card. Or: a completed adjudicator or agency signature section on the application. You also need proof of Coquitlam residency dated within two months. The red Compass Card route is worth noting. It is the same card BC transit concession holders already carry.","applyText":"Apply for Financial Assistance for Recreation","applyUrl":"https://www.coquitlam.ca/499/Financial-Assistance-for-Recreation","source":"https://www.coquitlam.ca/499/Financial-Assistance-for-Recreation","detail":{"about":"Each eligible family member receives 50 drop-in passes and a $225 credit. Income verification can use a CRA statement, government assistance, a red Compass Card or an approved adjudicator or agency signature.","steps":["Complete the online FAR form or download the paper application","Attach proof of Coquitlam residence dated within two months","Choose one accepted income-verification route and attach that evidence","Submit online, by email, mail or in a sealed envelope at Glen Pine Pavilion","After approval, use each family member's passes and credit in the recreation registration system" ],"documents":["Completed FAR application","Recent Coquitlam bill or government-issued identification","CRA Income Statement, assistance proof, red Compass Card proof, or adjudicator or agency section" ],"tips":["You may redact irrelevant licence, SIN and bank-account numbers. Leave your name, address, date and income visible","Use an Option C Income Statement, not a Notice of Assessment","Each eligible family member gets a separate set of passes and credit" ],"time":"Ask Community Access and Support after submission","phone":"604-927-6076"}},{"id":"kamloops-arch","name":"ARCH (Affordable Recreation for Community Health)","level":"Kamloops","category":"Recreation","amount":"Up to $400 in recreation credits per year","summary":"Kamloops' recreation subsidy: up to $400 in recreation credits a year. The same form also asks to be considered for KamPASS, the City's affordable transit pass. KamPASS is a separate program with its own exclusions.","requires":["bc","kamloops","archIncomeOrAssistance" ],"note":"ARCH is an annual program and requires a new application each year. One form covers both programs and applicants are automatically considered for both, but ARCH and KamPASS are two separate programs: being approved for ARCH does not establish that you are eligible for KamPASS. Check the KamPASS exclusions before counting on a transit pass.","applyText":"Apply for ARCH","applyUrl":"https://www.kamloops.ca/recreation-culture/programs-activities/accessible-recreation/arch-program","source":"https://www.kamloops.ca/recreation-culture/programs-activities/accessible-recreation/arch-program","detail":{"about":"ARCH provides up to $400 in recreation credits for permanent Kamloops residents. You qualify by meeting any one of three routes: you receive Income Assistance from the Ministry of Social Development and Poverty Reduction. Your annual income is below the Statistics Canada Low Income Guidelines listed on the application form. Or you receive a Canadian pension or long-term disability payment below those guidelines. The annual application also asks to be considered for KamPASS, the City's reduced-cost adult monthly transit pass. The City states that ARCH and KamPASS are two separate programs that share one application process, that applicants are automatically considered for both, and that qualified participants can use both programs or just one. Approval for ARCH does not establish KamPASS eligibility. A participating screening or referral agency reviews the application; City recreation facilities do not accept the application itself.","aboutList":{"lead":"ARCH provides up to $400 in recreation credits for permanent Kamloops residents.","items":["You qualify by meeting any one of three routes: you receive Income Assistance from the Ministry of Social Development and Poverty Reduction. Your annual income is below the Statistics Canada Low Income Guidelines listed on the application form. Or you receive a Canadian pension or long-term disability payment below those guidelines.","The annual application also asks to be considered for KamPASS, the City's reduced-cost adult monthly transit pass.","The City states that ARCH and KamPASS are two separate programs that share one application process, that applicants are automatically considered for both, and that qualified participants can use both programs or just one.","Approval for ARCH does not establish KamPASS eligibility.","A participating screening or referral agency reviews the application; City recreation facilities do not accept the application itself." ]},"steps":["Download the current ARCH–KamPASS application or pick up a paper copy","Gather photo identification, a second piece of identification, proof of a Kamloops address and proof of income for each adult","Take the complete application to a participating ARCH public screening agency or, if you are a client, a listed referral agency","If approved, take the approval letter and photo identification to a listed City facility to activate ARCH credit","If also approved for KamPASS, purchase it at Kamloops Museum and Archives" ],"documents":["Photo identification and a second piece of identification","Current utility bill or other accepted proof of Kamloops residence","Ministry assistance confirmation, each adult's latest Notice of Assessment, or accepted disability or pension income evidence" ],"tips":["Applications are not accepted at City recreation facilities","One form requests both, but ARCH and KamPASS have separate eligibility. Being approved for ARCH does not mean you qualify for KamPASS","KamPASS is not available to people who receive disability assistance from the Ministry of Social Development and Poverty Reduction under the Employment and Assistance for Persons with Disabilities Act. So many people who qualify for ARCH are excluded from KamPASS","KamPASS also excludes these people: people aged 60 and over who are eligible for the Provincial BC Bus Pass for Seniors and Others; people aged 18 or under eligible for the BC Transit Family Travel Program or School District No. 73 Transportation Assistance; post-secondary students enrolled in U-PASS; CNIB card holders; and anyone whose income is above the Statistics Canada Low Income Cut-Offs or who cannot provide income verification","Apply again each year and use the application form for the current program year" ],"time":"Annual approval; ask the screening agency for current review time","phone":"250-828-3582"}},{"id":"abbotsford-prc-subsidy","name":"PRC Subsidy Program (Abbotsford)","level":"Abbotsford","category":"Recreation","amount":"Recreation pass plus 25% off listed programs","summary":"A recreation pass for Abbotsford recreation centres and 25% off some registered programs. It is for full-time Abbotsford residents whose family net income is under the City's low-income cutoff for their household size.","note":"The program runs May 1 to April 30 and you re-apply each year. Group swim and skate lessons qualify, but private lessons do not. Some camps and other programs qualify, and the list is updated each year.","requires":["bc","abbotsford","abbotsfordPrcIncome" ],"eligibility":{"mode":"all","items":["You are a full-time Abbotsford resident","Your family net income after tax is within the City's low-income cutoff chart" ],"note":"Income proof is usually your 2025 Notice of Assessment (line 236); other proofs are listed."},"applyText":"Apply for the PRC Subsidy","applyUrl":"https://www.abbotsford.ca/node/10757","source":"https://www.abbotsford.ca/node/10757","detail":{"aboutList":{"lead":"The subsidy gives lower-income Abbotsford households a recreation pass and discounts on some programs.","items":["A recreation pass to City of Abbotsford recreation centres.","25% off group swim and skate lessons; private lessons are excluded.","25% off some neighbourhood and summer camps for ages 3 to 12, and other specified programs.","Net income limit: $22,361 for 1 person (from $5,000), $27,214 for 2, $33,888 for 3.","Net income limit: $42,278 for 4, $48,142 for 5, $53,390 for 6, $58,639 for 7 or more." ]},"steps":["Compare your family's after-tax net income with the City's cutoff chart","Fill in the application form with details for everyone in your household","Take the form and your documents to City Hall, the Abbotsford Recreation Centre or the Matsqui Recreation Centre","Wait for an email or letter telling you if you were approved","If approved, go to the Abbotsford or Matsqui Recreation Centre to get your pass","Re-apply each year" ],"documents":["Proof of Abbotsford residency dated in the last 3 months, such as a utility bill, a letter from your bank or a rental agreement","Valid government photo ID, such as a driver's licence, BC ID or passport","One of these as proof of income: a 2025 Notice of Assessment for every adult 19 or older, an Independent Youth Letter, or a letter from a Registered Social Worker","Canada Child Benefit Notice listing all dependent children, if children are on the application" ],"tips":["A Tax Notice Summary is not accepted. You need the Notice of Assessment.","The City does not accept faxed or emailed applications.","New immigrants must visit Archway Community Services for an application form.","If you are denied, you get a letter in the mail with the reasons." ],"time":"Up to 2 weeks to process","phone":"604-859-3134"}},{"id":"abbotsford-specialized-access","name":"Specialized Access Program (Abbotsford)","level":"Abbotsford","category":"Recreation","amount":"50% off recreation centre drop-in admissions and passes","summary":"Half-price drop-in admissions and passes at Abbotsford recreation centres. It is for full-time Abbotsford residents whose permanent disability a physician confirms. Support workers who are needed get in free.","note":"There is no income test on the page. A physician completes a section of the form, so no medical copies are needed. The page does not give a renewal period.","requires":["bc","abbotsford","physicianConfirmedDisability" ],"eligibility":{"mode":"all","items":["You are a full-time Abbotsford resident","You have a permanent disability confirmed by a physician" ]},"applyText":"Apply for Specialized Access","applyUrl":"https://www.abbotsford.ca/node/10757","source":"https://www.abbotsford.ca/node/10757","detail":{"aboutList":{"lead":"This program lowers recreation centre costs for Abbotsford residents with permanent disabilities.","items":["50% off recreation centre drop-in admissions.","50% off recreation centre passes.","Support workers who are required to assist you are admitted at no charge." ]},"steps":["Download and complete the application form, and review the FAQ","Ask a physician to complete the disability section of the form","Take the form and your documents to City Hall, the Abbotsford Recreation Centre or the Matsqui Recreation Centre","Wait for an email or letter telling you if you were approved","Go to the Abbotsford or Matsqui Recreation Centre to get your Specialized Access Card" ],"documents":["Proof of permanent disability confirmed by a physician, on the application form only; no copies required","Proof of Abbotsford residency dated in the last 3 months, such as a utility bill, a letter from your bank or a rental agreement","Valid government photo ID of the applicant, or of the legal guardian if the applicant is a minor" ],"tips":["The City does not accept faxed or emailed applications.","If you are denied, you get a letter in the mail with the reasons." ],"phone":"604-859-3134"}},{"id":"maple-ridge-access-pass-financial","name":"Access Pass, Financial (Maple Ridge)","level":"Maple Ridge","category":"Recreation","amount":"75% off admissions, 90% under $18,000; 50% off programs up to $300","summary":"A discount on Maple Ridge recreation for residents with a low household income. You get 75% off admissions and 50% off registered programs, up to $300 of spending. Income under $18,000 gets 90% off drop-in and 10- or 20-pass admissions.","note":"The pass lasts one year from approval and you re-apply each year. The 90% rate excludes post-secondary students.","requires":["bc","mapleRidge","mapleRidgeIncome" ],"eligibility":{"mode":"all","items":["You live in Maple Ridge (ask the City how this applies if you hold a study or visitor visa)","The main applicant is 19 or older" ],"note":"Before-tax household income at or below the Low Income Cut-off (500,000+ community size), or third-party verification."},"applyText":"Apply for the Access Pass","applyUrl":"https://mapleridge.ca/1465/Financial-Access","source":"https://mapleridge.ca/1465/Financial-Access","detail":{"aboutList":{"lead":"The Access Pass lowers admission and program costs for Maple Ridge residents with a low household income.","items":["75% off drop-in, 10-pass, 20-pass, 1-month and 3-month admissions.","90% off drop-in, 10-pass and 20-pass admissions if income is below $18,000, excluding post-secondary students.","50% off registered program fees, up to $300 of spending.","The pass is valid for one year from the date of approval." ]},"steps":["Choose how to apply: online, on paper at the Maple Ridge Leisure Centre, or through a third party","Fill in the Financial application form","Upload or hand in your documents, or have a third party complete the adjudicator section","Wait for an email or phone call about your application","Pick up your membership card at the Maple Ridge Leisure Centre or Albion Community Centre","Re-apply each year" ],"documents":["An address-related bill from the last 3 months. PO Box addresses are not accepted","A Notice of Assessment for each person contributing to household income, or government assistance documents such as GIS, SAFER, EI or income assistance","Not needed if a third party verifies you: proof of address and income" ],"tips":["Not discounted, among others: private swimming lessons, high performance training camps, contracted or partner programs over $299.99, licensed afterschool care and employment certification.","Rename your uploaded files with your last name.","A third party can be a social worker, caseworker, counsellor, school principal, community agency or medical provider.","Online registration applies your discount automatically. Email Registration@MapleRidge.ca for your first sign-in link.","Applications needing extra screening can take up to 14 days." ],"time":"Up to 10 business days","phone":"604-467-7422"}},{"id":"maple-ridge-access-pass-disability","name":"Access Pass, Disability (Maple Ridge)","level":"Maple Ridge","category":"Recreation","amount":"50% off admissions; 25% off programs up to $150 a year","summary":"A discount on City of Maple Ridge recreation for residents with a diagnosed temporary or permanent disability. You get 50% off admissions and 25% off program fees, up to $150 a year. It is for the person with the disability, not the family.","note":"The page lists no income test for this pass. The pass lasts one year from approval and you re-apply each year.","requires":["bc","mapleRidge","mapleRidgeDisabilityProof" ],"eligibility":{"mode":"all","items":["You live in Maple Ridge (ask the City how this applies if you hold a study or visitor visa)","You have a diagnosed temporary or permanent disability, with documents or third-party verification" ],"note":"The pass is for the person with the disability only, one applicant per application."},"applyText":"Apply for the Disability Access Pass","applyUrl":"https://mapleridge.ca/1465/Financial-Access","source":"https://mapleridge.ca/1465/Financial-Access","detail":{"aboutList":{"lead":"The Disability Access Pass lowers admission and program costs for Maple Ridge residents with a diagnosed disability.","items":["50% off single, 10-pass, 20-pass, 1-month and 3-month admissions.","The pass is valid for one year from the date of approval.","A medical or para-medical provider can verify your disability on the form." ]},"steps":["Choose how to apply: online, on paper at the Maple Ridge Leisure Centre, or through a third party","Fill in the Individuals Diagnosed With Temporary or Permanent Disability form","Upload or hand in your documents, or have a third party complete the adjudicator section","Wait for an email or phone call about your application","Pick up your membership card at the Maple Ridge Leisure Centre or Albion Community Centre","Re-apply each year" ],"documents":["An address-related bill from the last 3 months. PO Box addresses are not accepted","Proof of disability, such as BC PWD designation, Disability Tax Credit approval, CPP Disability letter, Veterans Affairs or WorkSafeBC documents","Not needed if a third party verifies you: proof of address" ],"tips":["Not discounted, among others: private swimming lessons, high performance training camps, contracted or partner programs over $299.99, licensed afterschool care and employment certification.","The page's list of disability documents is cut off at the end, so ask staff if yours is not listed.","Online registration applies your discount automatically. Email Registration@MapleRidge.ca for your first sign-in link.","Applications needing extra screening can take up to 14 days." ],"time":"Up to 10 business days","phone":"604-467-7422"}},{"id":"nanaimo-leap","name":"LEAP, Leisure Economic Access Pass (Nanaimo)","level":"Nanaimo","category":"Recreation","amount":"50 free admissions a year, 50% off programs up to $40","summary":"LEAP gives 50 free drop-in admissions a year per person, half-price registered programs (limits apply) and free art gallery and museum entry. You qualify through one of six listed routes, such as assistance or low income.","note":"Post-secondary students are not eligible. The newcomer or refugee route works only once. After that you must re-apply with a Notice of Assessment.","requires":["bc","nanaimo","nanaimoLeapRoute","nanaimoNotStudent" ],"eligibility":{"mode":"all","items":["You live in Nanaimo, Lantzville or Electoral Area A, B or C of the Regional District of Nanaimo","You show proof of financial need by one of the six routes on the page" ],"note":"Post-secondary students are not eligible for LEAP."},"applyText":"Apply for LEAP","applyUrl":"https://nanaimo.ca/parks-recreation-culture/recreation-facilities-schedules/leap-(leisure-economic-access-pass)","source":"https://nanaimo.ca/parks-recreation-culture/recreation-facilities-schedules/leap-(leisure-economic-access-pass)","detail":{"aboutList":{"lead":"LEAP helps Nanaimo-area families in financial need use City recreation, art and museum services.","items":["50 free admissions per year per person for drop-in swimming, skating, weight rooms and drop-in gym.","Half price on programs (to a $40 maximum) for all family members, up to four times a year per person.","Free admission to the Nanaimo Art Gallery and Nanaimo Museum.","Income limit if you use a Notice of Assessment: $26,290 for 1 person, $32,727 for 2, $40,234 for 3.","Income limit: $48,851 for 4 people, $55,404 for 5, $62,488 for 6, $69,571 for 7." ]},"steps":["Pick the route that fits: income assistance or disability assistance, Seniors GIS, CLBC support, child or youth in care, newcomer or refugee, or a Notice of Assessment","Print the LEAP form, or apply online","Attach your proof of need and photo ID, online or at the front desk","Child or youth in care: ask your social worker or guardianship worker to email registration@nanaimo.ca" ],"documents":["Photo ID for the main contact and other adults, showing current address","Income or disability assistance: a recent proof such as an MHSD stub, notice of deposit or benefit statement from the last 3 months","Seniors GIS: a confirmation letter from Service Canada or a cheque stub","CLBC: proof of CLBC support","None of the above: last tax year's Notice of Assessment for each adult in the family" ],"tips":["Income assistance includes disability assistance from the Province of BC or the Government of Canada.","If you are a CLBC client, bring proof of your approved support.","Newcomers and refugees can contact the Central Vancouver Island Multicultural Society at info@cvims.org or 250-753-6911.","Canadian Tire Jumpstart is a separate application and is not run by the City." ]}},{"id":"new-westminster-financial-assistance","name":"Financial Assistance Program (New Westminster)","level":"New Westminster","category":"Recreation","amount":"50% off eligible programs and two pass types","summary":"Eligible New Westminster residents get a 50% discount on eligible registered programs, the Active 10 Visit pass and the Active 30 Day pass. You qualify by a social service agency referral or household income under $50,000.","note":"Each family member gets 1,000 credits. They expire on December 31 each year, and you can then re-apply. Credits are non-transferable and have no cash value. You can buy one pass at a time.","requires":["bc","newWestminster","newWestRoute" ],"eligibility":{"mode":"any","items":["A social service agency completes the Financial Assistance Referral Form for you","Your household income is below $50,000" ],"note":"Either route also needs proof of New Westminster residency."},"applyText":"Apply for Financial Assistance","applyUrl":"https://www.newwestcity.ca/parks-and-recreation/access-and-inclusion/sb_expander_articles/973.php","source":"https://www.newwestcity.ca/parks-and-recreation/access-and-inclusion/sb_expander_articles/973.php","detail":{"aboutList":{"lead":"The program reduces fees for New Westminster residents who show a referral or lower household income.","items":["Every family member receives 1,000 credits; they reduce fees by up to 50% on eligible purchases.","Credits work through staff or your online account, and expire December 31.","$2 drop-in admissions are open to everyone, but they get no extra discount." ]},"steps":["Choose a route: an agency referral, or proof that household income is below $50,000","Bring your documents and proof of residency to Recreation Facility customer service staff during office hours","Staff create accounts for you and eligible household family members","Use your credits through staff or your online account","After credits expire on December 31, apply again" ],"documents":["Proof of New Westminster residency","Agency route: the Financial Assistance Referral Form completed by a social service agency","Income route: a CRA tax assessment or a federal Child Benefit Notice, dated within the past 12 months" ],"tips":["Registered programs are not eligible if they involve a third-party operator, are already subsidized, are private or semi-private lessons, or involve transportation costs.","An agency can also email the referral letter, and staff will contact you.","Credits expire December 31; you can then re-apply." ]}},{"id":"prince-george-lap","name":"Leisure Access Program (Prince George)","level":"Prince George","category":"Recreation","amount":"52 free swims, then 75% off swim passes","summary":"The Leisure Access Program gives 52 free public swims. After that it gives 75% off swim passes and 75% off swimming programs, up to a $50 credit. It is for Prince George residents with limited income.","note":"The program covers a variety of aquatic activities. Referral agencies can submit applications for their clients.","requires":["bc","princeGeorge","princeGeorgeIncome" ],"eligibility":{"mode":"all","items":["You live in Prince George (the City says “permanent residents of Prince George”)","Your annual income is below the Statistics Canada Low Income Guidelines, or you get a BC Seniors Supplement below them" ],"note":"Income limits are on the page by household size, from 1 to 6 people."},"applyText":"Apply for the Leisure Access Program","applyUrl":"https://www.princegeorge.ca/node/5327","source":"https://www.princegeorge.ca/node/5327","detail":{"aboutList":{"lead":"The program lowers swimming costs for residents on a limited income.","items":["52 complimentary public swimming admissions.","75% off all swim passes once the 52 free admissions are used.","75% off swimming programs, such as lessons, up to a $50 credit.","Income under: $26,127 for 1 person, $32,525 for 2, $39,986 for 3.","Income under: $48,550 for 4 people, $55,064 for 5, $62,103 for 6." ]},"steps":["Fill in the LAP Participant Application form, online or on paper","Get a paper copy at the Canfor Leisure Pool or P.G. Aquatic Centre if you prefer","Include proof of yearly household income and photo ID","Or ask an approved referral agency to apply for you with the LAP Referral Agency Application" ],"documents":["Proof of yearly household income","Photo ID" ],"tips":["Applications are processed Monday to Friday, 9 a.m. to 4:30 p.m.","Processing can take up to 10 days, but it is typically a day or two on weekdays.","Agencies that are not yet approved can email leisureaccessprogram@princegeorge.ca to ask about becoming a referral agency." ],"time":"Up to 10 days; often 1 to 2 weekdays"}},{"id":"campbell-river-life","name":"L.I.F.E. Program (Campbell River)","level":"Campbell River","category":"Recreation","amount":"52 free drop-ins and 50% off three programs","summary":"The L.I.F.E. card gives Campbell River residents who face financial challenges 52 free drop-in admissions. It also gives 50% off fees for three City recreation programs.","note":"Some programs are excluded, including Summerside Express summer camps. Each family member can get a card. Cards last one calendar year.","requires":["bc","campbellRiver","campbellRiverLifeRoute" ],"eligibility":{"mode":"all","items":["You live in Campbell River","You meet the income requirements on the application form" ],"note":"The income limits are on the application form, not on the page."},"applyText":"See L.I.F.E. program details","applyUrl":"https://www.campbellriver.ca/parks-recreation-culture/recreation/affordable-recreation","source":"https://www.campbellriver.ca/parks-recreation-culture/recreation/affordable-recreation","detail":{"aboutList":{"lead":"The L.I.F.E. card lowers recreation costs for Campbell River residents with limited funds.","items":["52 free drop-in admissions, including Centennial Pool, the weight room and drop-in classes.","50% off fees for three City of Campbell River recreation programs.","Some exceptions apply to the discount, such as Summerside Express summer camps.","Every family member can have one LIFE card." ]},"steps":["Get the form at the Sportsplex or Community Centre, or print it from the page","Fill in the whole form","Hand it to office staff at the Sportsplex or Community Centre with your proof documents","Show your card whenever you want the reduced fee" ],"documents":["Proof of residency with your current address, such as a driver's licence or current utility bill","Proof of income, such as a Notice of Assessment, EI, disability or pension stubs" ],"tips":["Applications that are not filled in fully are not accepted.","A card is cancelled if the information on the form is false.","Cards are not transferable and have no cash value." ]}},{"id":"colwood-langford-life","name":"LIFE Program (West Shore Parks & Recreation)","level":"Colwood","category":"Recreation","amount":"Low-income access to recreation centres","summary":"LIFE helps people and families with low incomes use recreation services and programs at municipal recreation centres in Greater Victoria. It is run by West Shore Parks & Recreation.","note":"LIFE passes cannot be transferred or exchanged for cash or credit.","requires":["bc","colwoodArea","colwoodLangfordLifeRoute","noPostSecondaryStudents" ],"eligibility":{"mode":"all","items":["You live in Colwood, Langford, Highlands, Metchosin or View Royal","Your combined gross household income is at or below the Statistics Canada low income thresholds","You are not a full-time post-secondary student at Royal Roads, UVic or Camosun College" ],"note":"Newcomers within 5 years of immigrating may use travel documents instead of a Notice of Assessment in year one."},"applyText":"See LIFE program details","applyUrl":"https://www.wspr.ca/inclusion-support/financial-support","source":"https://www.wspr.ca/inclusion-support/financial-support","detail":{"aboutList":{"lead":"LIFE opens Greater Victoria recreation centres to West Shore households with low incomes.","items":["Works at all municipal recreation centres in Greater Victoria.","Members can book a free weight room orientation at Juan de Fuca.","The page does not list a dollar amount or discount rate.","A lost card costs $5 plus tax to replace." ]},"steps":["Fill in one application per family","Gather proof of residency and your Notice of Assessment","Drop off the form at reception at the Juan de Fuca Recreation Centre, 1767 Island Highway, Victoria","Have your picture taken for your LIFE card" ],"documents":["Current proof of residency, such as a utility bill, rental agreement or government ID","A 2024 or 2025 Notice of Assessment","Newcomers: official travel documents for each family member in the first year" ],"tips":["A separate form exists for youth without family support.","An adjudicator form is also on the page.","Replacement cards lose 4 visits a month from January up to the replacement date." ],"phone":"250-478-8384"}},{"id":"courtenay-comox-rap-leap","name":"Recreation Access Program and LEAP (Comox Valley)","level":"Courtenay","category":"Recreation","amount":"52 free drop-ins plus program discounts","summary":"LEAP gives Comox Valley residents with lower incomes 52 free drop-in visits a year and a $350 subsidy per family member. Courtenay residents also get RAP discounts on registered programs.","note":"RAP is for Courtenay residents only; LEAP is regional.","requires":["bc","courtenayArea","courtenayComoxRapLeapRoute" ],"eligibility":{"mode":"all","items":["You live in the Comox Valley","Your household income is within the Statistics Canada after-tax low-income measure (LIM-AT)" ],"note":"RAP is for City of Courtenay residents; other Comox Valley residents use LEAP."},"applyText":"See RAP and LEAP details","applyUrl":"https://courtenay.ca/EN/main/community/recreation/recreation-access.html","source":"https://courtenay.ca/EN/main/community/recreation/recreation-access.html","detail":{"aboutList":{"lead":"One application covers both programs for lower-income Comox Valley residents.","items":["LEAP drop-in visits work at participating Comox Valley recreation centres.","LEAP: a $350 subsidy per family member for registered programs.","RAP for Courtenay residents: children get 75% off, up to $450 a year.","RAP: youth get 75% off, up to $400 a year.","RAP: adults get 50% off, up to $350 a year." ]},"steps":["Download the combined Recreation Access and LEAP 2026 application form","Complete it","Take it to the Lewis or Florence Filberg centre with your documents","Wait for staff to contact you when your recreation cards are ready" ],"documents":["Proof of Comox Valley residency, such as a utility bill or rental receipt","A B.C. Services Card for you and each family member applying" ],"tips":["Drop-ins include swimming, fitness, the Wellness Centre, parent and tot programs, The LINC Youth Centre and skating.","A program summary sheet is on the page." ],"phone":"250-338-1000"}},{"id":"cranbrook-leisure-access","name":"Leisure Access Program (Cranbrook)","level":"Cranbrook","category":"Recreation","amount":"75% off swim rates and free transit","summary":"The Leisure Access Program gives Cranbrook residents with limited income 75% off regular swim rates and free transit passes. Children under seven swim free with an adult.","note":"Transit passes are handed out monthly, cannot be transferred and are not replaced if lost or stolen. Benefits last one year, then you must re-apply.","requires":["bc","cranbrook","cranbrookLeisureAccessRoute" ],"eligibility":{"mode":"all","items":["You live in Cranbrook","Your household income is at or below the limit for your family size" ],"note":"Limits run from $20,848 for 1 person to $55,172 for 7 people; a family of 4 is $38,740."},"applyText":"See Leisure Access Program details","applyUrl":"https://cranbrook.ca/our-city/city-departments/leisure-services/services/leisure-access-program","source":"https://cranbrook.ca/our-city/city-departments/leisure-services/services/leisure-access-program","detail":{"aboutList":{"lead":"The program lowers swim and transit costs.","items":["75% off regular swim rates for public swims, Aquafit and joint mobility classes.","Free public swims for children under seven, with an adult.","Free transit access through monthly transit passes." ]},"steps":["Check your family size against the income chart","Contact one of the four adjudicating agencies listed on the page","Meet the adjudicator, who checks your information and fills out your application","Wait about a week, then book an appointment with Recreation & Culture to register","Show residency and ID at that appointment" ],"documents":["Government-issued photo ID with your current address","Proof of address in one adult's name, such as a utility bill, bank statement or rental contract","Notice of Assessment or T1 General for each adult, or a Release of Information from MSDSI","Canada Child Benefit notice if children are on the application" ],"tips":["The adjudicators are Salvation Army, Community Connections Society, Interior Health Mental Health Programs and MCFD.","Release of Information forms are at Service BC, 101-100 Cranbrook Street N.","If you do not qualify, check the pool schedule for Free Family Swims." ],"phone":"250-489-0220"}},{"id":"duncan-leisure-access","name":"Leisure Access Program (Duncan)","level":"Duncan","category":"Recreation","amount":"Annual drop-in access","summary":"The Leisure Access Program gives economically disadvantaged residents annual access to drop-in programs at the Cowichan Aquatic Centre and Fuller Lake Arena. City of Duncan residents can apply.","note":"North Cowichan runs the program for several areas, including the City of Duncan. The page gives no dollar value for the access.","requires":["bc","duncan","duncanLeisureAccessRoute" ],"eligibility":{"mode":"all","items":["You live in the City of Duncan or another listed area","Your gross household income is under the cutoff for your household size" ],"note":"Cutoffs run from $27,308 for 1 person to $72,268 for 7 or more; a household of 4 is $50,744."},"applyText":"Apply for the Leisure Access Program","applyUrl":"https://www.northcowichan.ca/form/leisure-access-program-application","source":"https://www.northcowichan.ca/form/leisure-access-program-application","detail":{"aboutList":{"lead":"The program covers drop-in use of two Cowichan area facilities for lower-income households.","items":["Open to residents of North Cowichan, the CVRD, Duncan, Cowichan Tribes Reserve Lands and Ladysmith." ]},"steps":["Fill in the online application","List every person in your household","Upload photo ID and your 2025 Notice of Assessment, or use an agency referral","Submit the form" ],"documents":["Current government-issued photo ID for each applicant over 18, with a matching address","2025 Notice of Assessment, line 15000","Or a referral completed by a listed agency, with its stamp or business card" ],"tips":["Total gross household income means all income before taxes from every household member.","Referral agencies are MCFD, Ministry of Housing and Social Development, Community Living BC, Cowichan Valley Youth Services and Cowichan Tribes Social Development.","Passes can be cancelled for breaking facility rules or the Code of Conduct." ]}},{"id":"mission-play-pass","name":"PLAY Pass (Mission)","level":"Mission","category":"Recreation","amount":"Free Leisure Centre admissions","summary":"The PLAY Pass gives free admissions to the Mission Leisure Centre. You qualify with a low income or by being on income assistance. There is a small admin fee.","note":"The fee is $5 for an individual and $10 for a family. Processing can take up to three weeks.","requires":["bc","mission","missionPlayPassRoute" ],"eligibility":{"mode":"all","items":["You have lived in Mission for at least 3 months","Your income is at or below the CRA low income thresholds, or you get Income Assistance" ],"note":"Income Assistance means the provincial ministry or the Federal Social Development Program."},"applyText":"Apply for a PLAY Pass","applyUrl":"https://mission.ca/playpass","source":"https://www.mission.ca/node/1114","detail":{"aboutList":{"lead":"The PLAY Pass removes the entry cost at the Leisure Centre for lower-income residents.","items":["Free admissions to the Leisure Centre.","Based on the CRA low income threshold or income assistance.","The page does not say how many free visits you get." ]},"steps":["Apply online at mission.ca/playpass or in person at the Leisure Centre","Pay the admin fee when your application is approved","Wait up to three weeks for processing" ],"documents":[ ],"tips":["The page points to a more information link for the full rules." ]}},{"id":"penticton-life","name":"LIFE Program (Penticton)","level":"Penticton","category":"Recreation","amount":"Free and low-cost recreation","summary":"The LIFE program gives free and low-cost recreation at the Penticton Community Centre. It is for Penticton residents with a limited family income.","note":"The page does not list an income limit or the exact discount. Check the LIFE information form or ask at the Community Centre.","requires":["bc","penticton","pentictonLifeRoute" ],"eligibility":{"mode":"all","items":["You live in Penticton","Your family income is limited" ],"note":"The page gives no income amount, so the form decides."},"applyText":"See LIFE program details","applyUrl":"https://www.penticton.ca/node/71","source":"https://www.penticton.ca/node/71","detail":{"aboutList":{"lead":"LIFE lowers the cost of recreation.","items":["It is for residents of Penticton on a limited family income.","The LIFE Pass Information Form and Application Form are online." ]},"steps":["Read the LIFE Pass Information Form","Fill in the application form","Return it with all required documents to the Community Centre at 325 Power Street" ],"documents":["All documents the application form asks for" ],"tips":["You can pick up a paper form at the Community Centre." ]}},{"id":"penticton-access-pass","name":"Access Pass (Penticton)","level":"Penticton","category":"Recreation","amount":"25% off fitness room and pool passes","summary":"The Access Pass gives 25% off passes to the fitness room, pool or both. It is for people with a permanent cognitive or physical disability.","note":"The discount also applies to promotional deals. It covers 10-ticket, 1, 3, 6 and 12 month passes.","requires":["bc","penticton","pentictonAccessPassRoute" ],"eligibility":{"mode":"all","items":["You have a permanent cognitive or physical disability" ]},"applyText":"See Access Pass details","applyUrl":"https://www.penticton.ca/node/71","source":"https://www.penticton.ca/node/71","detail":{"aboutList":{"lead":"Access Pass holders get a lower price on recreation passes.","items":["The discount is 25% off 10-ticket passes.","It works for the fitness room, the pool, or the combined pass." ]},"steps":["Download the Access Pass application form","Complete it","Follow the form's instructions for where to send it" ],"documents":["The completed Access Pass application form" ],"tips":["The page links to more information with the form." ]}},{"id":"pitt-meadows-fee-subsidy","name":"Program and Admission Fee Subsidy (Pitt Meadows)","level":"Pitt Meadows","category":"Recreation","amount":"Discounted program and admission fees for one year","summary":"Pitt Meadows residents with a low income can get discounted recreation program and admission fees for one year. You pay part of each fee.","note":"The policy does not state the discount amount. Temporary residents, including people on study or work permits, are excluded.","requires":["bc","pittMeadows","pittMeadowsFeeSubsidyRoute" ],"eligibility":{"mode":"all","items":["You live in Pitt Meadows","Your income is at or below the federal low-income cut-off","Your documents show at least $5,000 of income" ],"note":"Visitors and people on a study or work permit are excluded."},"applyText":"See the subsidy policy","applyUrl":"https://www.pittmeadows.ca/media/5925","source":"https://www.pittmeadows.ca/media/5925","detail":{"aboutList":{"lead":"Council Policy C083 sets up a fee subsidy for local residents who cannot afford full fees.","items":["It covers program fees and admission fees.","Approval lasts one year, and you can reapply each year.","Everyone still pays a portion of the fee." ]},"steps":["Gather proof that you live in Pitt Meadows","Gather proof that your income meets the cut-off","Complete the Fee Subsidy Application Form","Reapply each year with the same documents" ],"documents":["Proof of local residence","Income documents showing you meet the cut-off and have at least $5,000 of income" ],"tips":["Business class immigrants, investors and entrepreneurs are also excluded." ]}},{"id":"port-moody-leisure-access","name":"Leisure Access Program (Port Moody)","level":"Port Moody","category":"Recreation","amount":"50% off admissions, fitness passes and some programs","summary":"Port Moody residents in financial need get 50% off admissions, fitness passes and some programs. The card lasts up to one year.","note":"Your family income must fall between a minimum and a maximum that depend on family size. Free skate and helmet rentals are included.","requires":["bc","portMoody","portMoodyLeisureAccessRoute" ],"eligibility":{"mode":"all","items":["You live in Port Moody","Your family income is above the minimum and below the maximum for your family size" ],"note":"For one person, income must be from $5,000 to $23,861."},"applyText":"See the application form","applyUrl":"https://www.portmoody.ca/media/pybmlml1/leisure-access-application-form.pdf","source":"https://www.portmoody.ca/media/pybmlml1/leisure-access-application-form.pdf","detail":{"aboutList":{"lead":"The Leisure Access Card gives half-price recreation for the whole family.","items":["50% off single drop-ins, fitness passes and skating or aquatics passes.","50% off up to four registered programs per family member each year.","50% off up to two weeks of all-day summer camp per person.","Free skate and helmet rentals." ]},"steps":["Complete the Leisure Access application form","Attach the checklist documents","Take it to the Recreation Complex or Kyle Centre","Have a photo taken for each family member","Reapply each year, at least a month before expiry" ],"documents":["Government photo ID","Utility bill in an adult's name","GST credit notice","Child benefit notices if you have dependents","Cheque stub from your income source","Notice of Assessment for each income earner" ],"tips":["Private lessons and party packages are not included.","Students living at home must include their family's income." ],"time":"Valid up to one year"}},{"id":"prince-rupert-recreation-access","name":"Recreation Access Program (Prince Rupert)","level":"Prince Rupert","category":"Recreation","amount":"90% off for children and youth, 50% off for adults","summary":"Prince Rupert subsidizes recreation fees by 90% for children and youth and 50% for adults. Each eligible family member also gets 50 free admissions a year.","note":"Funding is first come, first served until the budget is used. Eligibility is based only on financial need.","requires":["bc","princeRupert","princeRupertRecreationAccessRoute" ],"eligibility":{"mode":"any","items":["You get a named provincial benefit such as disability assistance, social assistance or a Seniors Supplement","Your tax and benefit documents show financial need" ],"note":"You also need photo ID and proof you live in Prince Rupert."},"applyText":"Apply for the Recreation Access Program","applyUrl":"https://www.princerupert.ca/node/988","source":"https://www.princerupert.ca/node/988","detail":{"aboutList":{"lead":"The program helps people in need use the Rec Complex at a lower cost.","items":["The subsidy works toward memberships, visit passes or registered programs.","The 50 free admissions can be used for the gymnasium, swimming or skating.","Approval lasts one year and is reviewed each year." ]},"steps":["Check that you can show proof of financial assistance","Get a referral letter if you need one","Fill in the form, on paper or online","Attach your documents","Call to book an intake appointment if you want help" ],"documents":["Photo ID for all adults","Proof you live in Prince Rupert","Proof of assistance, or a Notice of Assessment for all adults and a Child Tax Benefit notice for dependents" ],"tips":["Applications are kept confidential.","A missed program with no cancellation may affect later subsidy requests." ],"phone":"(250) 624 6707"}},{"id":"quesnel-leisure-access","name":"Leisure Access Card (Quesnel)","level":"Quesnel","category":"Recreation","amount":"50% off swimming and skating, 25% off programs","summary":"Quesnel gives 50% off public swimming and skating admissions and 25% off programs. It is for people on income assistance or with a low household income.","note":"The card is valid for one year from the day the application is accepted. Show both your Resident Card and your Leisure Access Card.","requires":["bc","quesnel","quesnelLeisureAccessRoute" ],"eligibility":{"mode":"any","items":["You get income assistance from the provincial ministry","Your household income is at or below the limit for your family size" ],"note":"The limit is $24,486 for one person and $64,797 for seven or more."},"applyText":"Apply for the Leisure Access Card","applyUrl":"https://www.quesnel.ca/node/4489","source":"https://www.quesnel.ca/node/4489","detail":{"aboutList":{"lead":"The card lowers costs at the Arts and Recreation Centre and Quesnel Arenas.","items":["The swimming and skating discount is for children and adults.","25% off programs at the Arts and Recreation Centre and the arenas." ]},"steps":["Complete the application form","Have proof of financial need ready","Submit the form with your proof","Renew with a new application when the card is about to expire" ],"documents":["A signed Release of Personal Information form, or your latest Notice of Assessment","A Seniors Supplement card or a current Employment Insurance form also works" ],"tips":["New applicants and renewals both fill in a new application.","The program is paid for by North Cariboo Parks and Recreation taxes." ]}},{"id":"squamish-recreation-access","name":"Recreation Access Program (Squamish)","level":"Squamish","category":"Recreation","amount":"50% off recreation services and registered programs","summary":"Squamish residents in financial need get 50% off recreation services and registered programs. The card is valid for one year.","note":"Gross household income must be under the limit for your size (from $26,570 for one person, 2024 form). The form also mentions a minimum; ask the District.","requires":["bc","squamish","squamishRecreationAccessRoute" ],"eligibility":{"mode":"all","items":["You live in the District of Squamish","Your household income is under the limit for your household size","You have the original required documents" ],"note":"The page lists limits from $26,570 for one person to $70,298 for seven."},"applyText":"See the application form","applyUrl":"https://squamish.ca/assets/000-Recreation-Services/000_Forms/RAP-updated-form_-2024.pdf","source":"https://squamish.ca/assets/000-Recreation-Services/000_Forms/RAP-updated-form_-2024.pdf","detail":{"aboutList":{"lead":"The Recreation Access Card lowers the cost of recreation for households in need.","items":[ ]},"steps":["Check the self-assessment on the form","Complete the application form","Bring it with your documents to Brennan Park Recreation Centre" ],"documents":["Government-issued ID for the main applicant","For each adult, a Notice of Assessment, proof of income, or an income assistance or disability statement","Proof of residency such as a lease or Canada Child Benefit notice" ],"tips":["Approved agencies can take your application, including PearlSpace and Sea to Sky Community Services.","Staff can help if you lack the documents." ],"phone":"604.898.3604"}},{"id":"terrace-affordable-recreation-access","name":"Affordable Recreation Access Program (Terrace)","level":"Terrace","category":"Recreation","amount":"50% off drop-in fees and short memberships","summary":"Terrace gives a discount card for 50% off drop-in fees and short memberships. It is for people who get certain provincial or federal assistance or disability benefits.","note":"Fitness class registration, rentals, swimming lessons and other registered activities are not included.","requires":["bc","terrace","terraceAffordableRecreationAccessRoute" ],"eligibility":{"mode":"any","items":["You get regular income assistance, PWD or PPMB benefits","You get Canada Pension Plan Disability","You get the Guaranteed Income Supplement or the Child Disability Benefit" ]},"applyText":"See the program details","applyUrl":"https://www.terrace.ca/sites/default/files/2026-06/Affordable%20Recreation%20Access%20Program%20-%20Revised%20June%2022%202026.pdf","source":"https://www.terrace.ca/sites/default/files/2026-06/Affordable%20Recreation%20Access%20Program%20-%20Revised%20June%2022%202026.pdf","detail":{"aboutList":{"lead":"A discount card lowers the price of drop-in visits and short memberships.","items":["It gives 50% off drop-in fees.","It covers 10-visit, 1 month and 3 month memberships.","Buy memberships before the card expires." ]},"steps":["Pick up the application and letter at the Terrace and District Aquatic Centre","Complete the form","Take it to Service BC or Service Canada to verify your benefits","Bring the paperwork back to the Aquatic Centre" ],"documents":["The completed application form","A Release of Personal Information form (HR0095) for provincial benefits","The standard benefit letter for CPP Disability, the Guaranteed Income Supplement or the Child Disability Benefit","Identification" ],"tips":["Cards expire on a schedule: every six months for some benefits and yearly for PWD.","People on regular income assistance get cards for up to 3 dependent children too." ],"phone":"250-615-3030"}},{"id":"white-rock-leisure-access","name":"Leisure Access Program (White Rock)","level":"White Rock","category":"Recreation","amount":"50% off programs and memberships, up to $300 a year","summary":"White Rock gives low-income residents 50% off eligible recreation programs or memberships, up to $300 a year. Skating at Centennial Arena is free.","note":"South Surrey residents are not eligible. They can apply to the City of Surrey program instead.","requires":["bc","whiteRock","whiteRockLeisureAccessRoute" ],"eligibility":{"mode":"all","items":["You are a permanent resident of the City of White Rock","Your family income is at or below the limit for your family size" ],"note":"The limit is $26,926 for one person and $64,000 for six."},"applyText":"Apply for the Leisure Access Program","applyUrl":"https://www.whiterockcity.ca/825/Leisure-Access-Program","source":"https://www.whiterockcity.ca/825/Leisure-Access-Program","detail":{"aboutList":{"lead":"The program helps residents join recreation when money is tight.","items":["It gives 50% off eligible programs or memberships, up to $300 per year.","It includes free public skating at Centennial Arena.","Annual and 20-session passes for Grandview Heights Aquatic Centre and South Surrey Indoor Pool are 50% off." ]},"steps":["Download the application form","Include the total income of all adults in the household","Complete one application per family","Contact Recreation and Culture to arrange your submission" ],"documents":["The completed application form and the documents it requires" ],"tips":["Total income for all adults in the household must be included." ],"phone":"604-541-2199"}},{"id":"dawson-creek-leisure-access","name":"Leisure Access Program (Dawson Creek)","level":"Dawson Creek","category":"Recreation","amount":"Funding toward drop-in and program fees; amount varies","summary":"Funding for low-income Dawson Creek residents to pay for classes, drop-ins and events. You may get a drop-in punch card or credit toward a registered program. The amount depends on limited yearly funds.","note":"Funding is not guaranteed, and the amount can be small. New applicants are considered before repeat applicants. Applications are considered on the first day of each month.","requires":["bc","dawsonCreek","dawsonCreekLeisureAccessRoute" ],"eligibility":{"mode":"all","items":["You are a permanent resident living within city boundaries for at least three months","Your family income is at or below the Statistics Canada Low-Income Cut-Off" ]},"applyText":"Get the application form","applyUrl":"https://www.dawsoncreek.ca/parks-recreation/recreation-programs/leisure-access-and-funding-assistance/","source":"https://www.dawsoncreek.ca/parks-recreation/recreation-programs/leisure-access-and-funding-assistance/","detail":{"aboutList":{"lead":"Help paying for classes, drop-ins and events.","items":["Approved drop-in funding is used with a punch card at the front desk.","For registered programs, you tell staff to use your funding on the fee.","If you are approved for $30 on a $50 class, you pay the other $20." ]},"steps":["Print the individual or group form, or pick one up at the Kenn Borek Aquatic Centre or Culture & Recreation front desk","Fill out the main applicant section","Ask a Trusted Partner to fill out the bottom section","Email the form or drop it off at the aquatic centre or Kin Arena" ],"documents":["The completed application form","The bottom section completed by a Trusted Partner, verifying income and residency" ],"tips":["A Trusted Partner is a social service agency, government agency or non-profit you work with.","Applicants are told by mail, up to three weeks after the deadline.","You can apply again, but funding is limited each calendar year." ],"time":"Up to three weeks after the deadline","phone":"250-784-3604"}},{"id":"langley-leisure-access-grant","name":"Leisure Access Grant (City of Langley)","level":"Langley","category":"Recreation","amount":"25% to 75% off a program or pass","summary":"Low-income City of Langley residents can get a discount on a City program or pass, or an aquatic pass to the indoor pools in the area. If approved, each family member living permanently in the household gets the discount.","note":"Temporary residents, including people on study and work permits, do not qualify. The aquatic pass option is for adults and seniors only. The City replies within three weeks.","requires":["bc","langley","langleyLeisureAccessGrantRoute" ],"eligibility":{"mode":"all","items":["You are a low-income resident of the City of Langley","You meet the Leisure Access Program income requirements","You are not a temporary resident" ],"note":"Temporary residents include people on study and work permits."},"applyText":"Apply for the Leisure Access Grant","applyUrl":"https://langleycity.ca/recreation-culture/recreation/admission-rates-passes-and-financial-assistance","source":"https://langleycity.ca/recreation-culture/recreation/admission-rates-passes-and-financial-assistance","detail":{"aboutList":{"lead":"The grant lowers the cost of recreation.","items":["The discount is 25% to 75%.","It covers a City of Langley program or pass.","Adults and seniors can choose an aquatic pass instead." ]},"steps":["Complete the Leisure Access Grant application form","Attach the required documents","Submit it at a recreation facility, or email recreation@langleycity.ca","Wait to be contacted" ],"documents":["Proof of address, such as a recent utility bill in your name","A pay stub from your employer","A Notice of Assessment for all income earners in the family" ],"tips":["The application cannot be processed without the documents.","The page does not list the income limits. Ask the City about them." ],"time":"Contact within three weeks of submission","phone":"604.514.2940"}},{"id":"nelson-rdck-leisure-access","name":"Leisure Access Program (RDCK, Nelson)","level":"Nelson","category":"Recreation","amount":"$100 per adult or $150 per child credit a year","summary":"The Regional District of Central Kootenay gives a yearly subsidy credit to people in financial hardship. It gives 50% off adult and 75% off youth admissions and memberships, and 50% off programs. Nelson residents can apply.","note":"Apply with a Notice of Assessment or proof of government assistance. Assistance recipients get a second credit of up to $200 for adults and $300 for youth. The pass expires every May 31.","requires":["bc","nelson","nelsonRdckLeisureAccessRoute" ],"eligibility":{"mode":"all","items":["You live in the Regional District of Central Kootenay, which includes the City of Nelson","You are 19 or older, or a family applying together","You show proof of residency and one qualifying route" ],"note":"Routes are listed assistance, income below the Low Income Measure, or a social service letter."},"applyText":"Open the application form","applyUrl":"https://rdck.jotform.com/260834508820255","source":"https://rdck.jotform.com/260834508820255","detail":{"aboutList":{"lead":"A subsidy credit used for RDCK recreation.","items":["Admissions and memberships are 50% off for adults and 75% off for youth.","Programs are 50% off the advertised rate.","CHEER events have 100% subsidized admission.","Discounts apply only while you have credit left." ]},"steps":["Complete the online application form","Upload ID or a household bill","Upload your proof of assistance or Notice of Assessment","Wait for approval, then show your card at each purchase" ],"documents":["ID or a recent household bill showing your name and address","A confirmation letter for the assistance you get, or a Notice of Assessment","Or a letter from a pre-approved social service organization" ],"tips":["Check your junk folder for the approval email.","The page recommends reapplying at least three weeks before May 31. The 2026 to 2027 form is on the page.","Expired passes get full rates, and fees are not refunded later." ],"time":"Up to three weeks"}},{"id":"port-coquitlam-financial-assistance","name":"Financial Assistance for Recreation (Port Coquitlam)","level":"Port Coquitlam","category":"Recreation","amount":"One City Pass plus a $200 adult or $500 child scholarship","summary":"Approved Port Coquitlam residents get a One City Pass for the calendar year. They can also take a scholarship of $200 per adult or $500 per child or youth. The scholarship gives a 75% discount on registered program fees.","note":"The scholarship cannot be used on programs you already registered for.","requires":["bc","portCoquitlam","portCoquitlamFinancialAssistanceRoute" ],"eligibility":{"mode":"all","items":["You are a Port Coquitlam resident","Your income is within the LICO table, or a Community Partner or adjudicator refers you" ],"note":"Family means a maximum of 2 adults plus children or dependents in the home."},"applyText":"Apply online","applyUrl":"https://www.portcoquitlam.ca/node/949","source":"https://www.portcoquitlam.ca/node/949","detail":{"aboutList":{"lead":"A pass and an optional scholarship for registered programs.","items":["A One City Pass is valid for each approved family member.","The scholarship is $200 per adult and $500 per child or youth aged 0 to 18.","You pay the other 25% of the program fee.","Specialty programs, personal training, rentals and events are not included." ]},"steps":["Fill out the online form, or download the paper form","Provide proof of residency","Provide a Proof of Income Statement or a Community Partner Reference Form","Submit by email, mail or drop-off" ],"documents":["A bill from the past 90 days showing your name and Port Coquitlam address","A CRA Proof of Income Statement for adults in the family","Or the Community Partner Reference Form" ],"tips":["A Notice of Assessment, T1 or T4 cannot replace the Proof of Income Statement.","January is busy. Staff reply within 10 to 14 business days.","The income limit is $31,264 or less for 1 person." ],"time":"10 to 14 business days","phone":"604-927-5371"}},{"id":"west-vancouver-recreation-financial-assistance","name":"Recreation Financial Assistance Program (West Vancouver)","level":"West Vancouver","category":"Recreation","amount":"50% off FitPasses and activities; some memberships free","summary":"West Vancouver residents with low income and no significant savings or assets can get 50% off FitPasses and activities. Enhance West Van and Seniors' Activity Centre memberships are 100% subsidized.","note":"FitPass subsidy is up to $362 per subsidy year, and activities up to $400. Birthday parties, personal training, private lessons and events are not eligible; other exclusions may apply. Review can take two to six weeks.","requires":["bc","westVancouver","westVancouverRecreationFinancialAssistanceRoute" ],"eligibility":{"mode":"all","items":["You are a West Vancouver resident, with proof for all family members","You are low income without significant savings or assets" ],"note":"Details are in the Qualifying for Financial Assistance handout."},"applyText":"Apply for RFAP","applyUrl":"https://westvancouver.ca/parks-recreation/recreation-programs-services/financial-assistance-support","source":"https://westvancouver.ca/parks-recreation/recreation-programs-services/financial-assistance-support","detail":{"aboutList":{"lead":"A subsidy on community centre recreation.","items":["50% off FitPasses, up to a maximum per subsidy year.","50% off activities, up to a maximum per subsidy year." ]},"steps":["Read the information handout to confirm eligibility","Create a recreation account at activewestvanrec","Complete and sign the RFAP application form","Drop off the sealed package at the West Vancouver Community Centre front desk","Register for an RFAP interview at drop-off" ],"documents":["The signed and dated application form","Supporting documents listed in the handout, including recent tax information","Copies of EI documents, if you received EI" ],"tips":["Interview registration is not available online.","Do not email supporting documents.","Documents not collected within six weeks of your interview are shredded." ],"time":"Two to six weeks to review","phone":"604-925-7279"}},{"id":"bc-csil","name":"Choice in Supports for Independent Living (CSIL)","level":"British Columbia","category":"Home support","amount":"Monthly funds from your health authority; minimum $38.19 an hour (April 1, 2024)","summary":"Your health authority sends you money each month so you can hire and manage your own home support workers. For people with a significant physical disability who want more control.","note":"You pay a daily rate based on income, and no more than $300 a month if you or your spouse has earned income. You pay no daily rate if you get GIS, support and shelter allowance, or War Veterans Allowance.","requires":["bc","bcCsilRoute" ],"eligibility":{"mode":"all","items":["You are assessed as needing home support services as part of your care plan.","You are assessed as having high physical care needs and a physical disability, and are medically stable.","Your assessed needs can be met within CSIL, within available resources.","You agree to pay the assessed client rate.","You can safely manage CSIL, or a support group or representative acts as your employer." ],"note":"You must also meet the general eligibility criteria for home and community care services."},"applyText":"Contact your health authority","applyUrl":"https://www2.gov.bc.ca/gov/content/health/accessing-health-care/home-community-care/care-options-and-cost/choice-in-supports-for-independent-living","source":"https://www2.gov.bc.ca/gov/content/health/accessing-health-care/home-community-care/care-options-and-cost/choice-in-supports-for-independent-living","detail":{"aboutList":{"lead":"CSIL gives you control over who you hire, when services happen and how tasks are done.","items":["You become the employer and manage hiring, supervising and how the funds are spent.","Funding is the hourly rate times the home support hours your assessment says you need each month.","Your monthly contribution is taken out of the funding you receive." ]},"steps":["Contact your health authority's home and community care office, or ask a health care professional to refer you.","Have your health authority assess your care needs and your finances.","Agree on funding in a written agreement between you and the health authority.","Hire and supervise your own care providers and manage the funds." ],"documents":["The page does not list documents. Ask your responsible assessor what to bring." ],"tips":["Read the CSIL Online Workbook to see what being an employer involves.","Tell your responsible assessor about any earned income during your financial assessment.","If the daily rate would cause serious financial hardship, you can ask for a temporary reduction.","If you cannot manage CSIL alone, a client support group or a representative can act as employer." ],"time":"Not published"}},{"id":"bc-family-benefit","name":"B.C. Family Benefit","level":"British Columbia","category":"Money (for parents)","amount":"Up to $1,750 first child, $1,100 second child, $900 each added child a year (July 2026 to June 2027)","summary":"A tax-free monthly payment for families with children under 18. The CRA pays it together with the Canada child benefit and works out the amount from your tax return.","note":"Amounts are for July 2026 to June 2027, based on 2025 income. Low-income single parents may get up to $500 more a year. Shared custody gets half the amount.","requires":["bc","child","bcFamilyBenefitRoute" ],"eligibility":{"mode":"all","items":["Your family has a child under 18.","Your child is registered for the Canada child benefit.","You (and your spouse or common-law partner) file a T1 income tax return." ],"note":"The amount depends on your family makeup and your adjusted family net income."},"applyText":"Register for the Canada child benefit","applyUrl":"https://www2.gov.bc.ca/gov/content/family-social-supports/affordability/family-benefit","source":"https://www2.gov.bc.ca/gov/content/family-social-supports/affordability/family-benefit","detail":{"aboutList":{"lead":"The CRA calculates the amount automatically from the tax returns you have filed.","items":["You get the maximum if 2025 adjusted family net income is less than $30,176.","Between $30,176 and $96,562 you get a reduced amount of at least $775, $750 or $725 per child.","Over $96,562 the amounts are reduced by 4 percent of the extra income until they reach zero.","The monthly payment is the annual amount divided by 12." ]},"steps":["File your T1 tax return, and your spouse or partner files theirs.","If your child is not registered for the Canada child benefit, apply for it through the CRA.","The CRA uses that registration to decide your eligibility and pays you each month." ],"documents":["Your T1 Income Tax and Benefit Return" ],"tips":["Use the federal child and family benefits calculator to estimate your monthly amount.","If you move outside B.C., tell the CRA quickly to avoid an overpayment you would have to repay.","From July 2027 a disability supplement will be paid with this benefit for eligible children." ],"time":"Not published"}},{"id":"bc-home-support","name":"Home Support (Home and Community Care)","level":"British Columbia","category":"Home support","amount":"Subsidized service; daily rate based on income, and no more than $300 a month with earned income","summary":"Publicly subsidized help at home from community health workers with personal care such as bathing, dressing and mobility. It can also give a caregiver a break.","note":"Short-term care may not need the three-month residency. You pay no daily rate if you get GIS, support or shelter allowance, or a War Veterans Allowance.","requires":["bc","bcHomeSupportRoute" ],"eligibility":{"mode":"all","items":["A health authority professional assessed you as needing personal assistance or respite for your caregiver.","You agree to pay the assessed client rate." ],"note":"You must also meet the general eligibility criteria for home and community care services."},"applyText":"Contact your health authority","applyUrl":"https://www2.gov.bc.ca/gov/content/health/accessing-health-care/home-community-care/care-options-and-cost/home-support","source":"https://www2.gov.bc.ca/gov/content/health/accessing-health-care/home-community-care/care-options-and-cost/home-support","detail":{"aboutList":{"lead":"Home support helps you stay independent and live at home as long as possible.","items":["Help covers mobility, nutrition, lifts and transfers, bathing and dressing, cueing, grooming and toileting.","It may also include clean-up, laundry of soiled bedding or clothing, and meal preparation.","Hours are set by your health, your supports, your care goals and the risk to staff.","It is usually provided over months or years, or short term after a hospital discharge." ]},"steps":["Contact the home and community care office of your health authority, or ask a health care professional to refer you.","Have a health authority professional do a clinical assessment of your need.","Complete the financial assessment with your responsible assessor.","Confirm that you accept the assessed client rate." ],"documents":["The page does not list documents. Ask your health authority what to bring." ],"tips":["Tell your responsible assessor about any earned income when you do your financial assessment.","If the daily rate would cause serious financial hardship, you can ask for a temporary reduction.","If you and your spouse both get home support, you are both assessed, but only one is charged per service day.","If your assessed daily rate is more than the actual cost, you pay no more than the actual cost." ],"time":"Not published"}},{"id":"bc-income-assistance","name":"Income Assistance","level":"British Columbia","category":"Income support","amount":"Monthly payment; the amount is not stated on this page","summary":"Monthly help for people in need who have no other resources, meant to support a move into work. It is a different program from disability assistance (PWD).","note":"Disability assistance (PWD) is listed separately. Income assistance asks for a three-week work search first, unless you are exempt. Some people with disabilities are exempt.","requires":["bc","age18plus","bcIncomeAssistanceRoute" ],"eligibility":{"mode":"any","items":["You are out of work or not earning enough to meet your basic needs.","You are waiting for other sources of money to arrive.","You cannot work at all.","You urgently need food, shelter or medical attention." ],"note":"You must look for and use all other income and assets before you apply."},"applyText":"Apply on My Self Serve","applyUrl":"https://www2.gov.bc.ca/gov/content/family-social-supports/income-assistance","source":"https://www2.gov.bc.ca/gov/content/family-social-supports/income-assistance","detail":{"aboutList":{"lead":"Income assistance is for people in need with no other resources.","items":["Income and disability assistance payments are issued monthly, but they are separate kinds of assistance.","This page does not state a payment amount, so check the rate tables.","The application also asks about EI or WCB benefits, outstanding warrants and sponsorship." ]},"steps":["Use My Self Serve to check your eligibility and apply, or visit your local office if you cannot apply online.","Look for work for three weeks and keep a record on the Work Search Activities form, unless you are exempt.","If you do not find a job, attend an eligibility assessment in person or by phone.","If you are eligible, you begin to receive assistance." ],"documents":["Identification for you and your family","Your Social Insurance Number (SIN)","How much you pay for rent and utilities","Your bank account balance","How much you owe on your vehicle, if you have a car","Tenancy agreement or Shelter Information form, if you rent" ],"tips":["You may skip the work search if you are fleeing an abusive spouse or relative, are 65 or older, or cannot legally work in Canada.","Single parents of a child under three, and people with a condition that prevents a work search, may also skip it.","A work search is also not needed if you or a close family member is a person with disabilities (PWD).","Not eligible but still in need? You may be able to get hardship assistance, so contact the ministry.","If you disagree with a decision, speak to a worker first, then ask for a reconsideration." ],"time":"Not published","phone":"1-866-866-0800"}},{"id":"bc-nursing-support-services","name":"Nursing Support Services (BC Children's Hospital)","level":"British Columbia","category":"Health (for children)","amount":"In-home nursing respite and school nursing support; cost not stated","summary":"Scheduled in-home nursing respite so families get a break, and trained school staff who help children with complex medical needs do their care at school.","note":"Office services run Monday to Friday, 8 a.m. to 4 p.m. For specific questions, contact your local NSS Coordinator, not the central line.","requires":["bc","child","bcNursingSupportServicesRoute" ],"eligibility":{"mode":"all","items":["You are a child or youth in B.C. with a chronic, complex medical condition.","Your care, or part of it, needs a registered nurse's knowledge, judgement and skill.","A B.C.-licensed primary physician or nurse practitioner refers you." ]},"applyText":"Ask for a referral","applyUrl":"https://www.bcchildrens.ca/clinics-services/nursing-support-services","source":"https://www.bcchildrens.ca/clinics-services/nursing-support-services","detail":{"aboutList":{"lead":"The program supports children and youth whose care needs a registered nurse's skill.","items":["It may include children with a tracheostomy, a ventilator (including BiPAP and CPAP) or a palliative diagnosis.","In-home respite is scheduled and intermittent, so families can have a break from daily medical care.","School staff are taught to help with diabetes care or tube feeds as the student builds independence.","School staff are also trained for rescue steps if a student is at risk of a seizure or adrenal crisis." ]},"steps":["Ask your child's primary physician or nurse practitioner for a referral.","The referral is for home respite, delegated care in schools, or both.","Contact your local NSS Coordinator for help with your situation." ],"documents":["A referral from your child's primary physician or nurse practitioner licensed in B.C." ],"tips":["Email nss@cw.bc.ca with general questions about the services or how to make a referral.","The central inbox and phone do not handle specific queries about your child.","Referral details are on the program's referral page." ],"time":"Not published","phone":"236-427-9250"}},{"id":"bc-ppmb","name":"Persons with Persistent Multiple Barriers (PPMB)","level":"British Columbia","category":"Income support","amount":"May bring a higher support rate and extra supplements; see the rate table","summary":"An income assistance category for people with a long-term health condition and other barriers to work. You have no job search duties, and your family may get a higher rate and extra supplements.","note":"PPMB is part of income assistance, not disability assistance (PWD). Spouses of PWD recipients cannot be assessed for it. It is not permanent, and the ministry can review it.","requires":["bc","bcPpmbRoute" ],"eligibility":{"mode":"all","items":["You get income assistance or hardship assistance.","In the Minister's opinion, your confirmed health condition seriously impedes searching for or keeping work.","The condition has lasted a year, or has happened often in the past year.","It is likely to continue for at least two more years.","You have at least one more barrier that seriously impedes you from searching for, accepting or keeping work." ],"note":"An approved health professional must confirm the health condition."},"applyText":"Ask the ministry for a PPMB application","applyUrl":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/persons-with-persistent-multiple-barriers/persons-with-persistent-multiple-barriers-topic","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/persons-with-persistent-multiple-barriers/persons-with-persistent-multiple-barriers-topic","detail":{"aboutList":{"lead":"PPMB differs from disability assistance (PWD) in who it covers and how it is assessed.","items":["PPMB is not part of the Employment and Assistance for Persons with Disabilities Act.","PPMB is assessed with its own two-part application, form HR2892.","PPMB recipients have no employability duties, but may take part on a voluntary basis.","A family with one eligible adult may get a higher support rate and an earnings exemption.","It may also get general health supplements, dental supplements and employability supports.","Barriers include homelessness now or in the past 12 months, or domestic violence in the past six months.","Others are less than Grade 12, English training needs, no basic work skills, or a criminal record.","Also counted are multiple emergency health, mental health or addiction service visits in 12 months.","Also counted are recent refugee status (within 24 months), former child in care, or another severe barrier." ]},"steps":["Ask the ministry for a PPMB application. It first checks that you are a recipient.","Complete and submit the PPMB application (HR2892).","The ministry will contact you with an eligibility decision.","If you leave assistance and reapply within 24 months, you keep your PPMB category." ],"documents":["PPMB application (HR2892), with Section 1 completed by an approved health professional" ],"tips":["Approved health professionals include a medical practitioner, nurse practitioner, registered psychologist, and registered nurse or registered psychiatric nurse.","They also include an occupational therapist, physical therapist, registered social worker, chiropractor, registered clinical counsellor and school psychologist.","The ministry looks at whether your condition limits you to part-time or sporadic work.","If you were off assistance for longer than 24 months, you may be reassessed for PPMB when you reapply." ],"time":"Not published"}},{"id":"bc-rental-assistance-program","name":"Rental Assistance Program (RAP)","level":"British Columbia","category":"Housing","amount":"Pays a share of rent above 30% of household income, up to rent ceilings and benefit maximums","summary":"Monthly help with private-market rent for low-income families with at least one dependent child. A child of any age can count if they have a disability as defined by the CRA.","note":"RAP and income or disability assistance both pay a shelter subsidy, so you cannot get both. Existing clients must reapply each year.","requires":["bc","bcRentalAssistanceProgramRoute" ],"eligibility":{"mode":"all","items":["Your total before-tax household income is $60,000 or less a year.","You have at least one dependent child, mainly supported by you.","You have less than $100,000 in assets.","You file an annual income tax return.","More than 30% of your household income goes to rent or pad rental for a home you own.","You have lived in B.C. for 12 months.","You do not get income or disability assistance, unless it ended and you only get Medical Services Only.","You do not live in subsidized housing or own shares in a co-operative.","You do not share a kitchen or bathroom with your landlord or the homeowner.","You and your family meet the program residency and citizenship rules." ],"note":"A dependent child is under 19, under 25 in full-time school, or any age with a disability under CRA rules."},"applyText":"Get a RAP application","applyUrl":"https://www.bchousing.org/housing-assistance/rental-assistance-programs/RAP","source":"https://www.bchousing.org/housing-assistance/rental-assistance-programs/RAP","detail":{"aboutList":{"lead":"RAP reimburses a percentage of the gap between your rent and 30 percent of gross income.","items":["Payments are subject to maximum rent ceilings and maximum benefit amounts.","Rent ceilings since April 2025 are $1,950 for a family of 3 or less and $2,200 for 4 or more.","Assistance is based on your previous year's income.","Assets counted include real estate, stocks, cash and business equity.","Vehicles, RESPs, RRSPs and RDSPs do not count toward the asset limit." ]},"steps":["Download the RAP application form, request one by mail, or pick one up at a BC Housing office.","Attach your supporting documents.","Submit by upload, drop-off at a BC Housing office, fax or mail.","BC Housing will contact you by mail to say if you are approved or ineligible, or need more information." ],"documents":["Proof of income: CRA consent form, or last year's T1 and Notice of Assessment","Proof of status in Canada for every household member","Proof of rent, such as a tenancy agreement","A void cheque or other direct deposit form","Proof of assets, such as bank statements","Proof of enrolment for children aged 19 to 24 in full-time school" ],"tips":["Giving CRA consent is optional, but it streamlines your application and yearly reapplication.","Send copies only. Do not send original documents.","Payments are made by direct deposit on the last working day of each month, so you need a bank account.","Rental assistance is non-taxable, but declare it on your taxes if you get more than $500 in a tax year.","If you go on income or disability assistance, tell BC Housing at once or you may owe a debt.","If CRA has not processed your tax return, you can still apply and have up to 90 days to send missing items." ],"time":"Not published","phone":"604-433-2218 or 1-800-257-7756"}},{"id":"bc-safer","name":"Shelter Aid for Elderly Renters (SAFER)","level":"British Columbia","category":"Housing","amount":"Monthly rent supplement (minimum $50 a month)","summary":"A monthly rent supplement for B.C. residents aged 60 or older with a low to moderate income who rent in the private market.","note":"You are not eligible if you or your family get income or disability assistance, unless it ended and you only get Medical Services Only. Existing clients reapply each year.","requires":["bc","age60plus","bcSaferRoute" ],"eligibility":{"mode":"all","items":["You are age 60 or older.","Your gross income is less than $3,333.34 a month or $40,000 a year.","You file an annual income tax return.","You have lived in B.C. for 12 months.","You pay more than 30% of your gross monthly household income on rent.","You and your spouse meet the Canadian citizenship requirements.","You do not live in subsidized housing, Ministry of Health-funded care, or co-op housing as a shareholder." ],"note":"If you own and live in a manufactured home, pad rental counts as rent."},"applyText":"Get a SAFER application","applyUrl":"https://www.bchousing.org/housing-assistance/rental-assistance-programs/SAFER","source":"https://www.bchousing.org/housing-assistance/rental-assistance-programs/SAFER","detail":{"aboutList":{"lead":"SAFER helps older renters in the private market pay their rent.","items":["The maximum rent ceiling as of April 2025 is $1,150 for both singles and couples.","If your rent is over the ceiling, you may not get an increase in your subsidy.","If your rent includes meals, care or personal services, rent is counted as 50% of what you pay." ]},"steps":["Download the SAFER application form, request one by mail, or pick one up at a BC Housing office.","Attach your supporting documents.","Submit by upload, drop-off, fax or mail.","BC Housing will contact you by mail to say if you are approved, ineligible or need to send more.","Each year, complete the reapplication form sent three months before your birthday." ],"documents":["Tax information: CRA consent form, or last year's tax return and Notice of Assessment","Proof of current gross monthly income, if your income has stopped or dropped","Proof of age and status in Canada for you and your spouse","Proof of rent, such as a tenancy agreement","A void cheque or other direct deposit form" ],"tips":["Send copies only. Do not include original documents.","Receiving the BC Bus Pass or Provincial Seniors Supplement does not affect SAFER, but send your T5007 slip.","Your subsidy starts the month your application is received, and is paid in arrears.","SAFER is non-taxable, but declare it on your taxes if you get more than $500 in a tax year.","If you move or your rent changes, tell the SAFER office right away." ],"time":"Not published","phone":"604-433-2218 or 1-800-257-7756"}},{"id":"bc-hearing-supplements","name":"Hearing Instruments and Alternative Hearing Assistance Supplement","level":"British Columbia","category":"Health","amount":"Up to $2,000 per hearing aid; the alternative supplement amount is in the rate table","summary":"Pays for the least expensive, appropriate hearing aids, repairs and supplies for eligible recipients who lack the money. A separate monthly supplement helps with profound hearing loss in both ears.","note":"Hearing aids and repairs are not provided in a month you get the alternative supplement. Buy only after approval, or the ministry will not accept payment responsibility.","requires":["bc","bcAssistanceStatus","hearingDisability" ],"eligibility":{"mode":"any","items":["You are a recipient who is eligible for general health supplements.","You are a hard of hearing parent of a dependent child.","You are a child under 19 in a family eligible for MSP supplementary benefits (Healthy Kids).","You are in ministry-approved training.","In the Supervisor's opinion you need one to get a job, and going without is a direct barrier.","You are registered with the CNIB and are hard of hearing.","You have a hearing impairment and are the sole homemaking support for an adult with a cognitive impairment." ],"note":"Each route also needs an assessment, prior approval, the least expensive option and no other resources."},"applyText":"Ask a hearing provider to start approval","applyUrl":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/health-supplements-and-programs/medical-equipment-hearing-instruments","source":"https://www2.gov.bc.ca/gov/content/governments/policies-for-government/bcea-policy-and-procedure-manual/health-supplements-and-programs/medical-equipment-hearing-instruments","detail":{"aboutList":{"lead":"The main program covers hearing aids, bone anchored hearing aids, cochlear implants and repairs.","items":["New purchases include one year of batteries and one-time replacement coverage paid at $300 per aid.","Repairs must cost less than replacing, and the damage must not be from misuse.","Replacement is considered if it costs less than repair, there was no misuse, and 3 years have passed.","The alternative hearing assistance supplement is a separate monthly payment.","It is for permanent profound hearing loss in both ears.","You must not be able to benefit significantly from a hearing instrument for speech comprehension.","An audiologist or hearing instrument practitioner must assess you within the last 12 months.","It is not available if you got a hearing instrument in the last 36 months, unless the loss developed since." ]},"steps":["Get a hearing assessment at the health authority hearing clinic, or the nearest hospital audiology department.","If those are unavailable, see an audiologist or registered hearing instrument practitioner. No referral is needed.","Your provider contacts Pacific Blue Cross (PBC) to start the eligibility check, before you buy anything.","The provider has 120 days to send PBC the records, and PBC makes the final decision.","Once authorized, you get a 60-day trial period.","For the alternative supplement, your hearing health professional contacts PBC, which notifies you in writing.","If denied, you can ask the ministry for a reconsideration (form HR0100)." ],"documents":["Assessment from an audiologist or a registered hearing instrument practitioner","For the alternative supplement, an assessment from the last 12 months confirming profound hearing loss in both ears","Other documents PBC asks your provider to send" ],"tips":["The ministry does not accept hearing instrument request documents. Your provider sends them straight to PBC.","You must use other resources first, such as PharmaCare, ICBC, WorkSafeBC, Veterans Affairs Canada or private insurance.","If insurance pays only part, the ministry may consider paying the rest.","The ministry is not responsible for fees for documentation for hearing instruments.","WorkBC Assistive Technology Services may help with communication and hearing devices at work." ],"time":"Not published"}},{"id":"bc-subsidized-housing","name":"Subsidized housing (BC Housing Registry) for people with disabilities","level":"British Columbia","category":"Housing","amount":"Rent is 30% of household gross income, with a minimum rent","summary":"Long-term rental housing for B.C. residents with disabilities and a low income. Rent is based on your income. Demand is high, so wait times cannot be predicted.","note":"You must be able to live independently, with supports if they are available in your community. Your application must be kept up to date or it may be cancelled.","requires":["bc","bcSubsidizedHousingRoute" ],"eligibility":{"mode":"all","items":["You live in B.C. and can live independently.","You get a recognized disability pension, or you are disabled for income tax purposes.","Your household gross income is below the Housing Income Limits (HILs).","Your household assets are under $100,000 in buildings managed by BC Housing.","Everyone in your household meets the residency rules, such as being a citizen or permanent resident." ],"note":"Non-profit and co-op providers decide for themselves whether to apply an assets limit."},"applyText":"Apply to the Housing Registry","applyUrl":"https://www.bchousing.org/housing-assistance/rental-housing/subsidized-housing","source":"https://www.bchousing.org/housing-assistance/rental-housing/subsidized-housing","detail":{"aboutList":{"lead":"This page covers subsidized housing in general. This is what it says for people with disabilities.","items":["Rent is 30% of household gross income, subject to a minimum rent based on the number of people.","Single people with disabilities can apply for bachelor and one-bedroom units.","Low-income people who need help to live independently can apply for specially modified rental homes.","Those homes are in selected subsidized housing developments.","The income limits are the Housing Income Limits, which BC Housing sets from time to time." ]},"steps":["Use Housing Listings to find buildings and see how each one takes applications.","Apply online to the Housing Registry, or download and fill in the paper form.","Send copies of your documents by upload, in person at a BC Housing office, by mail or by fax.","Also apply directly to non-profit and co-op providers that run their own lists.","Update your application about once every six months and when your details change." ],"documents":["Proof you get a recognized disability pension, or are disabled for income tax purposes","Last year's tax return showing the Disability Tax Credit, or a Canada Revenue Agency approval letter","Copies of documents only, because originals are not returned" ],"tips":["Applying to many buildings may improve your chances of getting a unit.","If you have no landlord reference, some providers may accept a professional or personal reference.","A Supplemental Form can be filled in for a serious health condition that is affected by your housing.","If BC Housing does not hear from you for over six months, your application is put on hold." ],"time":"Not published. Wait times depend on unit turnover and the needs of other households."}} ]);
